INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Slide Deck Critic that Scores Each Slide for Clarity', 'Crítico de presentaciones que puntúa cada diapositiva', 'Upload a slide deck and get a per-slide critique: it flags walls of text, vague titles, missing takeaways, and busy charts, then suggests a sharper one-line headline for each. The demo runs a real deck through it and shows red-to-green scores updating slide by slide, so a presenter sees exactly which slides to cut or fix before a pitch.', 'Subí una presentación y recibí una crítica por diapositiva: marca bloques de texto, títulos vagos, conclusiones ausentes y gráficos recargados, y sugiere un titular más claro de una línea para cada una. La demo procesa una presentación real y muestra puntajes de rojo a verde actualizándose diapositiva por diapositiva, para que el presentador sepa cuáles cortar o arreglar antes de exponer.', 'ai-ml', '6-12h', 6, 12, 'intermediate', '["llm-apps","computer-vision"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Adversarial Pitch Panel that Attacks Your Business Plan', 'Panel de pitch adversarial que ataca tu plan de negocio', 'Paste a startup one-pager and a panel of role-playing agents — a skeptical investor, a rival founder, a CFO, and a lawyer — each pokes holes from its own angle and returns the three hardest questions you''d face. The demo shows the agents debating live, then a merged list of vulnerabilities ranked by how often they came up across personas.', 'Pegá el resumen de tu startup y un panel de agentes con roles —un inversor escéptico, un fundador rival, un CFO y un abogado— cuestiona cada uno desde su ángulo y devuelve las tres preguntas más difíciles que enfrentarías. La demo muestra a los agentes debatiendo en vivo y luego una lista combinada de vulnerabilidades ordenada por cuántas veces surgió cada una entre los roles.', 'ai-ml', '6-12h', 6, 12, 'intermediate', '["agents","llm-apps"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Workout Form Checker that Counts Reps from Your Phone', 'Corrector de técnica que cuenta repes desde tu teléfono', 'Prop your phone against a wall and the app watches you do squats or push-ups, counting clean reps and calling out form breaks — knees caving, back rounding, half range of motion — with a spoken cue mid-set. The demo has a judge do five reps on camera and watch the counter and form flags react in real time without any wearable.', 'Apoyá tu teléfono contra la pared y la app te observa hacer sentadillas o flexiones, contando repeticiones limpias y avisando errores de técnica —rodillas hacia adentro, espalda curvada, rango incompleto— con una indicación hablada a mitad de la serie. La demo hace que un juez haga cinco repes ante la cámara y vea el contador y las alertas reaccionar en tiempo real sin ningún wearable.', 'ai-ml', '12-24h', 12, 24, 'intermediate', '["computer-vision","audio"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Color Palette Generator from the Mood of a Photo', 'Generador de paleta a partir del clima de una foto', 'Drop in any photo and get a designer-ready color palette plus a one-word mood label — "warm dusk", "clinical", "playful" — that explains why those colors fit. The tool surfaces accessible foreground-background pairings that pass contrast checks. A tight single-screen build that turns a reference image into usable design tokens in seconds.', 'Soltá cualquier foto y obtené una paleta de colores lista para diseño más una etiqueta de clima de una palabra —"atardecer cálido", "clínico", "juguetón"— que explica por qué esos colores encajan. La herramienta sugiere combinaciones de texto y fondo accesibles que pasan controles de contraste. Una construcción ágil de una sola pantalla que convierte una imagen de referencia en tokens de diseño usables en segundos.', 'ai-ml', '1-3h', 1, 3, 'beginner', '["computer-vision","generative"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Email Draft Coach that Predicts the Reply You''ll Get', 'Coach de correos que predice la respuesta que recibirás', 'Write an email and the tool predicts the likely response — "defensive", "will ignore", "yes but slow" — and shows which sentences trigger that reaction, then offers a rewrite aimed at the outcome you want. The demo takes a touchy work email and previews how a recipient might read it before you hit send.', 'Escribí un correo y la herramienta predice la respuesta probable —"a la defensiva", "lo ignorará", "sí pero lento"— y muestra qué frases provocan esa reacción, luego ofrece una reescritura orientada al resultado que querés. La demo toma un correo laboral delicado y muestra cómo podría leerlo el destinatario antes de enviarlo.', 'ai-ml', '3-6h', 3, 6, 'intermediate', '["nlp","prediction"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Children''s Story Generator with Consistent Characters', 'Generador de cuentos con personajes consistentes', 'Describe a hero once and the tool writes a short illustrated story where that character keeps the same face, outfit, and personality across every page — solving the usual drift where generated art forgets what the protagonist looks like. The demo types a one-line premise and flips through a finished picture book whose hero stays recognizable throughout.', 'Describí a un héroe una vez y la herramienta escribe un cuento ilustrado corto donde ese personaje mantiene la misma cara, vestimenta y personalidad en cada página, resolviendo la deriva habitual en la que el arte generado olvida cómo luce el protagonista. La demo escribe una premisa de una línea y hojea un libro ilustrado terminado cuyo héroe permanece reconocible de principio a fin.', 'ai-ml', '12-24h', 12, 24, 'advanced', '["generative","computer-vision"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Live Debate Fact-Checker that Flags Claims as They Speak', 'Verificador de debates que marca afirmaciones al hablar', 'Point it at a livestream or meeting and it transcribes speech in real time, isolates checkable factual claims, and flags each as supported, disputed, or unverifiable with a confidence bar. The demo plays a short clip and watches claims pop up in a side panel seconds after they''re spoken, turning a passive listen into an active check.', 'Apuntala a una transmisión o reunión y transcribe el habla en tiempo real, aísla afirmaciones fácticas verificables y marca cada una como respaldada, disputada o no verificable con una barra de confianza. La demo reproduce un clip corto y observa cómo las afirmaciones aparecen en un panel lateral segundos después de ser dichas, convirtiendo una escucha pasiva en una verificación activa.', 'ai-ml', '12-24h', 12, 24, 'advanced', '["nlp","audio","agents"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Handwriting-to-LaTeX Converter for Math Notes', 'Conversor de manuscrito a LaTeX para apuntes de matemática', 'Snap a photo of handwritten equations and get clean, compilable LaTeX back, with fractions, integrals, and Greek letters resolved correctly. The tool shows the rendered formula beside your photo so you can confirm it nailed the structure. A focused build that saves students hours of retyping dense math by hand.', 'Sacá una foto de ecuaciones escritas a mano y recibí LaTeX limpio y compilable, con fracciones, integrales y letras griegas resueltas correctamente. La herramienta muestra la fórmula renderizada junto a tu foto para confirmar que captó la estructura. Una construcción enfocada que le ahorra a los estudiantes horas de retipear matemática densa a mano.', 'ai-ml', '6-12h', 6, 12, 'intermediate', '["computer-vision","generative"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Grocery Demand Forecaster for a Small Cafe''s Next Week', 'Pronóstico de demanda para la próxima semana de un café', 'Feed in a cafe''s past sales and the tool forecasts how much of each item to prep next week, factoring weekday patterns, weather, and local events, then flags items at risk of waste or stockout. The demo lets a judge pick a day and see predicted demand with a confidence range, turning gut-feel ordering into a clear prep list.', 'Cargá las ventas pasadas de un café y la herramienta pronostica cuánto preparar de cada producto la próxima semana, considerando patrones por día, clima y eventos locales, y marca productos en riesgo de desperdicio o quiebre de stock. La demo deja que un juez elija un día y vea la demanda prevista con un rango de confianza, convirtiendo el pedido por intuición en una lista de preparación clara.', 'ai-ml', '12-24h', 12, 24, 'intermediate', '["prediction","recommendation"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Comic Panel Maker that Turns a Script into a Strip', 'Creador de viñetas que convierte un guion en una tira', 'Write a few lines of dialogue and the tool lays out a multi-panel comic strip with speech bubbles, character poses, and pacing that matches the beats of your script. The demo types a short joke and watches it become a clean four-panel strip you can export, leaving the art style as a knob the builder controls.', 'Escribí unas líneas de diálogo y la herramienta arma una tira cómica de varias viñetas con globos de diálogo, poses de personajes y ritmo acorde a los tiempos de tu guion. La demo escribe un chiste corto y lo ve convertirse en una tira limpia de cuatro viñetas que podés exportar, dejando el estilo artístico como una perilla que controla quien lo construye.', 'ai-ml', '6-12h', 6, 12, 'intermediate', '["generative","nlp"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Accent Coach that Visualizes Where Your Sound Drifts', 'Coach de acento que visualiza dónde tu sonido se desvía', 'Pick a target phrase, say it aloud, and the tool overlays your pronunciation against a native reference on a phoneme timeline, highlighting exactly which sounds slipped and how to reshape your mouth. The demo has you repeat a tricky word and watch the mismatch shrink across attempts, making accent practice concrete instead of guesswork.', 'Elegí una frase objetivo, decila en voz alta y la herramienta superpone tu pronunciación contra una referencia nativa en una línea de tiempo de fonemas, resaltando qué sonidos se desviaron y cómo reformar la boca. La demo te hace repetir una palabra difícil y ver cómo el desajuste se reduce entre intentos, haciendo concreta la práctica de acento en vez de adivinanza.', 'ai-ml', '12-24h', 12, 24, 'advanced', '["audio","nlp"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Dream Journal that Turns Sleepy Notes into a Painting', 'Diario de sueños que vuelve notas soñolientas en pintura', 'Mumble or type a half-remembered dream and the tool stitches the fragments into a coherent short narrative, then generates a single surreal image capturing its mood. The demo dictates a groggy voice note and produces a titled dream entry with art in one tap — a delightful, low-stakes single-feature build.', 'Murmurá o escribí un sueño a medias y la herramienta cose los fragmentos en una narrativa corta coherente, luego genera una sola imagen surreal que capta su clima. La demo dicta una nota de voz adormilada y produce una entrada de sueño con título y arte en un toque, una construcción de una sola función, encantadora y de bajo riesgo.', 'ai-ml', '3-6h', 3, 6, 'beginner', '["generative","audio"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Code Review Agent that Rewrites the Diff and Explains Why', 'Agente de revisión que reescribe el diff y explica por qué', 'Point it at a pull request and the agent reviews the diff for bugs, naming, and missed edge cases, then proposes concrete patched code with a short rationale per change — not just comments. The demo runs a real PR through it and shows suggested edits a developer can accept or reject inline, turning review into something actionable.', 'Apuntalo a un pull request y el agente revisa el diff buscando errores, nombres y casos límite olvidados, luego propone código parcheado concreto con una breve justificación por cambio, no solo comentarios. La demo procesa un PR real y muestra ediciones sugeridas que un desarrollador puede aceptar o rechazar en línea, volviendo accionable la revisión.', 'ai-ml', '12-24h', 12, 24, 'advanced', '["agents","llm-apps"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Plant Watering Predictor from a Single Soil Photo', 'Predictor de riego a partir de una foto del suelo', 'Snap a photo of your potted plant''s soil and the tool estimates moisture from surface cues — cracking, color, sheen — and predicts how many days until it needs water for that species. The demo photographs a plant and returns a simple "water in 2 days" call with the visual reasons, no sensor in the pot required.', 'Sacá una foto de la tierra de tu planta en maceta y la herramienta estima la humedad a partir de pistas de la superficie —grietas, color, brillo— y predice cuántos días faltan para regar según la especie. La demo fotografía una planta y devuelve un simple "regar en 2 días" con las razones visuales, sin necesidad de un sensor en la maceta.', 'ai-ml', '6-12h', 6, 12, 'intermediate', '["computer-vision","prediction"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Movie Recommender that Asks the Mood You''re In Tonight', 'Recomendador de cine que pregunta tu ánimo de esta noche', 'Instead of past ratings, this picker asks a few quick mood questions — "want comfort or a gut punch?", "focused or half-watching?" — and returns three films that fit tonight, each with a one-line reason. The demo answers the prompts and gets a tiny, defensible shortlist, sidestepping the endless scroll of generic recommendation feeds.', 'En vez de calificaciones pasadas, este selector hace unas preguntas rápidas de ánimo —"¿querés consuelo o un golpe al estómago?", "¿concentrado o a medias?"— y devuelve tres películas que encajan esta noche, cada una con una razón de una línea. La demo responde las preguntas y obtiene una lista corta y justificable, evitando el scroll infinito de los feeds de recomendación genéricos.', 'ai-ml', '3-6h', 3, 6, 'beginner', '["recommendation","nlp"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Meeting Agent that Drafts Follow-Up Emails to Each Person', 'Agente de reunión que redacta correos de seguimiento por persona', 'After a meeting recording, the agent figures out who owns which action item and drafts a personalized follow-up email to each attendee with their tasks, deadlines, and the relevant context — ready to review and send. The demo feeds a transcript and produces a stack of individualized drafts, turning one messy call into clear per-person accountability.', 'Tras grabar una reunión, el agente identifica quién es responsable de cada tarea y redacta un correo de seguimiento personalizado para cada asistente con sus tareas, plazos y el contexto relevante, listo para revisar y enviar. La demo carga una transcripción y produce una pila de borradores individualizados, convirtiendo una llamada caótica en responsabilidades claras por persona.', 'ai-ml', '6-12h', 6, 12, 'intermediate', '["agents","nlp"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Recipe Scaler that Rewrites Steps for Any Serving Count', 'Escalador de recetas que reescribe los pasos por porciones', 'Paste a recipe and a target serving size; the tool rescales every ingredient AND rewrites the instructions to match — adjusting pan sizes, bake times, and "a pinch" amounts that don''t scale linearly. The demo turns a recipe for four into one for eleven and shows the reworded steps, handling the awkward math home cooks always get wrong.', 'Pegá una receta y la cantidad de porciones deseada; la herramienta reescala cada ingrediente Y reescribe las instrucciones para que coincidan, ajustando tamaños de sartén, tiempos de horno y cantidades "a gusto" que no escalan linealmente. La demo convierte una receta para cuatro en una para once y muestra los pasos reformulados, resolviendo la matemática incómoda que los cocineros caseros siempre erran.', 'ai-ml', '3-6h', 3, 6, 'beginner', '["nlp","llm-apps"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Sketch-to-UI Agent that Turns a Napkin Drawing into Code', 'Agente de boceto a UI que vuelve un dibujo en código', 'Photograph a rough wireframe sketch and the agent recognizes the layout — buttons, inputs, cards, nav — and emits clean component code that matches the arrangement. The demo snaps a hand-drawn screen and previews a working interface beside it, leaving the framework open so each team renders the same sketch their own way.', 'Fotografiá un boceto de wireframe a mano alzada y el agente reconoce el diseño —botones, campos, tarjetas, navegación— y emite código de componentes limpio que coincide con la disposición. La demo captura una pantalla dibujada a mano y muestra una interfaz funcional al lado, dejando el framework abierto para que cada equipo renderice el mismo boceto a su manera.', 'ai-ml', '12-24h', 12, 24, 'advanced', '["computer-vision","generative","agents"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Negotiation Simulator with an Agent That Won''t Budge Easily', 'Simulador de negociación con un agente que no cede fácil', 'Practice a salary or deal negotiation against an agent with a hidden goal and a stubborn personality that pushes back, anchors, and concedes only when you make a real case. After the chat it scores your tactics and shows the moments you left money on the table. The demo runs a full back-and-forth and ends with a coaching breakdown.', 'Practicá una negociación salarial o de un acuerdo contra un agente con un objetivo oculto y una personalidad terca que contraataca, ancla y solo cede cuando presentás un argumento real. Tras el chat puntúa tus tácticas y muestra los momentos donde dejaste dinero sobre la mesa. La demo corre un ida y vuelta completo y termina con un análisis de coaching.', 'ai-ml', '6-12h', 6, 12, 'intermediate', '["agents","nlp"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Soundscape Generator that Scores a Photo of a Place', 'Generador de paisaje sonoro que musicaliza una foto de un lugar', 'Upload a photo of any scene — a forest, a subway, a kitchen — and the tool generates a layered ambient soundscape that matches what you''d actually hear there, blending the right textures and rhythm. The demo drops in a street photo and plays back a looping ambience seconds later, a fun audio-meets-vision single-feature build.', 'Subí una foto de cualquier escena —un bosque, un subte, una cocina— y la herramienta genera un paisaje sonoro ambiental en capas que coincide con lo que realmente escucharías ahí, mezclando las texturas y el ritmo justos. La demo carga una foto de calle y reproduce un ambiente en bucle segundos después, una construcción divertida de una función que une audio y visión.', 'ai-ml', '6-12h', 6, 12, 'intermediate', '["generative","audio","computer-vision"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Spending Predictor that Warns Before You Overshoot Budget', 'Predictor de gastos que avisa antes de pasarte del presupuesto', 'Connect a month of transactions and the tool projects where your spending lands by month-end given your current pace, flagging categories about to blow the budget days before they do. The demo loads sample transactions and shows a forecast line crossing the limit, turning reactive regret into an early, specific heads-up.', 'Conectá un mes de transacciones y la herramienta proyecta dónde quedará tu gasto a fin de mes según tu ritmo actual, marcando categorías a punto de superar el presupuesto días antes de que ocurra. La demo carga transacciones de ejemplo y muestra una línea de pronóstico cruzando el límite, convirtiendo el arrepentimiento reactivo en un aviso temprano y específico.', 'ai-ml', '6-12h', 6, 12, 'intermediate', '["prediction","recommendation"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Cover Letter Tailor that Mirrors a Job Post''s Language', 'Adaptador de carta de presentación al lenguaje del aviso', 'Paste your resume and a job posting and the tool drafts a cover letter that mirrors the post''s own keywords and tone, mapping your real experience to each listed requirement so nothing feels generic. The demo pairs a resume with a posting and shows a tailored letter with the matched phrases highlighted, ready to refine.', 'Pegá tu currículum y un aviso de empleo y la herramienta redacta una carta de presentación que refleja las palabras clave y el tono del aviso, mapeando tu experiencia real a cada requisito listado para que nada suene genérico. La demo combina un currículum con un aviso y muestra una carta a medida con las frases coincidentes resaltadas, lista para pulir.', 'ai-ml', '1-3h', 1, 3, 'beginner', '["nlp","llm-apps"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Receipt Carbon Estimator that Scores Your Grocery Haul', 'Estimador de carbono que puntúa tu compra del súper', 'Snap a grocery receipt and the tool reads the line items, estimates the carbon footprint of each product, and suggests lower-impact swaps that keep the same meal plan. The demo photographs a receipt and returns a per-item footprint with a greener alternative beside the heaviest offenders, making an abstract number tangible at the cart level.', 'Sacá una foto del ticket del súper y la herramienta lee los ítems, estima la huella de carbono de cada producto y sugiere reemplazos de menor impacto que mantienen el mismo plan de comidas. La demo fotografía un ticket y devuelve una huella por ítem con una alternativa más verde junto a los que más pesan, volviendo tangible un número abstracto al nivel del carrito.', 'ai-ml', '6-12h', 6, 12, 'intermediate', '["computer-vision","recommendation","prediction"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Lyrics Coach that Suggests Rhymes That Fit Your Flow', 'Coach de letras que sugiere rimas acordes a tu flow', 'Type a line of a verse and the tool suggests rhyming continuations that match its syllable count and stress pattern, so the next line actually scans when you rap or sing it. The demo writes one bar and watches candidate next-lines appear ranked by how cleanly they fit the meter, a tight build for songwriters stuck mid-verse.', 'Escribí un verso y la herramienta sugiere continuaciones que riman y respetan su cantidad de sílabas y patrón de acentos, para que la siguiente línea realmente encaje al rapear o cantar. La demo escribe un compás y observa cómo aparecen líneas candidatas ordenadas por qué tan limpiamente calzan en la métrica, una construcción ágil para compositores trabados a mitad de verso.', 'ai-ml', '3-6h', 3, 6, 'intermediate', '["nlp","generative","audio"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Parking Spot Counter from a Live Lot Camera Feed', 'Contador de plazas libres desde una cámara del estacionamiento', 'Point a camera at a parking lot and the tool counts free versus taken spots in real time, drawing the layout and updating a live count as cars come and go. The demo runs a recorded lot clip and shows the open-spot tally tick up and down, a sharp vision build that turns a single overhead view into a usable availability board.', 'Apuntá una cámara a un estacionamiento y la herramienta cuenta plazas libres versus ocupadas en tiempo real, dibujando el plano y actualizando un conteo en vivo a medida que los autos entran y salen. La demo corre un clip grabado de un lote y muestra el conteo de plazas libres subir y bajar, una construcción de visión nítida que convierte una sola vista cenital en un tablero de disponibilidad usable.', 'ai-ml', '6-12h', 6, 12, 'intermediate', '["computer-vision","prediction"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Argument Mapper that Diagrams a Long Comment Thread', 'Mapeador de argumentos que diagrama un hilo largo de comentarios', 'Paste a sprawling online debate and the tool extracts the distinct claims, groups who agrees and disagrees, and renders a visual map showing which points actually clash versus talk past each other. The demo loads a heated thread and produces a one-screen diagram, making a chaotic argument suddenly legible at a glance.', 'Pegá un debate online enredado y la herramienta extrae las afirmaciones distintas, agrupa quién está de acuerdo y quién no, y renderiza un mapa visual que muestra qué puntos realmente chocan versus cuáles se ignoran entre sí. La demo carga un hilo acalorado y produce un diagrama de una pantalla, volviendo legible de un vistazo una discusión caótica.', 'ai-ml', '6-12h', 6, 12, 'intermediate', '["nlp","llm-apps"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Pet Behavior Translator from a Short Video Clip', 'Traductor de conducta de mascotas desde un clip corto', 'Upload a short clip of your dog or cat and the tool reads body language — ears, tail, posture, gaze — to estimate the animal''s likely emotional state and what it''s signaling, with the cues it relied on labeled. The demo plays a clip and returns "anxious, wants space" with the visual evidence, a playful but grounded vision build.', 'Subí un clip corto de tu perro o gato y la herramienta lee el lenguaje corporal —orejas, cola, postura, mirada— para estimar el probable estado emocional del animal y qué está señalando, con las pistas usadas etiquetadas. La demo reproduce un clip y devuelve "ansioso, quiere espacio" con la evidencia visual, una construcción de visión lúdica pero fundamentada.', 'ai-ml', '6-12h', 6, 12, 'intermediate', '["computer-vision","prediction"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Study Buddy Agent that Quizzes You by Voice on a Drive', 'Agente compañero que te toma examen por voz mientras manejás', 'Hand it your study material and the agent runs a hands-free spoken quiz: it asks questions aloud, listens to your answer, and adapts difficulty based on what you keep missing — perfect for studying during a commute. The demo holds a short voice quiz and shows the agent circling back to your weak spots, all without a screen.', 'Pasale tu material de estudio y el agente corre un examen hablado manos libres: hace preguntas en voz alta, escucha tu respuesta y adapta la dificultad según lo que seguís errando, ideal para estudiar en el viaje. La demo sostiene un quiz de voz corto y muestra al agente volviendo sobre tus puntos débiles, todo sin pantalla.', 'ai-ml', '6-12h', 6, 12, 'intermediate', '["audio","agents","nlp"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Thumbnail A/B Predictor that Scores Click Appeal', 'Predictor A/B de miniaturas que puntúa el atractivo de clic', 'Upload two video thumbnails and the tool predicts which will earn more clicks, scoring each on contrast, face emotion, text legibility, and clutter, then explains the gap. The demo pits two thumbnails head to head and shows the winner with a reasoned breakdown, helping creators choose before they ever publish.', 'Subí dos miniaturas de video y la herramienta predice cuál logrará más clics, puntuando cada una en contraste, emoción del rostro, legibilidad del texto y desorden, y luego explica la diferencia. La demo enfrenta dos miniaturas cara a cara y muestra la ganadora con un análisis razonado, ayudando a los creadores a elegir antes de publicar.', 'ai-ml', '6-12h', 6, 12, 'intermediate', '["computer-vision","prediction"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Voice-Cloned Audiobook Maker from a Short Sample', 'Creador de audiolibros con voz clonada desde una muestra corta', 'Record a one-minute voice sample, paste a chapter of text, and the tool narrates it in that voice with natural pacing, pauses, and emphasis — letting someone make an audiobook in their own or a loved one''s voice. The demo clones a short sample and plays back a paragraph, with clear consent gating built into the flow.', 'Grabá una muestra de voz de un minuto, pegá un capítulo de texto y la herramienta lo narra en esa voz con ritmo, pausas y énfasis naturales, permitiendo hacer un audiolibro con la voz propia o de un ser querido. La demo clona una muestra corta y reproduce un párrafo, con un control de consentimiento claro integrado en el flujo.', 'ai-ml', '12-24h', 12, 24, 'advanced', '["audio","generative"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Wardrobe Agent that Plans a Week of Outfits from Photos', 'Agente de guardarropa que arma una semana de outfits con fotos', 'Photograph your clothes once and the agent catalogs them, then plans a week of outfits matched to the forecast and your calendar — flagging when you''ve worn something too recently and what single piece would unlock the most new combos. The demo builds a Monday-to-Friday plan from a small closet, mixing vision tagging with planning.', 'Fotografiá tu ropa una vez y el agente la cataloga, luego planifica una semana de outfits acordes al pronóstico y tu calendario, avisando cuándo usaste algo hace muy poco y qué prenda única desbloquearía más combinaciones nuevas. La demo arma un plan de lunes a viernes desde un guardarropa chico, mezclando etiquetado visual con planificación.', 'ai-ml', '12-24h', 12, 24, 'intermediate', '["computer-vision","agents","recommendation"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Autonomous Research Crew that Compares Products for You', 'Equipo de investigación autónomo que compara productos por vos', 'State a buying goal — "a quiet under-$300 robot vacuum for pet hair" — and a crew of agents splits the work: one gathers candidates, one digs reviews, one checks prices, and a lead synthesizes a ranked recommendation with tradeoffs. The demo enters a real query and watches the agents coordinate to a decision table over 48-plus hours of build depth.', 'Indicá un objetivo de compra —"un robot aspirador silencioso de menos de 300 dólares para pelo de mascota"— y un equipo de agentes reparte el trabajo: uno reúne candidatos, otro escarba reseñas, otro chequea precios y un líder sintetiza una recomendación ordenada con sus pros y contras. La demo ingresa una consulta real y observa a los agentes coordinarse hasta una tabla de decisión, con la profundidad de un proyecto de más de 48 horas.', 'ai-ml', '48h+', 48, 72, 'advanced', '["agents","recommendation","llm-apps"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Game Master Agent that Runs a Living Tabletop Campaign', 'Agente máster que dirige una campaña de rol viva', 'An AI game master that runs a multi-session tabletop RPG: it tracks the world state, remembers your past choices and NPC relationships, improvises encounters, and enforces the rules — adapting the story across an entire weekend campaign. The demo plays a short session and shows the GM calling back an earlier decision, a meaty 48-plus hour build with persistent memory and narrative agents.', 'Un máster de juego con IA que dirige un RPG de mesa de varias sesiones: rastrea el estado del mundo, recuerda tus decisiones pasadas y las relaciones con los NPC, improvisa encuentros y hace cumplir las reglas, adaptando la historia durante toda una campaña de fin de semana. La demo juega una sesión corta y muestra al máster retomando una decisión anterior, una construcción robusta de más de 48 horas con memoria persistente y agentes narrativos.', 'ai-ml', '48h+', 48, 72, 'advanced', '["agents","generative","nlp"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Wait-Time Predictor for Clinics from Past Visit Logs', 'Predictor de espera para clínicas desde registros de visitas', 'Feed in a clinic''s historical visit logs and the tool predicts how long a patient arriving now will actually wait, factoring time of day, weekday, and current queue, then shows the lower-traffic windows to come back. The demo picks an arrival time and returns an estimated wait with a confidence band, turning a frustrating unknown into a plan.', 'Cargá los registros históricos de visitas de una clínica y la herramienta predice cuánto esperará realmente un paciente que llega ahora, considerando hora del día, día de la semana y la cola actual, y luego muestra las franjas de menor afluencia para volver. La demo elige una hora de llegada y devuelve una espera estimada con una banda de confianza, convirtiendo una incógnita frustrante en un plan.', 'ai-ml', '6-12h', 6, 12, 'intermediate', '["prediction","recommendation"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Camera That Signs Each Photo for On-Chain Authenticity', 'Cámara que firma cada foto para autenticidad on-chain', 'A capture app that cryptographically signs a photo the instant it is taken, embedding device key, time and GPS, then anchors the hash on-chain so anyone can later prove the image is original and unedited. Useful against deepfakes for journalists and insurers. The demo snaps a picture and shows a verifier rejecting a tampered copy while accepting the signed one.', 'Una app de captura que firma criptográficamente una foto en el instante en que se toma, incrustando clave del dispositivo, hora y GPS, y ancla el hash on-chain para que cualquiera pueda probar luego que la imagen es original y no editada. Útil contra deepfakes para periodistas y aseguradoras. La demo toma una foto y muestra a un verificador rechazando una copia alterada mientras acepta la firmada.', 'crypto-web3', '12-24h', 12, 24, 'advanced', '["identity","on-chain-data","smart-contracts"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Pay-Per-Call API Gate Where AI Agents Settle in Stablecoins', 'Puerta de API por llamada donde los agentes IA pagan en stablecoins', 'A reverse proxy that answers any unpaid API request with a machine-readable price, lets an AI agent pay a few cents in stablecoins, then forwards the call. No accounts, no API keys, just per-request settlement so agents can buy data autonomously. The demo runs a script that hits a paid endpoint, watches it get a 402, pays, and receives the response on retry.', 'Un proxy inverso que responde cualquier petición de API impaga con un precio legible por máquina, deja que un agente IA pague unos centavos en stablecoins y luego reenvía la llamada. Sin cuentas ni claves de API, solo liquidación por petición para que los agentes compren datos de forma autónoma. La demo corre un script que golpea un endpoint pago, recibe un 402, paga y obtiene la respuesta al reintentar.', 'crypto-web3', '12-24h', 12, 24, 'advanced', '["payments","smart-contracts"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Session-Key Pass That Lends an App Limited Wallet Power', 'Pase de clave de sesión que presta poder limitado de la wallet a una app', 'A wallet add-on that issues a scoped session key so a game or app can sign transactions for you within strict limits — only these contracts, this spend cap, this expiry — without ever touching your main key. Revoke it in one tap. The demo grants a key, lets the app fire several gasless moves, then shows the key auto-expiring and refusing the next action.', 'Un complemento de wallet que emite una clave de sesión acotada para que un juego o app firme transacciones por vos dentro de límites estrictos —solo estos contratos, este tope de gasto, este vencimiento— sin tocar nunca tu clave principal. Revocala con un toque. La demo otorga una clave, deja que la app dispare varias jugadas sin gas y luego muestra la clave expirando sola y rechazando la siguiente acción.', 'crypto-web3', '12-24h', 12, 24, 'advanced', '["wallets","smart-contracts","identity"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Private Credit Score You Prove With Zero-Knowledge Proofs', 'Puntaje de crédito privado que probás con pruebas de conocimiento cero', 'A tool that reads your on-chain history — repayments, liquidations, account age — computes a credit band, and lets you prove you are above a threshold without revealing the underlying wallet or numbers. A lender checks the proof, not your finances. The demo generates a proof for one wallet and a verifier confirms it clears the bar while learning nothing else.', 'Una herramienta que lee tu historial on-chain —repagos, liquidaciones, antigüedad de cuenta—, calcula una banda crediticia y te permite probar que superás un umbral sin revelar la wallet subyacente ni los números. Un prestamista verifica la prueba, no tus finanzas. La demo genera una prueba para una wallet y un verificador confirma que supera el límite sin enterarse de nada más.', 'crypto-web3', '24-48h', 24, 48, 'advanced', '["defi","identity","on-chain-data"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Delay-Insurance Pool That Pays Out on Slow Transactions', 'Pool de seguro de demora que paga ante transacciones lentas', 'A micro-insurance contract where you pay a tiny premium when sending a transaction; if it does not confirm within the promised window, the pool automatically refunds you a payout. It turns gas uncertainty into a hedge for time-sensitive swaps. The demo buys a policy, simulates a congested block, and shows the claim settling on its own once the deadline passes.', 'Un contrato de microseguro donde pagás una prima mínima al enviar una transacción; si no se confirma dentro de la ventana prometida, el pool te reembolsa automáticamente un pago. Convierte la incertidumbre del gas en una cobertura para swaps sensibles al tiempo. La demo compra una póliza, simula un bloque congestionado y muestra el reclamo liquidándose solo una vez vencido el plazo.', 'crypto-web3', '24-48h', 24, 48, 'advanced', '["defi","smart-contracts"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Merit-Weighted Governance NFT That Blunts Whale Capture', 'NFT de gobernanza ponderado por mérito que frena la captura de ballenas', 'A DAO voting layer where weight comes from a non-transferable badge earned through contributions and tenure, not raw token balance, so a rich newcomer cannot buy a decision overnight. Weights decay if you go inactive. The demo runs a proposal twice — once token-weighted, once merit-weighted — and shows how the outcome flips away from a single whale.', 'Una capa de votación de DAO donde el peso surge de una insignia intransferible ganada por contribuciones y antigüedad, no por el balance bruto de tokens, así un recién llegado adinerado no compra una decisión de un día para otro. Los pesos decaen si te volvés inactivo. La demo corre una propuesta dos veces —una ponderada por tokens, otra por mérito— y muestra cómo el resultado se aleja de una sola ballena.', 'crypto-web3', '12-24h', 12, 24, 'intermediate', '["dao","nfts","smart-contracts"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('One-Screen Token Allowance Heatmap for a Single Wallet', 'Mapa de calor de permisos de token en una pantalla para una wallet', 'Paste a wallet address and instantly see every active token approval as a heatmap, sized by how much value each spender could drain right now, hottest at the top. It is read-only and works in seconds, perfect for a quick risk gut-check before signing more. The demo loads a busy wallet and surfaces the two scariest unlimited approvals at a glance.', 'Pegá una dirección de wallet y mirá al instante cada permiso de token activo como un mapa de calor, dimensionado por cuánto valor podría drenar cada gastador ahora mismo, los más calientes arriba. Es de solo lectura y funciona en segundos, ideal para una revisión rápida de riesgo antes de firmar más. La demo carga una wallet activa y revela de un vistazo los dos permisos ilimitados más alarmantes.', 'crypto-web3', '1-3h', 1, 3, 'beginner', '["wallets","on-chain-data"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Stablecoin Payroll That Streams Salary by the Second', 'Nómina en stablecoins que transmite el salario por segundo', 'An employer dashboard that funds a contract once and streams each worker''s salary continuously, so anyone can withdraw whatever has accrued at any moment instead of waiting for payday. Pausing or topping up is one click. The demo starts a stream for three contributors and shows their claimable balances ticking up live, with one withdrawing mid-month.', 'Un panel para empleadores que financia un contrato una vez y transmite el salario de cada trabajador de forma continua, así cualquiera puede retirar lo acumulado en cualquier momento en lugar de esperar el día de pago. Pausar o recargar es un clic. La demo inicia un stream para tres colaboradores y muestra sus saldos reclamables subiendo en vivo, con uno retirando a mitad de mes.', 'crypto-web3', '12-24h', 12, 24, 'intermediate', '["payments","smart-contracts","defi"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('On-Chain Subscription That Auto-Cancels If You Stop Using It', 'Suscripción on-chain que se autocancela si dejás de usarla', 'A recurring-payment primitive where the merchant can only pull the next period''s fee if your usage oracle shows activity, so a forgotten subscription stops charging instead of bleeding you. You set the rules; the contract enforces them. The demo runs two billing cycles, then simulates inactivity and shows the third charge getting blocked automatically.', 'Una primitiva de pago recurrente donde el comercio solo puede cobrar la cuota del próximo período si tu oráculo de uso muestra actividad, así una suscripción olvidada deja de cobrarte en lugar de desangrarte. Vos ponés las reglas; el contrato las hace cumplir. La demo corre dos ciclos de cobro, luego simula inactividad y muestra el tercer cobro bloqueándose automáticamente.', 'crypto-web3', '12-24h', 12, 24, 'intermediate', '["payments","smart-contracts"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('MEV-Aware Swap Router That Shows the Sandwich You Dodged', 'Router de swap consciente de MEV que muestra el sándwich que evitaste', 'A swap front-end that routes your trade through a private path and then visualizes the sandwich attack it would have suffered on the public mempool, with the dollar amount you saved. It makes invisible MEV losses tangible. The demo runs the same swap publicly and privately side by side and highlights the price you kept by going dark.', 'Un front-end de swap que enruta tu operación por una vía privada y luego visualiza el ataque sándwich que habrías sufrido en el mempool público, con el monto en dólares que ahorraste. Hace tangibles las pérdidas invisibles por MEV. La demo corre el mismo swap pública y privadamente en paralelo y resalta el precio que conservaste al ir a oscuras.', 'crypto-web3', '24-48h', 24, 48, 'advanced', '["defi","on-chain-data"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Dynamic NFT Ticket That Locks After the Event Scans It', 'Entrada NFT dinámica que se bloquea tras escanearla en el evento', 'An event ticket NFT that is freely transferable until check-in, when a door scan flips it to a permanent, non-resellable proof of attendance with the seat and date baked in. It kills resale fraud at the door while leaving a collectible memento. The demo mints a ticket, transfers it once, scans it in, and shows resale attempts then bouncing.', 'Una entrada NFT libremente transferible hasta el check-in, cuando un escaneo en la puerta la convierte en una prueba de asistencia permanente e irrevendible con asiento y fecha grabados. Mata el fraude de reventa en la puerta y deja un recuerdo coleccionable. La demo acuña una entrada, la transfiere una vez, la escanea en el ingreso y muestra que luego los intentos de reventa rebotan.', 'crypto-web3', '6-12h', 6, 12, 'intermediate', '["nfts","smart-contracts","identity"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Proof-of-Reserves Widget Anyone Can Embed on a Site', 'Widget de prueba de reservas que cualquiera puede incrustar en un sitio', 'A drop-in badge that reads an exchange or treasury''s on-chain wallets and a liabilities attestation, then renders a live solvency ratio visitors can click to audit the underlying addresses. It turns trust-me into verify-yourself. The demo embeds the widget on a sample page and shows the ratio updating when a watched wallet''s balance changes.', 'Una insignia lista para incrustar que lee las wallets on-chain de un exchange o tesorería y una atestación de pasivos, y luego renderiza un ratio de solvencia en vivo que los visitantes pueden clicar para auditar las direcciones subyacentes. Convierte el confía en mí en verificalo vos. La demo incrusta el widget en una página de ejemplo y muestra el ratio actualizándose cuando cambia el balance de una wallet observada.', 'crypto-web3', '6-12h', 6, 12, 'intermediate', '["on-chain-data","defi"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Gasless Onboarding Link That Funds a New User''s First Move', 'Enlace de onboarding sin gas que financia el primer movimiento del usuario', 'A shareable claim link that spins up a smart account for a brand-new user and sponsors their first few transactions via a paymaster, so they can mint or vote before ever buying gas. The sender sets a budget and expiry. The demo opens the link as a fresh user, completes an action with zero balance, and shows the sponsor''s budget ticking down.', 'Un enlace reclamable que crea una cuenta inteligente para un usuario nuevo y patrocina sus primeras transacciones vía un paymaster, así puede acuñar o votar antes de comprar gas. El emisor fija un presupuesto y un vencimiento. La demo abre el enlace como usuario nuevo, completa una acción con saldo cero y muestra el presupuesto del patrocinador bajando.', 'crypto-web3', '12-24h', 12, 24, 'intermediate', '["wallets","payments","smart-contracts"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Token Vesting Cliff Visualizer That Flags Upcoming Unlocks', 'Visualizador de vesting que avisa los desbloqueos próximos', 'Paste a vesting contract address and get a clean timeline of every cliff and linear unlock, with a countdown to the next big tranche hitting the market and how much supply it adds. Traders use it to anticipate sell pressure. The demo loads a real-style schedule and highlights the next unlock that dwarfs daily volume in red.', 'Pegá la dirección de un contrato de vesting y obtené una línea de tiempo limpia de cada cliff y desbloqueo lineal, con una cuenta regresiva al próximo tramo grande llegando al mercado y cuánta oferta agrega. Los traders lo usan para anticipar presión vendedora. La demo carga un cronograma realista y resalta en rojo el próximo desbloqueo que eclipsa el volumen diario.', 'crypto-web3', '3-6h', 3, 6, 'beginner', '["on-chain-data","defi"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Onchain Loyalty Stamp Card That Unlocks a Reward at Ten', 'Tarjeta de sellos de fidelidad onchain que premia a los diez', 'A merchant tool where each purchase mints a stamp to the customer''s wallet, and the tenth stamp auto-redeems a coupon NFT — no app, no plastic card, fully portable across the merchant''s locations. The demo rings up purchases for a wallet, watches stamps accumulate, and triggers the reward automatically when the card fills.', 'Una herramienta para comercios donde cada compra acuña un sello en la wallet del cliente, y el décimo sello canjea automáticamente un cupón NFT —sin app, sin tarjeta de plástico, totalmente portable entre las sucursales del comercio. La demo registra compras para una wallet, mira los sellos acumularse y dispara la recompensa automáticamente cuando la tarjeta se llena.', 'crypto-web3', '3-6h', 3, 6, 'beginner', '["nfts","payments"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Bridge Risk Scanner That Rates a Cross-Chain Route Before You Send', 'Escáner de riesgo de puentes que califica una ruta cross-chain antes de enviar', 'Pick a source and destination chain and the tool scores every available bridge route by recent exploit history, liquidity depth, time-to-finality and fees, then recommends the safest path for your amount. The demo compares three routes for a sample transfer and explains in plain language why the cheapest one is also the riskiest.', 'Elegí una cadena de origen y destino y la herramienta puntúa cada ruta de puente disponible por historial reciente de exploits, profundidad de liquidez, tiempo a finalidad y comisiones, y luego recomienda el camino más seguro para tu monto. La demo compara tres rutas para una transferencia de ejemplo y explica en lenguaje claro por qué la más barata es también la más riesgosa.', 'crypto-web3', '6-12h', 6, 12, 'intermediate', '["defi","on-chain-data"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('DAO Treasury Diversifier That Rebalances Toward Stablecoins', 'Diversificador de tesorería de DAO que rebalancea hacia stablecoins', 'A governance-approved contract that automatically trims a DAO''s native-token concentration into stablecoins when it exceeds a set ratio, giving the treasury a runway that survives a token crash. Members vote the policy, the contract executes it. The demo simulates a price drop and shows the rebalance firing only once the threshold is breached.', 'Un contrato aprobado por gobernanza que recorta automáticamente la concentración del token nativo de una DAO hacia stablecoins cuando supera un ratio fijado, dándole a la tesorería una pista que sobrevive a una caída del token. Los miembros votan la política, el contrato la ejecuta. La demo simula una baja de precio y muestra el rebalanceo disparándose solo cuando se supera el umbral.', 'crypto-web3', '24-48h', 24, 48, 'advanced', '["dao","defi","smart-contracts"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Proof-of-Humanity Captcha Gated by a One-Person Attestation', 'Captcha de prueba de humanidad regido por una atestación de una persona', 'A drop-in widget that lets a site require a privacy-preserving humanity proof instead of a captcha, so each real person passes once and bots cannot farm thousands of accounts. No personal data leaves the user. The demo gates a signup form and shows a second attempt from the same human being recognized and refused a duplicate.', 'Un widget listo para incrustar que permite a un sitio exigir una prueba de humanidad que preserva la privacidad en lugar de un captcha, así cada persona real pasa una vez y los bots no pueden cultivar miles de cuentas. Ningún dato personal sale del usuario. La demo protege un formulario de registro y muestra que un segundo intento del mismo humano es reconocido y se le niega un duplicado.', 'crypto-web3', '12-24h', 12, 24, 'intermediate', '["identity","smart-contracts"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Royalty Splitter That Pays Collaborators on Every NFT Resale', 'Repartidor de regalías que paga a colaboradores en cada reventa de NFT', 'A mint wrapper that hard-codes a revenue split across many collaborators, so each primary sale and every downstream royalty auto-distributes to artists, writers and funders by their agreed shares with no manual accounting. The demo mints a piece with four contributors, simulates two resales, and shows each wallet''s cut landing instantly.', 'Un envoltorio de minteo que codifica un reparto de ingresos entre varios colaboradores, así cada venta primaria y cada regalía posterior se distribuye automáticamente a artistas, escritores y financiadores según sus partes acordadas sin contabilidad manual. La demo acuña una obra con cuatro colaboradores, simula dos reventas y muestra la parte de cada wallet llegando al instante.', 'crypto-web3', '6-12h', 6, 12, 'intermediate', '["nfts","payments","smart-contracts"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Smart Contract Diff Viewer That Explains a Risky Upgrade', 'Visor de diferencias de contrato que explica una actualización riesgosa', 'Paste two contract addresses or versions and see a function-level diff that flags newly added admin powers, removed checks or changed ownership in plain language, so a community can judge a proxy upgrade before it lands. The demo compares a benign upgrade with a sneaky one and surfaces the hidden mint-to-owner function in red.', 'Pegá dos direcciones o versiones de contrato y mirá una diferencia a nivel de función que marca en lenguaje claro nuevos poderes de administrador, chequeos eliminados o cambios de propiedad, para que una comunidad juzgue una actualización de proxy antes de que ocurra. La demo compara una actualización benigna con una tramposa y resalta en rojo la función oculta de acuñar al dueño.', 'crypto-web3', '6-12h', 6, 12, 'intermediate', '["smart-contracts","on-chain-data"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Tip Button That Splits Among Everyone Who Touched the Repo', 'Botón de propina que reparte entre todos los que tocaron el repo', 'A donate button for an open-source project that, on each tip, splits the funds across recent contributors weighted by their merged commits, paying maintainers and drive-by fixers alike automatically. The demo connects a sample repo, sends one tip, and shows it fanning out to five wallets in proportion to their contributions.', 'Un botón de donar para un proyecto de código abierto que, en cada propina, reparte los fondos entre los colaboradores recientes ponderados por sus commits fusionados, pagando a mantenedores y arregladores casuales por igual y de forma automática. La demo conecta un repo de ejemplo, envía una propina y la muestra repartiéndose a cinco wallets en proporción a sus aportes.', 'crypto-web3', '6-12h', 6, 12, 'intermediate', '["payments","smart-contracts"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Wallet Health Report Card With a Single Safety Grade', 'Boletín de salud de wallet con una sola nota de seguridad', 'Enter an address and get a one-page report card grading the wallet''s safety — risky approvals, exposure to flagged contracts, dust-attack tokens, no recovery set — distilled into an A-to-F grade with the top three fixes. The demo grades a messy wallet a D and lists the exact actions that would bump it to a B.', 'Ingresá una dirección y obtené un boletín de una página que califica la seguridad de la wallet —permisos riesgosos, exposición a contratos marcados, tokens de ataque por polvo, sin recuperación configurada— destilado en una nota de la A a la F con los tres arreglos principales. La demo califica una wallet desordenada con una D y lista las acciones exactas que la subirían a una B.', 'crypto-web3', '3-6h', 3, 6, 'beginner', '["wallets","on-chain-data","identity"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Milestone Escrow for Grants That Releases on Verified Output', 'Fideicomiso por hitos para subsidios que libera ante resultado verificado', 'A grant contract that locks funds and releases each tranche only when a milestone is attested — a merged PR, a deployed address, a signed reviewer approval — so funders pay for delivered work, not promises. The demo sets up a three-milestone grant, attests the first two, and shows the final payout staying locked until its proof arrives.', 'Un contrato de subsidio que bloquea fondos y libera cada tramo solo cuando un hito es atestado —un PR fusionado, una dirección desplegada, una aprobación firmada de revisor— para que los financiadores paguen por trabajo entregado, no por promesas. La demo arma un subsidio de tres hitos, atesta los dos primeros y muestra el pago final quedando bloqueado hasta que llega su prueba.', 'crypto-web3', '12-24h', 12, 24, 'intermediate', '["dao","payments","smart-contracts"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Liquidation Watchtower That Pings You Before You Get Wiped', 'Atalaya de liquidación que te avisa antes de que te liquiden', 'Connect a lending position read-only and the tool watches your health factor against live prices, sending an alert the moment a drop would put you within range of liquidation, with the exact top-up that restores safety. The demo loads a borrowed position, simulates a price slide, and fires the warning while there is still time to act.', 'Conectá una posición de préstamo en solo lectura y la herramienta vigila tu factor de salud contra precios en vivo, enviando una alerta en el momento en que una caída te pondría en rango de liquidación, con la recarga exacta que restaura la seguridad. La demo carga una posición prestada, simula un deslizamiento de precio y dispara el aviso cuando todavía hay tiempo de actuar.', 'crypto-web3', '6-12h', 6, 12, 'intermediate', '["defi","on-chain-data","wallets"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('ENS Profile Card That Renders a Wallet''s Public Reputation', 'Tarjeta de perfil ENS que renderiza la reputación pública de una wallet', 'Type any name or address and get a shareable profile card pulling its ENS name, avatar, POAPs, notable holdings and on-chain age into one clean view — a Web3 business card you can drop in a bio. The demo resolves a name and renders a card that updates the moment the wallet collects a new badge.', 'Escribí cualquier nombre o dirección y obtené una tarjeta de perfil compartible que reúne su nombre ENS, avatar, POAPs, tenencias destacadas y antigüedad on-chain en una vista limpia —una tarjeta de presentación Web3 para poner en una bio. La demo resuelve un nombre y renderiza una tarjeta que se actualiza en cuanto la wallet recibe una nueva insignia.', 'crypto-web3', '1-3h', 1, 3, 'beginner', '["identity","on-chain-data"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Refundable Crowdfund That Returns Funds If the Goal Misses', 'Crowdfunding reembolsable que devuelve fondos si no se llega a la meta', 'An all-or-nothing crowdfunding contract where pledges sit locked until a deadline: hit the goal and the creator can withdraw, miss it and every backer reclaims their full pledge with one click. No trust in the organizer required. The demo runs a campaign that falls short and shows backers pulling exact refunds automatically.', 'Un contrato de crowdfunding de todo o nada donde las promesas quedan bloqueadas hasta una fecha límite: si se alcanza la meta el creador puede retirar, si no, cada aportante reclama su promesa completa con un clic. No hace falta confiar en el organizador. La demo corre una campaña que no llega y muestra a los aportantes retirando reembolsos exactos automáticamente.', 'crypto-web3', '3-6h', 3, 6, 'beginner', '["payments","smart-contracts","dao"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Onchain Time Capsule NFT That Unlocks Its Media on a Date', 'NFT cápsula del tiempo que desbloquea su contenido en una fecha', 'Mint a sealed NFT whose image and message stay encrypted until a chosen future date, when the contract releases the key and the artwork reveals itself to whoever holds it. Perfect for graduations, anniversaries or a project''s launch. The demo mints a capsule with a near deadline and shows the hidden media decrypting the instant the block time passes.', 'Acuñá un NFT sellado cuya imagen y mensaje permanecen cifrados hasta una fecha futura elegida, cuando el contrato libera la clave y la obra se revela a quien lo posea. Ideal para graduaciones, aniversarios o el lanzamiento de un proyecto. La demo acuña una cápsula con un plazo cercano y muestra el contenido oculto descifrándose en el instante en que pasa el tiempo del bloque.', 'crypto-web3', '6-12h', 6, 12, 'intermediate', '["nfts","smart-contracts"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Spending Limit Smart Account That Throttles Daily Outflows', 'Cuenta inteligente con límite que regula las salidas diarias', 'A smart wallet that enforces a self-set daily and per-transaction spend cap, so even a leaked key cannot drain you in one shot — anything above the limit needs a timelock or a second device to confirm. The demo tries a large transfer that gets throttled, then approves it from a backup device after the cooldown.', 'Una wallet inteligente que impone un tope de gasto diario y por transacción que vos mismo fijás, así ni una clave filtrada puede vaciarte de un golpe —cualquier cosa por encima del límite necesita un timelock o un segundo dispositivo para confirmar. La demo intenta una transferencia grande que es regulada, y luego la aprueba desde un dispositivo de respaldo tras el enfriamiento.', 'crypto-web3', '12-24h', 12, 24, 'advanced', '["wallets","smart-contracts"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Real-World Asset Receipt That Ties an NFT to a Serial Number', 'Recibo de activo real que ata un NFT a un número de serie', 'A tool for sellers of physical goods to mint a transferable ownership receipt NFT bound to an item''s serial or QR tag, so resale, warranty and provenance follow the object across owners. The demo registers a watch, transfers its receipt to a buyer, and shows a scan of the tag resolving to the current rightful owner.', 'Una herramienta para vendedores de bienes físicos para acuñar un recibo de propiedad NFT transferible atado al número de serie o etiqueta QR de un artículo, así reventa, garantía y procedencia siguen al objeto entre dueños. La demo registra un reloj, transfiere su recibo a un comprador y muestra que escanear la etiqueta resuelve al dueño legítimo actual.', 'crypto-web3', '12-24h', 12, 24, 'intermediate', '["nfts","identity","smart-contracts"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Conviction Voting Board Where Support Grows the Longer You Back It', 'Tablero de voto por convicción donde el apoyo crece cuanto más lo sostenés', 'A DAO funding board using conviction voting: backers stake on proposals and their voting power on each grows the longer they hold it there, so steady community will beats a last-minute whale rush. The demo stakes on two proposals, fast-forwards time, and shows the patiently-backed one crossing the funding threshold first.', 'Un tablero de financiamiento de DAO con voto por convicción: los partidarios apuestan en propuestas y su poder de voto en cada una crece cuanto más lo mantienen ahí, así la voluntad sostenida de la comunidad le gana a una embestida de ballena de último minuto. La demo apuesta en dos propuestas, adelanta el tiempo y muestra a la apoyada con paciencia cruzando primero el umbral de financiamiento.', 'crypto-web3', '24-48h', 24, 48, 'advanced', '["dao","smart-contracts"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Gas Estimator That Quotes a Transaction in Your Local Currency', 'Estimador de gas que cotiza una transacción en tu moneda local', 'Paste a pending transaction or pick a common action and instantly see its gas cost converted to your local fiat currency, with a green-yellow-red verdict on whether now is a cheap moment to send. A tiny, friendly tool that demystifies fees for newcomers. The demo quotes a swap in pesos and updates the verdict as the base fee moves.', 'Pegá una transacción pendiente o elegí una acción común y mirá al instante su costo de gas convertido a tu moneda local, con un veredicto verde-amarillo-rojo sobre si ahora es un momento barato para enviar. Una herramienta pequeña y amigable que desmitifica las comisiones para los nuevos. La demo cotiza un swap en pesos y actualiza el veredicto a medida que se mueve la tarifa base.', 'crypto-web3', '1-3h', 1, 3, 'beginner', '["wallets","on-chain-data","payments"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Multisig Proposal Explainer That Decodes a Pending Safe Tx', 'Explicador de propuestas multisig que decodifica una tx Safe pendiente', 'Drop in a pending multisig transaction and the tool decodes the raw calldata into a plain-English summary — who gets paid, which contract is called, what permission changes — so co-signers know exactly what they are approving. The demo loads a queued transaction and reveals that a benign-looking call actually swaps the signer set.', 'Cargá una transacción multisig pendiente y la herramienta decodifica el calldata crudo en un resumen en lenguaje claro —quién cobra, qué contrato se llama, qué permisos cambian— para que los cofirmantes sepan exactamente qué están aprobando. La demo carga una transacción en cola y revela que una llamada de apariencia inocente en realidad cambia el conjunto de firmantes.', 'crypto-web3', '6-12h', 6, 12, 'intermediate', '["wallets","dao","smart-contracts"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Airdrop Eligibility Checker That Proves You Qualify Privately', 'Verificador de airdrop que prueba que calificás sin exponerte', 'A claim portal where a user proves they meet airdrop criteria — held a token by a snapshot, used a protocol N times — with a zero-knowledge proof, so they claim without doxxing their full wallet history to the project. The demo runs a wallet through the checker and issues a private proof that the contract accepts for the claim.', 'Un portal de reclamo donde un usuario prueba que cumple los criterios de airdrop —tener un token en un snapshot, usar un protocolo N veces— con una prueba de conocimiento cero, así reclama sin exponer todo su historial de wallet al proyecto. La demo pasa una wallet por el verificador y emite una prueba privada que el contrato acepta para el reclamo.', 'crypto-web3', '24-48h', 24, 48, 'advanced', '["identity","defi","smart-contracts"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Onchain Habit Stake That Pays You Back for Showing Up', 'Apuesta de hábito onchain que te devuelve por aparecer', 'Stake a deposit toward a daily goal; check in on-chain each day and you reclaim your stake at the end, miss days and the forfeited share is split among the people who stuck with it. A self-enforcing commitment device with skin in the game. The demo runs a short challenge, simulates a missed day, and redistributes the forfeit to the finishers.', 'Apostá un depósito hacia una meta diaria; registrate on-chain cada día y recuperás tu apuesta al final, perdé días y la parte perdida se reparte entre quienes cumplieron. Un dispositivo de compromiso autoejecutable con la piel en juego. La demo corre un desafío corto, simula un día perdido y redistribuye lo perdido a quienes terminaron.', 'crypto-web3', '6-12h', 6, 12, 'intermediate', '["smart-contracts","payments"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Stablecoin Yield Comparison That Shows the Real APY After Risk', 'Comparador de rendimiento en stablecoins que muestra la TAE real tras el riesgo', 'A board that lists where to park stablecoins across protocols, but discounts each headline APY by audit history, TVL stability and depeg exposure to show a risk-adjusted yield, not a vanity number. The demo ranks five venues and explains why a flashy 20% drops below a boring 6% once risk is priced in.', 'Un tablero que lista dónde estacionar stablecoins entre protocolos, pero descuenta cada TAE de portada por historial de auditorías, estabilidad de TVL y exposición a depeg para mostrar un rendimiento ajustado por riesgo, no un número de vanidad. La demo ordena cinco lugares y explica por qué un llamativo 20% cae por debajo de un aburrido 6% una vez valorado el riesgo.', 'crypto-web3', '6-12h', 6, 12, 'intermediate', '["defi","on-chain-data"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Prompt Injection Range that Scores Your LLM Guardrails', 'Campo de Pruebas de Inyección de Prompts que Puntúa tus Defensas de LLM', 'A test harness that throws a curated battery of prompt-injection and jailbreak payloads at any chatbot endpoint, then reports which ones leaked the system prompt, exfiltrated data, or broke role. Each attack shows the exact input and the model''s response side by side, with a pass/fail grid. The demo points it at a live bot and watches the leak counter climb.', 'Un banco de pruebas que lanza una batería curada de cargas de inyección de prompts y jailbreaks contra cualquier endpoint de chatbot, y luego informa cuáles filtraron el system prompt, exfiltraron datos o rompieron el rol. Cada ataque muestra la entrada exacta y la respuesta del modelo lado a lado, con una grilla de aprobado/fallado. La demo lo apunta a un bot en vivo y observa subir el contador de fugas.', 'cybersecurity', '6-12h', 6, 12, 'intermediate', '["web-security","ctf"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Cookie Jar Auditor that Flags Trackers Riding Your Session', 'Auditor de Cookies que Detecta Rastreadores Montados en tu Sesión', 'A tool that loads any page, captures every cookie and local-storage entry it sets, and classifies each as essential, analytics, or third-party tracker by matching domains against known lists. It shows which cookies persist after you say no to a consent banner. A tight, visual single-screen build that turns invisible tracking into an obvious list.', 'Una herramienta que carga cualquier página, captura cada cookie y entrada de local storage que define, y clasifica cada una como esencial, analítica o rastreador de terceros comparando dominios con listas conocidas. Muestra qué cookies persisten después de que rechazás un banner de consentimiento. Una construcción visual de una sola pantalla que convierte el rastreo invisible en una lista evidente.', 'cybersecurity', '3-6h', 3, 6, 'beginner', '["privacy","web-security"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('JWT Token Decoder that Catches Weak Signing Mistakes', 'Decodificador de Tokens JWT que Detecta Errores de Firma Débiles', 'Paste any JWT and the tool decodes header and claims, then runs a checklist for classic flaws: the alg:none trap, HS256 secrets brute-forceable from a wordlist, expired-but-accepted windows, and missing audience checks. Each finding links to how an attacker would abuse it. A sharp single-feature build perfect for a short sprint.', 'Pegá cualquier JWT y la herramienta decodifica el header y los claims, luego corre una lista de control de fallas clásicas: la trampa alg:none, secretos HS256 vulnerables a fuerza bruta desde un diccionario, ventanas vencidas pero aceptadas, y verificaciones de audiencia faltantes. Cada hallazgo enlaza a cómo lo abusaría un atacante. Una construcción nítida de una sola función ideal para un sprint corto.', 'cybersecurity', '1-3h', 1, 3, 'intermediate', '["authentication","web-security"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('SQL Injection Playground with a Live Vulnerable Endpoint', 'Laboratorio de Inyección SQL con un Endpoint Vulnerable en Vivo', 'A safe, sandboxed login form deliberately wide open to SQL injection, paired with a guided panel that suggests payloads and shows the raw query the server builds as you type. Learners watch the WHERE clause mutate and the auth bypass succeed, then flip a switch to see a parameterized version block the same attack. Demoable and genuinely instructive.', 'Un formulario de login en un entorno seguro y aislado, deliberadamente abierto a inyección SQL, junto a un panel guiado que sugiere cargas y muestra la consulta cruda que construye el servidor mientras escribís. Los estudiantes ven mutar la cláusula WHERE y triunfar el bypass de autenticación, y luego activan un interruptor para ver cómo una versión parametrizada bloquea el mismo ataque. Demostrable y genuinamente instructivo.', 'cybersecurity', '6-12h', 6, 12, 'intermediate', '["web-security","ctf"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Memory Dump Explorer that Pulls Secrets from a Crash File', 'Explorador de Volcados de Memoria que Extrae Secretos de un Crash', 'Drop in a process memory dump and the tool carves out plaintext passwords, API keys, and session tokens left in RAM, mapping each hit back to the region it came from. A timeline shows what was recoverable at the moment of capture. A focused forensics build that makes the danger of secrets living in memory tangible in a demo.', 'Soltá un volcado de memoria de un proceso y la herramienta extrae contraseñas en texto plano, claves de API y tokens de sesión que quedaron en la RAM, mapeando cada coincidencia a la región de donde provino. Una línea de tiempo muestra qué era recuperable en el momento de la captura. Una construcción forense enfocada que vuelve tangible en una demo el peligro de los secretos viviendo en memoria.', 'cybersecurity', '12-24h', 12, 24, 'advanced', '["forensics","malware-analysis"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Attack Surface Mapper from a Single Company Domain', 'Mapeador de Superficie de Ataque desde un Único Dominio Corporativo', 'Type one domain and the tool enumerates subdomains, open ports, exposed admin panels, and forgotten dev servers, then draws them as an interactive graph ranked by risk. It flags the staging box still running last year''s software. A satisfying recon build where a judge enters their own domain and watches the map sprawl outward in real time.', 'Escribí un dominio y la herramienta enumera subdominios, puertos abiertos, paneles de administración expuestos y servidores de desarrollo olvidados, y luego los dibuja como un grafo interactivo ordenado por riesgo. Marca el servidor de staging que sigue corriendo el software del año pasado. Una construcción de reconocimiento satisfactoria donde un juez ingresa su propio dominio y ve el mapa expandirse en tiempo real.', 'cybersecurity', '12-24h', 12, 24, 'intermediate', '["network","web-security"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Password Spray Simulator that Shows Why Lockouts Fail', 'Simulador de Password Spraying que Muestra por qué Fallan los Bloqueos', 'Against a mock auth service, this tool demonstrates password spraying: one common password tried slowly across many accounts to dodge per-account lockout. A dashboard tracks attempts, lockout thresholds, and which accounts fell, then lets you toggle defenses like rate limits and impossible-travel checks to see them work. Sharp, demoable, and eye-opening for a half-day build.', 'Contra un servicio de autenticación simulado, esta herramienta demuestra el password spraying: una contraseña común probada lentamente en muchas cuentas para esquivar el bloqueo por cuenta. Un tablero rastrea intentos, umbrales de bloqueo y qué cuentas cayeron, y luego te permite activar defensas como límites de tasa y detección de viajes imposibles para verlas funcionar. Nítida, demostrable y reveladora para una construcción de medio día.', 'cybersecurity', '3-6h', 3, 6, 'intermediate', '["authentication","network"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('OAuth Flow Visualizer that Animates Every Redirect', 'Visualizador de Flujos OAuth que Anima Cada Redirección', 'Point it at any Login-with-Google or GitHub flow and the tool intercepts and animates each step: the authorization request, the consent screen, the code exchange, and the token grant, highlighting where scopes and state parameters live. It flags a missing state check that opens a CSRF hole. A clear teaching build that makes an opaque protocol finally legible.', 'Apuntalo a cualquier flujo de Iniciar sesión con Google o GitHub y la herramienta intercepta y anima cada paso: la solicitud de autorización, la pantalla de consentimiento, el intercambio del código y la concesión del token, resaltando dónde viven los scopes y el parámetro state. Marca una verificación de state faltante que abre un agujero CSRF. Una construcción didáctica clara que vuelve legible un protocolo opaco.', 'cybersecurity', '6-12h', 6, 12, 'intermediate', '["authentication","web-security"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Hash Cracking Visualizer that Races Wordlist vs Brute Force', 'Visualizador de Cracking de Hashes que Compite Diccionario contra Fuerza Bruta', 'Drop in a few sample hashes and watch two cracking strategies race side by side: a dictionary attack with mutation rules versus pure brute force, with live counters for guesses per second and time elapsed. It visually drives home why a salted, slow hash like bcrypt defeats both. A crisp single-screen build that makes password storage tradeoffs click.', 'Soltá algunos hashes de ejemplo y mirá competir dos estrategias de cracking lado a lado: un ataque de diccionario con reglas de mutación contra fuerza bruta pura, con contadores en vivo de intentos por segundo y tiempo transcurrido. Demuestra visualmente por qué un hash lento y con sal como bcrypt vence a ambos. Una construcción nítida de una sola pantalla que aclara los compromisos del almacenamiento de contraseñas.', 'cybersecurity', '3-6h', 3, 6, 'intermediate', '["cryptography","authentication"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('CTF Challenge Builder that Auto-Generates Flag Variants', 'Constructor de Retos CTF que Genera Variantes de Flags Automáticamente', 'An authoring tool for CTF organizers: describe a challenge once and it spins up per-team instances with unique flags so nobody can share answers, plus auto-graded submission and a live scoreboard. Each instance gets its own seeded secret. A genuinely useful build for anyone running an event, with a demo that registers two teams and shows them distinct flags.', 'Una herramienta de autoría para organizadores de CTF: describí un reto una vez y genera instancias por equipo con flags únicas para que nadie pueda compartir respuestas, además de envío autocorregido y un marcador en vivo. Cada instancia recibe su propio secreto sembrado. Una construcción genuinamente útil para quien organiza un evento, con una demo que registra dos equipos y les muestra flags distintas.', 'cybersecurity', '12-24h', 12, 24, 'intermediate', '["ctf","web-security"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Subdomain Takeover Hunter that Spots Dangling DNS', 'Cazador de Tomas de Subdominios que Detecta DNS Colgante', 'Feed it a domain and the tool finds subdomains whose DNS still points to a deprovisioned cloud service an attacker could re-register and hijack. Each dangling record shows the orphaned target and the takeover fingerprint that confirms it. A focused recon build with a demo that flags a real CNAME pointing at an unclaimed bucket.', 'Dale un dominio y la herramienta encuentra subdominios cuyo DNS todavía apunta a un servicio en la nube dado de baja que un atacante podría volver a registrar y secuestrar. Cada registro colgante muestra el destino huérfano y la huella de toma que lo confirma. Una construcción de reconocimiento enfocada con una demo que marca un CNAME real apuntando a un bucket sin reclamar.', 'cybersecurity', '6-12h', 6, 12, 'advanced', '["network","web-security"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Diceware Passphrase Generator with Live Entropy Math', 'Generador de Frases de Contraseña Diceware con Cálculo de Entropía en Vivo', 'Roll virtual dice to build a memorable passphrase from a wordlist, with the tool showing live entropy in bits and an estimated time to crack as each word lands. A side panel explains why six random words beat a tortured Pa$$w0rd. A tiny, satisfying single-feature build that fits comfortably in a one-to-three-hour sprint.', 'Tirá dados virtuales para armar una frase de contraseña memorable desde un diccionario, con la herramienta mostrando la entropía en bits en vivo y un tiempo estimado de crackeo mientras cae cada palabra. Un panel lateral explica por qué seis palabras al azar superan a un torturado Pa$$w0rd. Una construcción pequeña y satisfactoria de una sola función que entra cómoda en un sprint de una a tres horas.', 'cybersecurity', '1-3h', 1, 3, 'beginner', '["cryptography","authentication"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('DNS over HTTPS Sniff Test that Proves Your Lookups Leak', 'Prueba de DNS sobre HTTPS que Demuestra que tus Consultas se Filtran', 'A diagnostic that fires DNS queries both the old plaintext way and over encrypted DoH, then shows what a network eavesdropper would see in each case side by side. It reveals the exact domains your unencrypted lookups expose. A sharp single-screen build that makes an abstract privacy win concrete in a short sprint.', 'Un diagnóstico que dispara consultas DNS tanto a la vieja usanza en texto plano como cifradas por DoH, y luego muestra lado a lado qué vería un espía de red en cada caso. Revela los dominios exactos que exponen tus consultas sin cifrar. Una construcción nítida de una sola pantalla que vuelve concreta una victoria abstracta de privacidad en un sprint corto.', 'cybersecurity', '3-6h', 3, 6, 'intermediate', '["network","privacy"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Malicious Macro Inspector for Office Documents', 'Inspector de Macros Maliciosas para Documentos de Office', 'Upload a Word or Excel file and the tool extracts and deobfuscates its embedded macros, surfacing the suspicious bits: auto-run triggers, shell calls, and base64-encoded payloads that fetch a second stage. Findings are annotated in plain language. A grounded malware-analysis build with a demo that turns a scary attachment into a readable verdict.', 'Subí un archivo de Word o Excel y la herramienta extrae y desofusca sus macros incrustadas, exponiendo las partes sospechosas: disparadores de autoejecución, llamadas al shell y cargas en base64 que descargan una segunda etapa. Los hallazgos se anotan en lenguaje claro. Una construcción de análisis de malware con fundamento, con una demo que convierte un adjunto aterrador en un veredicto legible.', 'cybersecurity', '12-24h', 12, 24, 'advanced', '["malware-analysis","forensics"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Clickjacking Demonstrator that Overlays Any Live Site', 'Demostrador de Clickjacking que Superpone Cualquier Sitio en Vivo', 'A teaching tool that frames a target site under an invisible decoy layer and shows how a user clicking a fake button actually triggers a real action underneath. It then checks the site''s X-Frame-Options and CSP headers to explain why the attack works or is blocked. A vivid, demoable build that makes an underrated web flaw obvious in minutes.', 'Una herramienta didáctica que enmarca un sitio objetivo bajo una capa señuelo invisible y muestra cómo un usuario que hace clic en un botón falso en realidad dispara una acción real por debajo. Luego revisa los encabezados X-Frame-Options y CSP del sitio para explicar por qué el ataque funciona o queda bloqueado. Una construcción vívida y demostrable que vuelve obvia en minutos una falla web subestimada.', 'cybersecurity', '3-6h', 3, 6, 'intermediate', '["web-security","privacy"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Firmware Unpacker that Maps a Router Image''s Innards', 'Desempaquetador de Firmware que Mapea las Entrañas de un Router', 'Drop in a router or IoT firmware blob and the tool carves out the filesystem, locates hardcoded credentials and private keys, and lists outdated binaries with known CVEs. A tree view lets you browse the extracted contents. A solid reverse-engineering build with a demo that finds an admin password baked into a real consumer image.', 'Soltá un blob de firmware de router o IoT y la herramienta extrae el sistema de archivos, localiza credenciales y claves privadas embebidas, y lista binarios desactualizados con CVE conocidos. Una vista de árbol te permite navegar el contenido extraído. Una construcción sólida de ingeniería inversa con una demo que encuentra una contraseña de administrador horneada en una imagen real de consumo.', 'cybersecurity', '24-48h', 24, 48, 'advanced', '["malware-analysis","forensics","network"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Consent Banner Dark Pattern Grader for Any Website', 'Calificador de Patrones Oscuros en Banners de Consentimiento', 'Load any site''s cookie consent banner and the tool grades its dark patterns: a giant Accept button versus a buried Reject, pre-ticked boxes, and reject flows that take five extra clicks. It returns a fairness score and screenshots the offending UI. A quick, opinionated build that turns a familiar annoyance into measurable evidence.', 'Cargá el banner de consentimiento de cookies de cualquier sitio y la herramienta califica sus patrones oscuros: un botón gigante de Aceptar frente a un Rechazar escondido, casillas premarcadas, y flujos de rechazo que requieren cinco clics extra. Devuelve un puntaje de equidad y captura la interfaz infractora. Una construcción rápida y con opinión que convierte una molestia familiar en evidencia medible.', 'cybersecurity', '3-6h', 3, 6, 'beginner', '["privacy","web-security"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('ARP Spoofing Lab that Shows a Man-in-the-Middle Live', 'Laboratorio de ARP Spoofing que Muestra un Hombre en el Medio en Vivo', 'On an isolated test network, this tool demonstrates an ARP spoofing attack: it poisons the cache so traffic between two machines routes through the attacker, then displays the intercepted requests in real time. A toggle enables static ARP entries to show the defense. A hands-on network build that makes a classic LAN attack tangible for judges.', 'En una red de pruebas aislada, esta herramienta demuestra un ataque de ARP spoofing: envenena la caché para que el tráfico entre dos máquinas pase por el atacante, y luego muestra las solicitudes interceptadas en tiempo real. Un interruptor habilita entradas ARP estáticas para mostrar la defensa. Una construcción de redes práctica que vuelve tangible para los jueces un ataque clásico de LAN.', 'cybersecurity', '12-24h', 12, 24, 'advanced', '["network","forensics"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Signed URL Tamper Tester for Cloud Storage Links', 'Probador de Manipulación de URLs Firmadas para Enlaces de Almacenamiento', 'Paste a pre-signed download link from a cloud bucket and the tool dissects its signature, expiry, and permissions, then tries small tampering tricks to see if the server actually enforces them. It flags links that grant more access than intended or never expire. A sharp single-feature build that audits a deceptively risky pattern in minutes.', 'Pegá un enlace de descarga prefirmado de un bucket en la nube y la herramienta analiza su firma, vencimiento y permisos, y luego prueba pequeños trucos de manipulación para ver si el servidor realmente los hace cumplir. Marca los enlaces que otorgan más acceso del previsto o que nunca vencen. Una construcción nítida de una sola función que audita en minutos un patrón engañosamente riesgoso.', 'cybersecurity', '3-6h', 3, 6, 'intermediate', '["web-security","cryptography"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Browser Fingerprint Revealer that Shows How Trackable You Are', 'Revelador de Huella del Navegador que Muestra qué tan Rastreable Sos', 'Open the page and it silently collects the signals advertisers use to fingerprint you, canvas rendering, fonts, screen size, audio stack, then computes how unique your browser is among millions. It shows which signals leak the most and how to blunt them. A compelling privacy build with an instant aha moment for any visitor in the demo.', 'Abrí la página y recolecta en silencio las señales que usan los anunciantes para identificarte, renderizado de canvas, fuentes, tamaño de pantalla, pila de audio, y luego calcula qué tan único es tu navegador entre millones. Muestra qué señales filtran más y cómo atenuarlas. Una construcción de privacidad convincente con un momento de revelación instantáneo para cualquier visitante en la demo.', 'cybersecurity', '6-12h', 6, 12, 'intermediate', '["privacy","web-security"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('IDOR Hunter that Walks Object IDs to Find Leaks', 'Cazador de IDOR que Recorre IDs de Objetos para Hallar Fugas', 'Authenticated as a normal user, the tool methodically increments and swaps object identifiers across an app''s endpoints to surface records you should not be able to read. Each hit shows the request, the leaked data, and the missing authorization check. A focused web-security build whose demo quietly pulls another user''s invoice from a test app.', 'Autenticada como un usuario común, la herramienta incrementa e intercambia metódicamente identificadores de objetos en los endpoints de una app para exponer registros que no deberías poder leer. Cada acierto muestra la solicitud, los datos filtrados y la verificación de autorización faltante. Una construcción de seguridad web enfocada cuya demo extrae sigilosamente la factura de otro usuario de una app de prueba.', 'cybersecurity', '6-12h', 6, 12, 'intermediate', '["web-security","authentication"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Visual Encryption Padlock that Shows AES Mode Pitfalls', 'Candado de Cifrado Visual que Muestra los Riesgos de los Modos AES', 'Encrypt an image with AES in different modes and watch the result render: ECB leaves the ghostly outline of the original visible, while CBC and GCM turn it to noise. Side panels explain why mode choice matters and where an IV must be unique. A tight, visual single-feature build that makes a subtle crypto mistake unforgettable.', 'Cifrá una imagen con AES en distintos modos y mirá cómo se renderiza el resultado: ECB deja visible el contorno fantasmal del original, mientras que CBC y GCM lo convierten en ruido. Paneles laterales explican por qué importa la elección del modo y dónde un IV debe ser único. Una construcción visual nítida de una sola función que vuelve inolvidable un error sutil de criptografía.', 'cybersecurity', '3-6h', 3, 6, 'intermediate', '["cryptography","ctf"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Phishing Domain Lookalike Detector with Homograph Alerts', 'Detector de Dominios Falsos de Phishing con Alertas de Homógrafos', 'Enter a brand and the tool generates the lookalike domains attackers register, swapped letters, extra hyphens, and Unicode homographs that render identically, then checks which are already live and serving content. Each result shows the trick used and a screenshot. A practical build with a demo that surfaces real squatted domains around a familiar brand.', 'Ingresá una marca y la herramienta genera los dominios parecidos que registran los atacantes, letras cambiadas, guiones extra y homógrafos Unicode que se ven idénticos, y luego revisa cuáles ya están activos sirviendo contenido. Cada resultado muestra el truco usado y una captura. Una construcción práctica con una demo que expone dominios ocupados reales en torno a una marca conocida.', 'cybersecurity', '6-12h', 6, 12, 'intermediate', '["web-security","network"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Side-Channel Timing Lab that Leaks a Secret Comparison', 'Laboratorio de Canal Lateral que Filtra una Comparación Secreta', 'A guided lab that demonstrates a timing side channel: a naive string compare that returns early on the first wrong character, letting an attacker recover a secret token byte by byte from response times. A live chart shows the timing peaks giving it away, then a constant-time fix flattens them. An eye-opening crypto build that reveals an invisible leak.', 'Un laboratorio guiado que demuestra un canal lateral de tiempo: una comparación de cadenas ingenua que retorna temprano en el primer carácter incorrecto, permitiendo a un atacante recuperar un token secreto byte por byte a partir de los tiempos de respuesta. Un gráfico en vivo muestra los picos de tiempo que lo delatan, y luego un arreglo de tiempo constante los aplana. Una construcción de criptografía reveladora que expone una fuga invisible.', 'cybersecurity', '12-24h', 12, 24, 'advanced', '["cryptography","ctf"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Container Image Scanner that Ranks Layers by Risk', 'Escáner de Imágenes de Contenedor que Ordena Capas por Riesgo', 'Point it at a Docker image and the tool inspects each layer for vulnerable packages, leaked secrets, and a root user that should be dropped, then ranks the layers by how much risk each one adds. A diff view shows which base image bloated the attack surface. A practical DevSecOps build with a demo that condemns a popular but bloated base image.', 'Apuntalo a una imagen de Docker y la herramienta inspecciona cada capa en busca de paquetes vulnerables, secretos filtrados y un usuario root que debería descartarse, y luego ordena las capas según cuánto riesgo aporta cada una. Una vista de diferencias muestra qué imagen base infló la superficie de ataque. Una construcción práctica de DevSecOps con una demo que condena una imagen base popular pero inflada.', 'cybersecurity', '12-24h', 12, 24, 'intermediate', '["malware-analysis","web-security"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('WebSocket Traffic Inspector that Replays a Live Channel', 'Inspector de Tráfico WebSocket que Reproduce un Canal en Vivo', 'A proxy that captures the WebSocket messages flowing between a web app and its server, decodes the frames, and lets you edit and replay them to probe for missing authorization on real-time actions. A timeline view groups messages by intent. A sharp build for testing the often-overlooked security of live channels, with an instantly demoable replay.', 'Un proxy que captura los mensajes WebSocket que circulan entre una app web y su servidor, decodifica los frames y te permite editarlos y reproducirlos para sondear autorización faltante en acciones en tiempo real. Una vista de línea de tiempo agrupa los mensajes por intención. Una construcción nítida para probar la seguridad a menudo ignorada de los canales en vivo, con una reproducción demostrable al instante.', 'cybersecurity', '6-12h', 6, 12, 'advanced', '["web-security","network"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Git History Secret Scanner that Catches Deleted Keys', 'Escáner de Historial Git que Atrapa Claves Borradas', 'Run it on any repo and the tool walks the full commit history, not just the current tree, to find API keys and passwords that were committed and later deleted but still live in the git log forever. Each hit shows the commit, the file, and the moment it was removed. A quick, high-value build with a demo that resurrects a secret from a tidy-looking repo.', 'Ejecutala en cualquier repo y la herramienta recorre todo el historial de commits, no solo el árbol actual, para encontrar claves de API y contraseñas que se commitearon y luego se borraron pero siguen viviendo para siempre en el log de git. Cada acierto muestra el commit, el archivo y el momento en que se eliminó. Una construcción rápida y de alto valor con una demo que resucita un secreto de un repo de apariencia prolija.', 'cybersecurity', '1-3h', 1, 3, 'beginner', '["web-security","forensics"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Rate Limit Stress Tester that Maps an API''s Real Limits', 'Probador de Límites de Tasa que Mapea los Topes Reales de una API', 'Pointed at your own API, this tool ramps request volume across endpoints and headers to discover where rate limiting actually kicks in and where it is silently absent. A heatmap shows which routes an attacker could hammer for free. A focused build that turns a vague worry about abuse into a concrete map of weak spots in a short sprint.', 'Apuntada a tu propia API, esta herramienta aumenta el volumen de solicitudes en endpoints y encabezados para descubrir dónde se activa realmente el límite de tasa y dónde está ausente en silencio. Un mapa de calor muestra qué rutas podría martillar gratis un atacante. Una construcción enfocada que convierte una preocupación vaga sobre el abuso en un mapa concreto de puntos débiles en un sprint corto.', 'cybersecurity', '3-6h', 3, 6, 'intermediate', '["network","web-security"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('SBOM Diff Tracker that Alerts When a Dependency Turns Risky', 'Rastreador de Diferencias de SBOM que Alerta cuando una Dependencia se Vuelve Riesgosa', 'Generate a software bill of materials for a project, then re-run it later and the tool diffs the two: new packages, version bumps, and any component that just acquired a published vulnerability or changed maintainers suspiciously. A timeline shows how your supply-chain risk drifted. A practical build that makes dependency rot visible over time.', 'Generá una lista de materiales de software para un proyecto, luego volvé a correrla más tarde y la herramienta compara las dos: paquetes nuevos, saltos de versión, y cualquier componente que acaba de adquirir una vulnerabilidad publicada o cambió de mantenedores de forma sospechosa. Una línea de tiempo muestra cómo se desvió tu riesgo de cadena de suministro. Una construcción práctica que vuelve visible la pudrición de dependencias con el tiempo.', 'cybersecurity', '12-24h', 12, 24, 'intermediate', '["malware-analysis","web-security"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Encrypted File Vault with a Convincing Decoy Mode', 'Bóveda de Archivos Cifrada con un Modo Señuelo Convincente', 'A vault that encrypts your files but offers two passwords: the real one opens your secrets, while a duress password unlocks a plausible decoy set, giving deniable encryption for high-risk users. The demo shows the same vault revealing two completely different worlds depending on the key. A meaningful crypto build that explores deniability as a feature.', 'Una bóveda que cifra tus archivos pero ofrece dos contraseñas: la real abre tus secretos, mientras que una contraseña de coacción desbloquea un conjunto señuelo plausible, brindando cifrado negable para usuarios de alto riesgo. La demo muestra la misma bóveda revelando dos mundos completamente distintos según la clave. Una construcción de criptografía con sentido que explora la negabilidad como funcionalidad.', 'cybersecurity', '12-24h', 12, 24, 'advanced', '["cryptography","privacy"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Phishing Simulation Kit that Trains a Team Safely', 'Kit de Simulación de Phishing que Entrena a un Equipo de Forma Segura', 'An internal training tool that sends consenting teammates realistic but harmless phishing emails, tracks who clicks, and instantly shows them the tells they missed instead of shaming them. A dashboard charts the team getting savvier over each campaign. A fuller build with real human-factor value and a demo that runs a campaign end to end.', 'Una herramienta de capacitación interna que envía a compañeros que dieron su consentimiento correos de phishing realistas pero inofensivos, registra quién hace clic y al instante les muestra las señales que pasaron por alto en lugar de avergonzarlos. Un tablero grafica cómo el equipo se vuelve más astuto con cada campaña. Una construcción más completa con valor real de factor humano y una demo que corre una campaña de principio a fin.', 'cybersecurity', '24-48h', 24, 48, 'intermediate', '["web-security","privacy"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Race Condition Exploiter that Doubles a Wallet Balance', 'Explotador de Condiciones de Carrera que Duplica un Saldo de Billetera', 'Against a mock wallet API, this tool fires many withdrawal requests in the same instant to exploit a race condition and spend the same balance twice. A live ledger shows the impossible negative balance appearing, then a fix using atomic locks blocks the replay. A vivid build that makes a notoriously slippery class of bug concrete for judges.', 'Contra una API de billetera simulada, esta herramienta dispara muchas solicitudes de retiro en el mismo instante para explotar una condición de carrera y gastar el mismo saldo dos veces. Un libro mayor en vivo muestra aparecer el saldo negativo imposible, y luego un arreglo con bloqueos atómicos impide la repetición. Una construcción vívida que vuelve concreta para los jueces una clase de bug notoriamente escurridiza.', 'cybersecurity', '12-24h', 12, 24, 'advanced', '["web-security","ctf"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Wordlist Forge that Builds Targeted Guesses from a Profile', 'Forja de Diccionarios que Construye Conjeturas a Partir de un Perfil', 'A red-team helper that takes public facts about a target, names, pets, birth years, employer, and forges a smart password wordlist by applying the mangling rules people actually use. A counter shows how few guesses it takes to cover common patterns. A sharp single-purpose build that drives home why personal info makes terrible passwords.', 'Un asistente de red team que toma datos públicos de un objetivo, nombres, mascotas, años de nacimiento, empleador, y forja un diccionario de contraseñas inteligente aplicando las reglas de modificación que la gente realmente usa. Un contador muestra qué pocas conjeturas hacen falta para cubrir los patrones comunes. Una construcción nítida de un solo propósito que deja claro por qué la información personal hace contraseñas pésimas.', 'cybersecurity', '3-6h', 3, 6, 'intermediate', '["authentication","ctf"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Turbine Bird-Strike Forecaster from Migration and Wind Data', 'Pronosticador de choques de aves en turbinas con datos de migración y viento', 'Pull open migratory-bird tracks and a wind farm''s hourly forecast, then predict the high-risk windows when flocks and gusts line up over the blades. The tool ranks each turbine by collision odds for the next 48 hours so operators can curtail only the dangerous ones. The demo drops a flock path over a map and watches the at-risk turbines flash.', 'Toma rutas abiertas de aves migratorias y el pronóstico horario de un parque eólico, y predice las ventanas de alto riesgo cuando bandadas y ráfagas coinciden sobre las palas. La herramienta ordena cada turbina por probabilidad de choque para las próximas 48 horas, así los operadores frenan solo las peligrosas. La demo lanza una ruta de bandada sobre un mapa y ve parpadear las turbinas en riesgo.', 'environment', '12-24h', 12, 24, 'intermediate', '["biodiversity","energy","climate-data"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Watershed Flow Predictor that Forecasts a River''s Next Week', 'Predictor de caudal que pronostica la próxima semana de un río', 'Feed a watershed''s recent rainfall, snowpack and gauge readings and get a seven-day flow forecast for a chosen river point, flagging when it crosses drought or flood thresholds. The hook is splitting the watershed into upstream sub-basins so users see which tributary drives the change. The demo lets a judge pick a river and scrub a slider through the week ahead.', 'Ingresa la lluvia reciente, el manto de nieve y las lecturas de aforo de una cuenca y obtén un pronóstico de caudal a siete días para un punto del río, marcando cuándo cruza umbrales de sequía o crecida. El gancho es dividir la cuenca en subcuencas aguas arriba para ver qué afluente impulsa el cambio. La demo deja al jurado elegir un río y deslizar por la semana siguiente.', 'environment', '24-48h', 24, 48, 'advanced', '["water","climate-data"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Rock-Weathering Carbon Calculator for a Farm Field', 'Calculadora de carbono por meteorización de roca para un campo agrícola', 'Enhanced rock weathering spreads crushed basalt on fields to pull CO2 from the air. This tool takes a field''s size, soil pH and rainfall and estimates how much basalt to apply and how much carbon it could capture over years, with the uncertainty range shown honestly. The demo draws a field on a map and outputs a tonnage and a cost-per-tonne badge.', 'La meteorización mejorada de roca esparce basalto triturado en campos para capturar CO2 del aire. Esta herramienta toma el tamaño del campo, el pH del suelo y la lluvia, y estima cuánto basalto aplicar y cuánto carbono podría capturar en años, mostrando el rango de incertidumbre con honestidad. La demo dibuja un campo en un mapa y entrega un tonelaje y una insignia de costo por tonelada.', 'environment', '6-12h', 6, 12, 'intermediate', '["agriculture","climate-data"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Surplus-Harvest Marketplace that Rescues Bruised Local Produce', 'Mercado de excedentes que rescata productos locales magullados', 'A lightweight marketplace where small farmers list bruised or surplus produce by the box at a discount and nearby buyers claim it before it rots. The twist is a same-day expiry clock on each listing that drops the price as the deadline nears, turning waste into a flash sale. The demo posts a crate, watches the price slide, and confirms a pickup.', 'Un mercado liviano donde pequeños agricultores publican productos magullados o excedentes por caja con descuento y compradores cercanos los reclaman antes de que se pudran. El giro es un reloj de vencimiento del mismo día en cada anuncio que baja el precio al acercarse la fecha, convirtiendo el desperdicio en oferta relámpago. La demo publica un cajón, ve caer el precio y confirma un retiro.', 'environment', '12-24h', 12, 24, 'intermediate', '["waste","agriculture","transport"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Camera-Trap Triage that Sorts Wildlife Photos from Empty Frames', 'Triaje de cámaras trampa que separa fotos de fauna de cuadros vacíos', 'Conservation camera traps spit out tens of thousands of photos, most of them empty triggers from wind. Drop a folder and the tool flags which frames actually contain an animal, groups them by likely species, and exports a tidy sightings sheet. The hook is killing the empty-frame slog that buries volunteers. The demo ingests a messy folder and surfaces only the real sightings.', 'Las cámaras trampa de conservación escupen decenas de miles de fotos, casi todas disparos vacíos por el viento. Suelta una carpeta y la herramienta marca qué cuadros contienen un animal, los agrupa por especie probable y exporta una planilla ordenada de avistajes. El gancho es eliminar el tedio de los cuadros vacíos que sepulta a los voluntarios. La demo ingiere una carpeta caótica y muestra solo los avistajes reales.', 'environment', '6-12h', 6, 12, 'intermediate', '["biodiversity"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('EV Charger Siting Map that Finds Gaps Along a Highway', 'Mapa de ubicación de cargadores que halla huecos en una ruta', 'Pick a highway corridor and the tool overlays existing charging stations against realistic EV range, then highlights the dead zones where a driver would run out before the next plug. It ranks candidate sites by how many stranded miles each new charger would fix. The demo traces a corridor and lights up the single best spot to add a station.', 'Elige un corredor vial y la herramienta superpone las estaciones de carga existentes contra la autonomía real de un EV, y resalta las zonas muertas donde un conductor se quedaría sin batería antes del próximo enchufe. Ordena sitios candidatos según cuántos kilómetros varados arreglaría cada cargador nuevo. La demo traza un corredor e ilumina el mejor punto para sumar una estación.', 'environment', '6-12h', 6, 12, 'intermediate', '["transport","energy","climate-data"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Heat-Pump Switch Advisor that Compares Bills Before You Buy', 'Asesor de cambio a bomba de calor que compara facturas antes de comprar', 'Enter your home''s heating fuel, climate zone and last winter''s bills, and the tool models what a heat pump would cost to run instead, month by month, including the cold snaps where it struggles. It returns a payback timeline and the carbon saved. The demo flips a slider for local electricity prices and watches the break-even year move.', 'Ingresa el combustible de calefacción de tu casa, la zona climática y las facturas del último invierno, y la herramienta modela cuánto costaría operar una bomba de calor, mes a mes, incluso en las olas de frío donde le cuesta. Devuelve un plazo de recuperación y el carbono ahorrado. La demo mueve un control para los precios locales de electricidad y ve cambiar el año de equilibrio.', 'environment', '3-6h', 3, 6, 'beginner', '["energy","climate-data"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Coral Bleaching Watcher that Alerts on Marine Heat Spikes', 'Vigía de blanqueo de coral que alerta ante picos de calor marino', 'Track a reef of your choice using open sea-surface temperature feeds and raise an alert when accumulated heat crosses the bleaching threshold that kills coral. The hook is the degree-heating-week meter that fills like a thermometer as danger builds, days before damage is visible. The demo picks a reef and replays a past marine heatwave to show the gauge redline.', 'Sigue un arrecife elegido usando feeds abiertos de temperatura superficial del mar y emite una alerta cuando el calor acumulado cruza el umbral de blanqueo que mata al coral. El gancho es el medidor de semanas-grado de calor que se llena como un termómetro a medida que crece el peligro, días antes de ver el daño. La demo elige un arrecife y reproduce una ola de calor marina pasada para mostrar la aguja en rojo.', 'environment', '6-12h', 6, 12, 'intermediate', '["biodiversity","water","climate-data"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Pollen Forecast Map that Warns Allergy Sufferers by Block', 'Mapa de pronóstico de polen que avisa a alérgicos por cuadra', 'Combine local tree-species data, bloom timing and weather to forecast neighborhood pollen levels for the next few days, broken down by the plants that trigger most people. Users set their personal triggers and get a simple green-yellow-red day rating. The demo lets a judge enter a city and a sensitivity and see tomorrow''s risk light up the map.', 'Combina datos de especies de árboles locales, tiempos de floración y clima para pronosticar niveles de polen del barrio para los próximos días, desglosados por las plantas que más afectan. Los usuarios fijan sus desencadenantes y reciben una calificación diaria verde-amarillo-rojo. La demo deja al jurado ingresar una ciudad y una sensibilidad y ver el riesgo de mañana iluminar el mapa.', 'environment', '6-12h', 6, 12, 'intermediate', '["air-quality","biodiversity","climate-data"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Wildfire Smoke Window Coach that Times When to Open Up', 'Coach de ventanas ante humo de incendios que indica cuándo airear', 'During wildfire season, this tool watches outdoor air quality near you and tells you the exact hours it''s safe to open windows and air out the house versus seal up. The hook is a 24-hour timeline that shades the clean and dirty hours so you plan ventilation around the smoke. The demo replays a smoky day and shows the one good window to open.', 'En temporada de incendios, esta herramienta vigila la calidad del aire exterior cerca tuyo y te dice las horas exactas en que conviene abrir ventanas y ventilar la casa frente a cuándo sellarla. El gancho es una línea de tiempo de 24 horas que sombrea las horas limpias y sucias para planear la ventilación según el humo. La demo reproduce un día con humo y muestra la única buena ventana para abrir.', 'environment', '3-6h', 3, 6, 'beginner', '["air-quality","climate-data"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Greywater Reuse Sizer for a Single Household''s Garden', 'Dimensionador de reúso de aguas grises para el jardín de un hogar', 'Tell the tool how many people live in your home and what you grow, and it estimates how much shower and laundry greywater you could safely divert to the garden each week, and which plants tolerate it. It returns a simple plumbing layout sketch and the freshwater saved. The demo sets a household size and watches the litres-saved counter climb.', 'Indica cuántas personas viven en tu casa y qué cultivas, y la herramienta estima cuánta agua gris de ducha y lavarropas podrías derivar al jardín de forma segura cada semana, y qué plantas la toleran. Devuelve un croquis simple de plomería y el agua dulce ahorrada. La demo fija el tamaño del hogar y ve subir el contador de litros ahorrados.', 'environment', '3-6h', 3, 6, 'beginner', '["water","agriculture"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Cold-Chain Spoilage Predictor that Flags At-Risk Food Shipments', 'Predictor de deterioro en cadena de frío que marca envíos en riesgo', 'Upload a refrigerated shipment''s temperature log and route, and the tool estimates remaining shelf life at each stop, flagging the legs where a warm spike already burned through days of freshness. The hook is turning a noisy sensor trace into a clear ''eat-by'' shift so dispatchers reroute the riskiest pallets first. The demo loads a log and ranks pallets by spoilage risk.', 'Sube el registro de temperatura y la ruta de un envío refrigerado, y la herramienta estima la vida útil restante en cada parada, marcando los tramos donde un pico de calor ya consumió días de frescura. El gancho es convertir una traza ruidosa de sensores en un claro corrimiento de ''consumir antes de'' para que los despachadores reencaminen primero los pallets más riesgosos. La demo carga un registro y ordena pallets por riesgo de deterioro.', 'environment', '6-12h', 6, 12, 'intermediate', '["waste","transport","agriculture"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Light-Pollution Star Map that Scores Your Sky for Stargazing', 'Mapa de contaminación lumínica que puntúa tu cielo para observar estrellas', 'Enter a location and the tool grades the night sky from open light-pollution data, then names the nearest darker spot within a chosen drive time where the Milky Way becomes visible. The hook pairs a Bortle-style sky score with a concrete ''drive 40 minutes here'' suggestion. The demo drops a pin in a city and reveals the closest truly dark patch.', 'Ingresa una ubicación y la herramienta califica el cielo nocturno con datos abiertos de contaminación lumínica, y luego nombra el punto más oscuro cercano dentro de un tiempo de viaje elegido donde la Vía Láctea se vuelve visible. El gancho combina un puntaje de cielo estilo Bortle con una sugerencia concreta de ''maneja 40 minutos hasta aquí''. La demo pone un pin en una ciudad y revela el rincón realmente oscuro más cercano.', 'environment', '3-6h', 3, 6, 'beginner', '["climate-data","biodiversity"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Microplastic Sampling Logger that Maps Citizen River Tests', 'Registro de muestreo de microplásticos que mapea tests ciudadanos de ríos', 'A field-friendly logger where volunteers photograph a filtered water sample, count visible fibers and pin the spot on a shared river map. The hook is a standard photo grid overlay that makes rough counts comparable across people, building a heat map of where plastic concentrates. The demo logs two samples and watches a polluted bend of the river darken.', 'Un registro apto para campo donde voluntarios fotografían una muestra de agua filtrada, cuentan fibras visibles y fijan el punto en un mapa fluvial compartido. El gancho es una grilla estándar sobre la foto que hace comparables los conteos aproximados entre personas, armando un mapa de calor de dónde se concentra el plástico. La demo registra dos muestras y ve oscurecerse un recodo contaminado del río.', 'environment', '12-24h', 12, 24, 'intermediate', '["water","waste","biodiversity"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Grid Carbon Clock that Shows the Cleanest Hour to Run Anything', 'Reloj de carbono de la red que muestra la hora más limpia para todo', 'A single-screen widget that reads your region''s live grid carbon intensity and shows, in plain terms, whether right now is a clean or dirty hour to run a dishwasher, charge a car or train a model. The hook is a 24-hour ring that marks the greenest upcoming window. A sharp one-feature build that''s instantly demoable in a short sprint.', 'Un widget de una sola pantalla que lee la intensidad de carbono en vivo de la red de tu región y muestra, en términos simples, si ahora es una hora limpia o sucia para usar el lavavajillas, cargar un auto o entrenar un modelo. El gancho es un anillo de 24 horas que marca la próxima ventana más verde. Una construcción nítida de una función, demostrable al instante en un sprint corto.', 'environment', '1-3h', 1, 3, 'beginner', '["energy","climate-data"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Tide and Storm-Surge Dial for a Coastal Address', 'Dial de marea y marejada para una dirección costera', 'Type a coastal address and a single dial shows when the next high tide combines with forecast surge to threaten low spots, with a clear ''wet feet by 6pm'' style warning. The hook is fusing routine tide tables with storm forecasts into one at-a-glance risk for the day. A tight single-screen tool that''s perfect for a very short sprint.', 'Escribe una dirección costera y un solo dial muestra cuándo la próxima pleamar se combina con la marejada pronosticada para amenazar zonas bajas, con un aviso claro estilo ''pies mojados a las 18 h''. El gancho es fusionar las tablas de marea de rutina con los pronósticos de tormenta en un único riesgo de un vistazo para el día. Una herramienta ajustada de una pantalla, ideal para un sprint muy corto.', 'environment', '1-3h', 1, 3, 'beginner', '["water","climate-data"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Crop Disease Spotter that Reads a Leaf Photo in the Field', 'Detector de enfermedades de cultivo que lee una foto de hoja en el campo', 'A farmer snaps a struggling leaf and the tool names the likely disease or deficiency, explains the telltale pattern, and suggests a low-chemical first response sized to a smallholder plot. The hook is pairing the diagnosis with a ''watch these nearby plants next'' early-spread alert. The demo photographs a blighted leaf and returns the call with confidence.', 'Un agricultor fotografía una hoja enferma y la herramienta nombra la enfermedad o deficiencia probable, explica el patrón delator y sugiere una primera respuesta con poco químico dimensionada a una parcela pequeña. El gancho es unir el diagnóstico con una alerta de propagación temprana ''vigila estas plantas cercanas''. La demo fotografía una hoja con tizón y devuelve el veredicto con confianza.', 'environment', '6-12h', 6, 12, 'intermediate', '["agriculture","biodiversity"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Glacier Retreat Slider that Animates Ice Loss Year by Year', 'Deslizador de retroceso glaciar que anima la pérdida de hielo año a año', 'Pick a glacier and drag a slider to watch its outline shrink across decades of satellite imagery, with a counter showing area lost and water released. The hook is making an abstract trend visceral by morphing the ice edge under your finger. A focused data-viz build that fits a short sprint and lands hard in a demo when a judge scrubs their local glacier.', 'Elige un glaciar y arrastra un deslizador para ver su contorno encogerse a lo largo de décadas de imágenes satelitales, con un contador que muestra el área perdida y el agua liberada. El gancho es volver visceral una tendencia abstracta al transformar el borde del hielo bajo tu dedo. Una construcción enfocada en visualización que cabe en un sprint corto y impacta cuando el jurado desliza su glaciar local.', 'environment', '1-3h', 1, 3, 'beginner', '["climate-data","water"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Building Retrofit Ranker that Picks the Highest-Impact Upgrade', 'Clasificador de reformas que elige la mejora de mayor impacto', 'Enter an old building''s size, age and energy bills and the tool ranks retrofits, from insulation to windows to a heat pump, by carbon saved per dollar, so owners do the smartest thing first instead of the loudest. The hook is the impact-per-cost leaderboard that reshuffles as you tweak budget. The demo loads a building and reveals its top three moves.', 'Ingresa el tamaño, la antigüedad y las facturas de energía de un edificio viejo y la herramienta clasifica las reformas, de aislación a ventanas a bomba de calor, por carbono ahorrado por dólar, para que los dueños hagan primero lo más inteligente y no lo más ruidoso. El gancho es la tabla de impacto por costo que se reordena al ajustar el presupuesto. La demo carga un edificio y revela sus tres mejores movidas.', 'environment', '12-24h', 12, 24, 'intermediate', '["energy","climate-data"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Roadkill Hotspot Mapper that Flags Where to Build Crossings', 'Mapeador de puntos de atropello que indica dónde construir pasos de fauna', 'Drivers and rangers log animal roadkill with a quick photo and pin, and the tool clusters the data to reveal the road segments where wildlife crossings would save the most animals. The hook is turning grim, scattered sightings into a ranked case for specific underpasses. The demo adds a few pins and watches a deadly stretch of road emerge as a hotspot.', 'Conductores y guardaparques registran atropellos de animales con una foto rápida y un pin, y la herramienta agrupa los datos para revelar los tramos de ruta donde los pasos de fauna salvarían más animales. El gancho es transformar avistajes sombríos y dispersos en un caso ordenado para pasos específicos. La demo agrega unos pines y ve emerger un tramo mortal de ruta como punto crítico.', 'environment', '6-12h', 6, 12, 'intermediate', '["biodiversity","transport"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Community Fridge Network that Routes Surplus Meals Before Closing', 'Red de heladeras comunitarias que enruta comidas excedentes antes de cerrar', 'Cafes and shops post leftover meals at closing time, and the tool routes a volunteer to collect and drop them at the nearest community fridge before they spoil. The hook is a closing-time countdown that batches nearby donations into one efficient pickup loop. The demo posts three donations and draws the shortest rescue route on a map.', 'Cafés y comercios publican comidas sobrantes a la hora de cierre, y la herramienta enruta a un voluntario para recogerlas y dejarlas en la heladera comunitaria más cercana antes de que se echen a perder. El gancho es una cuenta regresiva de cierre que agrupa donaciones cercanas en un solo recorrido eficiente de retiro. La demo publica tres donaciones y dibuja la ruta de rescate más corta en un mapa.', 'environment', '12-24h', 12, 24, 'intermediate', '["waste","transport"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Packaging Recyclability Grader from a Photo of the Label', 'Calificador de reciclabilidad de envases desde una foto de la etiqueta', 'Snap the back of a package and the tool reads the material codes and layers, then grades how recyclable it really is in the user''s local system, calling out the sneaky mixed-material parts that quietly go to landfill. The hook is exposing the gap between the green logo and reality. The demo photographs a snack wrapper and returns a blunt recyclability grade.', 'Fotografía el reverso de un envase y la herramienta lee los códigos de material y las capas, y luego califica cuán reciclable es realmente en el sistema local del usuario, señalando las partes engañosas de material mixto que en silencio van al relleno. El gancho es exponer la brecha entre el logo verde y la realidad. La demo fotografía la envoltura de un snack y devuelve una calificación de reciclabilidad sin rodeos.', 'environment', '6-12h', 6, 12, 'intermediate', '["waste"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Shade-Walk Router that Finds the Coolest Path on a Hot Day', 'Enrutador de paseo a la sombra que halla el camino más fresco en un día caluroso', 'On a scorching day, enter two points and the tool routes you along the shadiest streets using building heights and tree canopy instead of the shortest line, cutting heat exposure for kids and the elderly. The hook is a sun-versus-shade overlay that recolors the route by time of day. The demo picks an afternoon hour and draws the cool path across town.', 'En un día abrasador, ingresa dos puntos y la herramienta te enruta por las calles más sombreadas usando alturas de edificios y copa de árboles en vez de la línea más corta, reduciendo la exposición al calor para niños y mayores. El gancho es una capa de sol versus sombra que recolorea la ruta según la hora del día. La demo elige una hora de la tarde y dibuja el camino fresco por la ciudad.', 'environment', '12-24h', 12, 24, 'intermediate', '["transport","climate-data","biodiversity"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Septic and Sanitation Health Tracker for Rural Wells', 'Rastreador de salud de pozos sépticos y agua para pozos rurales', 'Rural households log septic pump dates, well distance and recent rain, and the tool estimates the contamination risk to their drinking water, nudging when to test and when heavy rain raises the odds. The hook is connecting septic upkeep to well safety in plain terms families actually act on. The demo enters a homestead''s layout and flips its risk to red after a storm.', 'Hogares rurales registran fechas de vaciado séptico, distancia al pozo y lluvia reciente, y la herramienta estima el riesgo de contaminación del agua potable, avisando cuándo testear y cuándo la lluvia fuerte eleva las probabilidades. El gancho es conectar el mantenimiento séptico con la seguridad del pozo en términos que las familias realmente apliquen. La demo ingresa el trazado de una finca y pone su riesgo en rojo tras una tormenta.', 'environment', '6-12h', 6, 12, 'intermediate', '["water","agriculture"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Second-Life Battery Matcher that Pairs Old EV Packs to Homes', 'Emparejador de baterías de segunda vida que une packs de EV viejos con hogares', 'Retired EV batteries still hold useful capacity. Enter a pack''s remaining health and a home''s daily power pattern, and the tool sizes how much backup or solar storage it could provide and the years left before recycling. The hook is the reuse-before-recycle calculator that quantifies a pack''s second act. The demo loads a tired pack and matches it to a household''s needs.', 'Las baterías de EV retiradas aún conservan capacidad útil. Ingresa la salud restante de un pack y el patrón diario de consumo de un hogar, y la herramienta dimensiona cuánto respaldo o almacenamiento solar podría dar y los años que quedan antes de reciclar. El gancho es la calculadora de reúso-antes-de-reciclar que cuantifica el segundo acto de un pack. La demo carga un pack gastado y lo empareja con las necesidades de un hogar.', 'environment', '12-24h', 12, 24, 'advanced', '["energy","waste"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Wetland Restoration Planner that Maps Where to Rewet Land', 'Planificador de restauración de humedales que mapea dónde rehumedecer la tierra', 'Drained wetlands leak carbon and floods. Draw a degraded area and the tool uses elevation and water-flow data to show which parcels would naturally re-flood if a ditch were blocked, ranking them by carbon stored and flood buffering gained. The hook is finding the cheap, high-leverage plug points. The demo sketches a marsh and highlights the one ditch to dam first.', 'Los humedales drenados liberan carbono y crecidas. Dibuja un área degradada y la herramienta usa datos de elevación y flujo de agua para mostrar qué parcelas se reinundarían naturalmente si se bloqueara una zanja, ordenándolas por carbono almacenado y amortiguación de crecidas ganada. El gancho es hallar los puntos de tapón baratos y de alto efecto. La demo bosqueja un pantano y resalta la primera zanja a represar.', 'environment', '24-48h', 24, 48, 'advanced', '["water","biodiversity","climate-data"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Curbside Pickup Optimizer that Trims a Garbage Truck''s Route', 'Optimizador de recolección que recorta la ruta de un camión de basura', 'Feed a neighborhood''s bin locations and pickup days, and the tool plans a shorter collection route that cuts fuel and idling, and suggests which low-fill bins could shift to every-other-week. The hook is showing the diesel and CO2 saved by reordering stops, not buying anything new. The demo loads a route and animates the truck taking the leaner path.', 'Ingresa las ubicaciones de contenedores de un barrio y sus días de retiro, y la herramienta planea una ruta de recolección más corta que reduce combustible y ralentí, y sugiere qué contenedores poco llenos podrían pasar a una semana de por medio. El gancho es mostrar el diésel y el CO2 ahorrados al reordenar paradas, sin comprar nada nuevo. La demo carga una ruta y anima al camión tomando el camino más eficiente.', 'environment', '12-24h', 12, 24, 'intermediate', '["waste","transport","energy"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Frog Chorus Counter that Gauges Wetland Health by Ear', 'Contador de coro de ranas que mide la salud del humedal por el oído', 'Record a few minutes of a pond at dusk and the tool separates the overlapping frog calls, names the species and estimates how many are calling, since amphibian chorus richness signals wetland health. The hook is turning a noisy night recording into a clear biodiversity score. The demo plays a marsh clip and breaks it into a labeled list of callers.', 'Graba unos minutos de un estanque al atardecer y la herramienta separa los cantos de rana superpuestos, nombra las especies y estima cuántas cantan, ya que la riqueza del coro de anfibios indica la salud del humedal. El gancho es convertir una grabación nocturna ruidosa en un puntaje claro de biodiversidad. La demo reproduce un clip de pantano y lo descompone en una lista etiquetada de cantores.', 'environment', '6-12h', 6, 12, 'intermediate', '["biodiversity","water"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Solar Self-Consumption Tuner that Schedules Appliances to the Sun', 'Afinador de autoconsumo solar que agenda electrodomésticos al sol', 'For a home with rooftop solar, enter the panel size and daily routine, and the tool builds an appliance schedule that runs the dishwasher, dryer and car charging during peak production so less power is sold cheap and re-bought dear. The hook is the self-consumption gauge that climbs as you shuffle chores. The demo drags a wash cycle into midday and watches savings rise.', 'Para un hogar con solar en el techo, ingresa el tamaño de paneles y la rutina diaria, y la herramienta arma un cronograma que corre el lavavajillas, el secarropas y la carga del auto durante la producción pico, para vender menos energía barata y recomprarla cara. El gancho es el medidor de autoconsumo que sube al reordenar tareas. La demo arrastra un lavado al mediodía y ve crecer el ahorro.', 'environment', '6-12h', 6, 12, 'intermediate', '["energy","climate-data"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Invasive Species Early-Warning Wall from Citizen Photos', 'Muro de alerta temprana de especies invasoras con fotos ciudadanas', 'People photograph an unfamiliar plant or bug and the tool checks it against a region''s invasive watch list, raising a flag and a map pin the moment a new incursion appears outside its known range. The hook is catching invasions while they''re still small and stoppable. The demo submits a photo of a known invader and lights up a fresh outbreak on the map.', 'La gente fotografía una planta o insecto desconocido y la herramienta lo coteja con la lista de vigilancia de invasoras de una región, alzando una bandera y un pin en el mapa apenas aparece una nueva incursión fuera de su rango conocido. El gancho es atrapar invasiones mientras aún son pequeñas y frenables. La demo envía la foto de un invasor conocido e ilumina un brote nuevo en el mapa.', 'environment', '12-24h', 12, 24, 'intermediate', '["biodiversity","agriculture"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Methane Plume Reviewer that Triages Satellite Leak Alerts', 'Revisor de plumas de metano que tría alertas satelitales de fugas', 'Open methane satellites flag possible leaks daily, but most need a human gut-check. This tool lays each suspected plume over a map of pipelines and landfills, scores how likely it''s a real source versus noise, and queues the strongest cases for follow-up. The hook is turning a firehose of alerts into a short, ranked worklist. The demo loads a day''s plumes and surfaces the top suspect.', 'Los satélites abiertos de metano marcan posibles fugas a diario, pero la mayoría necesita verificación humana. Esta herramienta superpone cada pluma sospechosa sobre un mapa de gasoductos y rellenos, puntúa cuán probable es que sea una fuente real frente a ruido, y encola los casos más fuertes para seguimiento. El gancho es transformar un torrente de alertas en una breve lista de trabajo ordenada. La demo carga las plumas de un día y muestra al principal sospechoso.', 'environment', '24-48h', 24, 48, 'advanced', '["air-quality","climate-data","energy"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Reusable Container Deposit Tracker for a Campus Cafe Loop', 'Rastreador de depósito de envases reutilizables para un circuito de café de campus', 'A QR-based loop where a campus cafe lends reusable cups and bowls, tracks who has what, and nudges returns before a deposit is forfeited, replacing single-use packaging. The hook is the live return-rate dashboard that proves the loop actually closes instead of leaking containers. The demo borrows a cup, scans it back, and ticks the waste-avoided counter up.', 'Un circuito basado en QR donde un café de campus presta vasos y bowls reutilizables, registra quién tiene qué, y recuerda devolverlos antes de perder el depósito, reemplazando el empaque de un solo uso. El gancho es el panel en vivo de tasa de devolución que prueba que el circuito de verdad se cierra en vez de perder envases. La demo presta un vaso, lo escanea de vuelta y sube el contador de residuos evitados.', 'environment', '6-12h', 6, 12, 'beginner', '["waste"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Climate Adaptation Game where a Town Survives Rising Seas', 'Juego de adaptación climática donde un pueblo sobrevive a la suba del mar', 'A turn-based strategy game where you govern a coastal town over decades, spending a limited budget on seawalls, marsh buffers and managed retreat as storms intensify. The hook is that every defense has a tradeoff, so players feel the brutal math of adaptation instead of reading about it. The demo plays two rounds and shows a flood the player''s choices either held back or didn''t.', 'Un juego de estrategia por turnos donde gobiernas un pueblo costero durante décadas, gastando un presupuesto limitado en murallas, humedales amortiguadores y retirada gestionada mientras las tormentas se intensifican. El gancho es que cada defensa tiene un costo, así los jugadores sienten la matemática brutal de la adaptación en vez de leerla. La demo juega dos rondas y muestra una crecida que las decisiones del jugador contuvieron o no.', 'environment', '24-48h', 24, 48, 'intermediate', '["climate-data","water"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Rooftop Garden Load Checker for Safe Urban Growing', 'Verificador de carga de techo verde para cultivo urbano seguro', 'Before turning a flat roof into a garden, enter the building type, roof area and planned beds, and the tool estimates the added weight when soil is fully soaked and flags whether it likely stays within safe load limits. The hook is catching the soggy-soil worst case that naive planners miss. The demo lays out beds on a roof and turns the load gauge amber as you add planters.', 'Antes de convertir un techo plano en jardín, ingresa el tipo de edificio, el área del techo y los canteros planeados, y la herramienta estima el peso agregado con el suelo totalmente empapado y marca si probablemente se mantiene dentro de límites seguros. El gancho es atrapar el peor caso de suelo mojado que los planificadores ingenuos pasan por alto. La demo distribuye canteros en un techo y pone el medidor de carga en ámbar al sumar maceteros.', 'environment', '3-6h', 3, 6, 'beginner', '["agriculture","biodiversity"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Blind Maze Where One Player Sees and the Other Walks', 'Laberinto a ciegas donde uno ve y el otro camina', 'An asymmetric co-op puzzle: one player sees the full maze on their screen but can''t move, while the other walks blind through a dark first-person view and must follow spoken directions. Traps reset the run, so trust and clear talking are everything. Join over a shared link with no install for a tense, funny two-player demo.', 'Un rompecabezas cooperativo asimétrico: un jugador ve el laberinto completo en su pantalla pero no puede moverse, mientras el otro avanza a ciegas en una vista en primera persona oscura y debe seguir indicaciones habladas. Las trampas reinician la partida, así que la confianza y hablar claro lo son todo. Únanse por un enlace compartido sin instalar nada.', 'games-fun', '6-12h', 6, 12, 'intermediate', '["multiplayer","party-games"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Tarot Roguelite Where Each Card You Draw Rewrites the Run', 'Roguelite de tarot donde cada carta reescribe la partida', 'A roguelite dungeon where your only resource is a tarot deck: drawing The Tower collapses a wall, The Sun heals but blinds enemies, Death swaps your health with a foe''s. Every floor is procedurally laid out so the same draw plays differently each time. The hook is reading risky cards under pressure, with a satisfying loop for an overnight build.', 'Un roguelite de mazmorra donde tu único recurso es una baraja de tarot: sacar La Torre derrumba un muro, El Sol cura pero ciega enemigos, La Muerte intercambia tu vida con la de un rival. Cada piso se genera de forma procedural, así que la misma carta se juega distinto cada vez. El gancho es leer cartas arriesgadas bajo presión, con un bucle satisfactorio para una noche.', 'games-fun', '12-24h', 12, 24, 'intermediate', '["procedural","retro"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Co-op Cooking Game Where the Recipe Is in Another Language', 'Juego de cocina cooperativo con la receta en otro idioma', 'A frantic kitchen game for two: one player holds the recipe written in a language they can''t read, the other knows the language but can''t see the stove. They must translate and shout steps before dishes burn. Orders escalate and the chaos compounds, making the forced cross-talk the whole joke in a quick party-night build.', 'Un juego de cocina frenético para dos: un jugador tiene la receta escrita en un idioma que no entiende, el otro conoce el idioma pero no ve la cocina. Deben traducir y gritar los pasos antes de que los platos se quemen. Los pedidos escalan y el caos se acumula, haciendo de la conversación cruzada forzada el chiste central en una creación rápida para una noche de fiesta.', 'games-fun', '6-12h', 6, 12, 'intermediate', '["multiplayer","party-games"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Whisper-Controlled Stealth Game You Play with Your Voice', 'Juego de sigilo controlado por susurros con tu voz', 'A stealth game where loudness is movement: whisper to tiptoe, speak to walk, and a shout sends your character sprinting but wakes every guard. The mic meter is the controller, so playing it in a quiet room is its own comedy. A single sharp mechanic that demos beautifully in a short sprint.', 'Un juego de sigilo donde el volumen es movimiento: susurra para ir de puntillas, habla para caminar y un grito hace correr a tu personaje pero despierta a todos los guardias. El medidor del micrófono es el control, así que jugarlo en una sala silenciosa es comedia en sí mismo. Un mecanismo único y filoso que se demuestra de maravilla en un sprint corto.', 'games-fun', '3-6h', 3, 6, 'intermediate', '["music-game","physics"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('AI Detective Game Where Suspects Lie and You Cross-Examine', 'Juego de detective con IA donde los sospechosos mienten', 'A murder-mystery where every suspect is an AI character with a hidden alibi, a secret, and a tell. You interrogate them freely by typing questions, and catching contradictions between their stories unlocks the accusation. Each playthrough seeds a new culprit and motive, so the deductions never repeat across a longer build.', 'Un misterio de asesinato donde cada sospechoso es un personaje con IA con una coartada oculta, un secreto y un gesto delator. Los interrogas libremente escribiendo preguntas, y atrapar contradicciones entre sus relatos desbloquea la acusación. Cada partida siembra un nuevo culpable y motivo, así que las deducciones nunca se repiten en una creación más larga.', 'games-fun', '24-48h', 24, 48, 'advanced', '["ai-npc","procedural"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Rhythm Boxing Where Punches Must Land on the Beat', 'Boxeo rítmico donde los golpes caen en el ritmo', 'A webcam boxing game scored on timing: jabs and hooks only count when thrown on the beat of the track, and stringing combos in sync charges a flashy finisher. It reads your arm motion through the camera, turning any song into a workout fight. A tight, sweaty single-screen demo that gets a room cheering.', 'Un juego de boxeo por webcam puntuado por el tiempo: los jabs y ganchos solo cuentan cuando se lanzan al ritmo de la pista, y encadenar combos sincronizados carga un remate vistoso. Lee el movimiento de tus brazos por la cámara, convirtiendo cualquier canción en una pelea de ejercicio. Una demo de una pantalla, intensa y sudorosa, que hace gritar a la sala.', 'games-fun', '6-12h', 6, 12, 'intermediate', '["music-game","physics"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Procedural City Builder Where Citizens Riot If You Ignore Them', 'Constructor de ciudad procedural donde la gente se rebela', 'A tiny city builder where each procedurally placed citizen has needs and a temper: neglect water or joy and they organize, protest, and eventually flip a district into chaos. You balance growth against keeping crowds happy, watching unrest spread block by block. A meaty systems toy with real emergent drama for a weekend build.', 'Un pequeño constructor de ciudades donde cada ciudadano colocado de forma procedural tiene necesidades y carácter: descuida el agua o la alegría y se organizan, protestan y al final vuelcan un distrito al caos. Equilibras el crecimiento con mantener contenta a la multitud, viendo el descontento expandirse cuadra por cuadra. Un juguete de sistemas con drama emergente real para un fin de semana.', 'games-fun', '24-48h', 24, 48, 'advanced', '["procedural","ai-npc"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Air-Drum Battle Where Two Phones Become Your Drumsticks', 'Batalla de batería al aire con dos teléfonos de baquetas', 'A rhythm game played by swinging two phones like drumsticks: their motion sensors detect each hit and direction, mapping the air in front of you to a kit. Notes scroll down and you smack invisible drums in time. Calibration takes a minute and then it''s pure flailing fun, perfect for a short, physical demo.', 'Un juego de ritmo que se juega agitando dos teléfonos como baquetas: sus sensores de movimiento detectan cada golpe y dirección, mapeando el aire frente a ti como una batería. Las notas bajan y golpeas tambores invisibles a tiempo. La calibración toma un minuto y luego es pura diversión a manotazos, ideal para una demo corta y física.', 'games-fun', '3-6h', 3, 6, 'intermediate', '["music-game","multiplayer"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Retro Text Adventure That Renders Each Room as Pixel Art', 'Aventura de texto retro que dibuja cada sala en pixel art', 'A throwback parser adventure with a twist: as you type commands, it generates a chunky pixel-art scene of the room you''re in, so reading and seeing happen together. Items you pick up vanish from the picture; doors you open appear. A cozy, nostalgic single-player build that pairs old-school typing with instant visuals.', 'Una aventura de parser a la vieja usanza con un giro: mientras escribes comandos, genera una escena de pixel art tosca de la sala en la que estás, así que leer y ver ocurren juntos. Los objetos que tomas desaparecen de la imagen; las puertas que abres aparecen. Una creación individual acogedora y nostálgica que une la escritura clásica con visuales instantáneos.', 'games-fun', '12-24h', 12, 24, 'intermediate', '["retro","procedural"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Tug-of-War Quiz Where Right Answers Drag a Rope on Screen', 'Quiz de cinchada donde acertar arrastra una soga en pantalla', 'A two-team party quiz visualized as a rope: every correct answer yanks the marker toward your side, every wrong one gives ground. Teams buzz in from their phones and the on-screen rope lurches dramatically with each round. A loud, simple crowd game whose whole charm is the visible momentum swing in a quick build.', 'Un quiz de fiesta entre dos equipos visualizado como una soga: cada respuesta correcta tira del marcador hacia tu lado, cada error cede terreno. Los equipos responden desde sus teléfonos y la soga en pantalla da tirones dramáticos en cada ronda. Un juego de multitud ruidoso y simple cuyo encanto es el cambio de impulso visible en una creación rápida.', 'games-fun', '3-6h', 3, 6, 'beginner', '["party-games","multiplayer"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Gravity-Flip Runner Where the Floor and Ceiling Keep Swapping', 'Corredor de gravedad invertida donde piso y techo se cambian', 'A one-button endless runner built on physics: tap to flip gravity and your character falls up, dodging spikes that come from both directions. Procedurally generated stretches ramp the speed and force split-second flips. A clean, addictive arcade hook that''s beginner-friendly to build in a half-day yet endlessly replayable.', 'Un corredor infinito de un botón basado en física: toca para invertir la gravedad y tu personaje cae hacia arriba, esquivando púas que vienen de ambos lados. Tramos generados de forma procedural aumentan la velocidad y obligan a inversiones en una fracción de segundo. Un gancho arcade limpio y adictivo, fácil de construir en media jornada pero infinitamente rejugable.', 'games-fun', '3-6h', 3, 6, 'beginner', '["physics","procedural"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('AR Tabletop Battler That Turns Your Desk Into a Battlefield', 'Batallador AR que convierte tu escritorio en un campo de batalla', 'Point your phone at any desk and a miniature army appears anchored to the surface, with cover and high ground mapped from real objects like mugs and books. You move troops by tapping and they take cover behind whatever is actually on your table. A striking AR demo where the room itself becomes the level.', 'Apunta tu teléfono a cualquier escritorio y aparece un ejército en miniatura anclado a la superficie, con cobertura y terreno alto mapeados desde objetos reales como tazas y libros. Mueves tropas tocando y se cubren detrás de lo que de verdad está en tu mesa. Una demo AR impactante donde la habitación misma se vuelve el nivel.', 'games-fun', '24-48h', 24, 48, 'advanced', '["ar-vr","physics"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Party Game Where Everyone Secretly Mimics a Hidden Emotion', 'Juego de fiesta donde todos imitan en secreto una emoción', 'Each phone gets a secret emotion to act out while the group films a short shared scene together; afterward everyone guesses who had which feeling. It scores hilarity by how badly people overact and how wrong the guesses are. A camera-driven social game that thrives on a crowded room in a quick build.', 'Cada teléfono recibe una emoción secreta para actuar mientras el grupo filma juntos una escena corta compartida; después todos adivinan quién tenía cuál sentimiento. Puntúa la comicidad según lo mal que la gente sobreactúa y lo equivocados que están los aciertos. Un juego social guiado por cámara que florece en una sala llena, en una creación rápida.', 'games-fun', '6-12h', 6, 12, 'intermediate', '["party-games","multiplayer"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Procedural Planet Survival Where Each World Has New Physics', 'Supervivencia en planeta procedural con física distinta', 'A survival sandbox where every generated planet rolls its own physics: low gravity makes jumps float, dense atmospheres slow your fall, magnetic worlds yank metal tools away. You adapt your strategy to laws you discover by dying. The deep hook is mastering rules that change each world, ideal for a longer, ambitious build.', 'Un sandbox de supervivencia donde cada planeta generado sortea su propia física: la baja gravedad hace flotar los saltos, las atmósferas densas frenan tu caída, los mundos magnéticos arrancan las herramientas de metal. Adaptas tu estrategia a leyes que descubres muriendo. El gancho profundo es dominar reglas que cambian en cada mundo, ideal para una creación larga y ambiciosa.', 'games-fun', '48h+', 48, 72, 'advanced', '["procedural","physics"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('VR Cooking School Where an AI Chef Critiques Your Knife Work', 'Escuela de cocina VR donde un chef IA critica tu corte', 'A VR kitchen where you chop, flip, and plate with hand tracking while an AI chef character watches and reacts in real time, praising clean cuts and scolding sloppy ones. Recipes branch based on how well you perform earlier steps. A polished, replayable experience with personality that justifies a full multi-day build.', 'Una cocina VR donde cortas, volteas y emplatas con seguimiento de manos mientras un chef con IA observa y reacciona en tiempo real, elogiando cortes limpios y regañando los descuidados. Las recetas se ramifican según lo bien que hiciste los pasos anteriores. Una experiencia pulida y rejugable con personalidad que justifica una creación de varios días.', 'games-fun', '48h+', 48, 72, 'advanced', '["ar-vr","ai-npc"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Color-Matching Brawler Where Hits Only Work on Same-Hue Foes', 'Peleador de colores donde solo dañas enemigos del mismo tono', 'A fast arena brawler with a puzzle layer: you can only damage enemies whose color matches yours, and you swap your hue on a cooldown. Crowds force quick re-coloring as waves mix shades. The single mechanic creates a constant juggling tension that''s sharp to demo and quick to prototype in a few hours.', 'Un peleador de arena veloz con capa de rompecabezas: solo puedes dañar enemigos cuyo color coincida con el tuyo, y cambias tu tono con un tiempo de recarga. Las multitudes obligan a recolorear rápido cuando las oleadas mezclan matices. El mecanismo único crea una tensión de malabares constante, filosa para demostrar y rápida de prototipar en pocas horas.', 'games-fun', '3-6h', 3, 6, 'intermediate', '["physics","retro"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Co-op Spaceship Where Each Player Mans One Broken Station', 'Nave cooperativa donde cada jugador opera una estación rota', 'A frantic bridge simulator for a small crew: one steers, one fires, one patches hull breaches, and consoles randomly short out so roles must be covered on the fly. Asteroid runs are procedurally generated to keep crises fresh. The hook is the shouted coordination of a crew barely holding it together, great for an overnight build.', 'Un simulador de puente frenético para una tripulación pequeña: uno pilota, uno dispara, uno repara brechas del casco, y las consolas se cortan al azar, así que los roles deben cubrirse sobre la marcha. Los tramos de asteroides se generan de forma procedural para mantener frescas las crisis. El gancho es la coordinación a gritos de una tripulación que apenas aguanta, ideal para una noche.', 'games-fun', '12-24h', 12, 24, 'intermediate', '["multiplayer","procedural"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Shadow Puppet Theater Where Your Hands Cast the Characters', 'Teatro de sombras donde tus manos crean los personajes', 'A webcam game that turns your hand shadows into puppet characters on a lit stage: make a bird, a dog, a snake, and the game recognizes the shape and animates it into a tiny story it narrates around your gestures. A charming, gesture-driven creative toy that demos instantly and feels magical in a short sprint.', 'Un juego por webcam que convierte las sombras de tus manos en personajes de títeres sobre un escenario iluminado: haz un pájaro, un perro, una serpiente, y el juego reconoce la forma y la anima en una pequeña historia que narra en torno a tus gestos. Un juguete creativo encantador guiado por gestos que se demuestra al instante y se siente mágico en un sprint corto.', 'games-fun', '6-12h', 6, 12, 'intermediate', '["ai-npc","party-games"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Deck-Builder Where Cards Are Generated From Words You Type', 'Constructor de mazos con cartas creadas de palabras que escribes', 'A card battler where you forge cards by typing any noun: type ''volcano'' and get a high-damage fire card, type ''umbrella'' and get a defensive shield. An AI assigns stats and art, so each player''s deck is wildly personal. The hook is the joke-and-strategy of naming your way to a winning hand in a longer build.', 'Un juego de cartas donde forjas cartas escribiendo cualquier sustantivo: escribe ''volcán'' y obtén una carta de fuego de alto daño, escribe ''paraguas'' y obtén un escudo defensivo. Una IA asigna estadísticas y arte, así que el mazo de cada jugador es muy personal. El gancho es el chiste y la estrategia de nombrar tu camino a una mano ganadora en una creación larga.', 'games-fun', '24-48h', 24, 48, 'advanced', '["ai-npc","procedural"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Beat-Synced Platformer Where Platforms Appear on the Drop', 'Plataformas al ritmo donde aparecen en el bajón musical', 'A platformer fused to music: platforms, hazards, and gaps pulse in and out exactly on the song''s beat, so you must jump in rhythm or fall through where a platform just vanished. Drop in any track and the level rebuilds to its tempo. A tight audiovisual hook that''s satisfying to nail in a half-day prototype.', 'Un plataformas fusionado con la música: las plataformas, los peligros y los huecos aparecen y desaparecen justo al ritmo de la canción, así que debes saltar a tempo o caer por donde una plataforma acaba de esfumarse. Suelta cualquier pista y el nivel se reconstruye a su tempo. Un gancho audiovisual ajustado, satisfactorio de clavar en un prototipo de media jornada.', 'games-fun', '3-6h', 3, 6, 'intermediate', '["music-game","physics"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Telephone Dungeon Where Each Friend Adds One Room Live', 'Mazmorra teléfono donde cada amigo agrega una sala en vivo', 'A collaborative dungeon-drawing party game: players take turns adding one room, monster, or trap to a shared map without seeing the whole thing, then everyone watches a hero auto-walk through the absurd result. The comedy is the mismatched contributions colliding. A quick, social build that turns group chaos into a playable crawl.', 'Un juego de fiesta de dibujo colaborativo de mazmorras: los jugadores se turnan para agregar una sala, un monstruo o una trampa a un mapa compartido sin ver el conjunto, y luego todos miran a un héroe recorrer en automático el resultado absurdo. La comedia es la colisión de aportes desparejos. Una creación rápida y social que vuelve el caos grupal en un recorrido jugable.', 'games-fun', '6-12h', 6, 12, 'intermediate', '["party-games","multiplayer"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Retro Racer Where the Track Is Drawn by the Previous Lap', 'Carrera retro donde la pista la dibuja la vuelta anterior', 'A top-down arcade racer with a twist: there''s no fixed track, your driving line on lap one becomes the wall everyone races inside on lap two. Sloppy first laps make brutal, twisty courses for later ones. A clever single-mechanic build with chunky retro visuals that''s fun solo and even better in a hotseat duel.', 'Una carrera arcade cenital con un giro: no hay pista fija, tu trazada en la primera vuelta se vuelve el muro dentro del cual todos corren en la segunda. Las primeras vueltas descuidadas hacen circuitos brutales y retorcidos para las siguientes. Una creación ingeniosa de un solo mecanismo con visuales retro toscos, divertida en solitario y aún mejor en un duelo por turnos.', 'games-fun', '6-12h', 6, 12, 'intermediate', '["retro","physics"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Negotiation Game Where AI Merchants Remember Your Reputation', 'Juego de regateo donde mercaderes IA recuerdan tu fama', 'A trading game built on AI merchants who haggle in natural language and gossip: cheat one and word spreads, raising prices across the market. You bluff, build trust, and exploit rivalries to corner deals. The hook is a living economy that reacts to your reputation, rich enough for a multi-day build with real replay value.', 'Un juego de comercio basado en mercaderes con IA que regatean en lenguaje natural y chismean: engaña a uno y corre la voz, subiendo precios por todo el mercado. Faroleas, generas confianza y explotas rivalidades para cerrar tratos. El gancho es una economía viva que reacciona a tu reputación, lo bastante rica para una creación de varios días con verdadero valor de rejugada.', 'games-fun', '48h+', 48, 72, 'advanced', '["ai-npc","procedural"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Pong Reinvented Where the Paddle Is Your Phone''s Tilt', 'Pong reinventado donde la paleta es la inclinación del móvil', 'A two-player Pong revival where each phone is a paddle controlled by tilting it, and both connect to one shared big screen over a link. The ball speeds up with every volley and the tilting gets frantic. A nostalgic, beginner-friendly build that nails instant fun with zero setup beyond scanning a code.', 'Un renacer de Pong para dos donde cada teléfono es una paleta controlada inclinándolo, y ambos se conectan a una pantalla grande compartida por un enlace. La pelota se acelera con cada volea y la inclinación se vuelve frenética. Una creación nostálgica y apta para principiantes que logra diversión instantánea sin más preparación que escanear un código.', 'games-fun', '1-3h', 1, 3, 'beginner', '["retro","multiplayer"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Idle Volcano You Calm by Solving Tiny Physics Puzzles', 'Volcán inactivo que calmas resolviendo mini puzzles de física', 'An idle game with a physics core: a volcano slowly builds pressure, and you vent it by solving quick marble-and-lever puzzles that redirect lava into safe channels. Leave it alone and it erupts, so you check back to defuse it. A satisfying low-pressure loop with a clever puzzle hook, buildable in a single short session.', 'Un juego idle con núcleo de física: un volcán acumula presión lentamente, y la liberas resolviendo puzzles rápidos de canicas y palancas que redirigen la lava a canales seguros. Déjalo solo y entra en erupción, así que vuelves a revisarlo para desactivarlo. Un bucle satisfactorio de baja presión con un gancho de puzzle ingenioso, construible en una sola sesión corta.', 'games-fun', '3-6h', 3, 6, 'beginner', '["physics","procedural"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Improv Stage Where an AI Audience Heckles Your Performance', 'Escenario de improvisación con público IA que te abuchea', 'A solo comedy game: you type or speak improv responses to absurd scene prompts, and an AI audience reacts live with laughs, groans, or heckles that shape your score. Land a good bit and the room roars; bomb and they walk out. The hook is performing for a crowd that genuinely judges you, fun in a focused build.', 'Un juego de comedia en solitario: escribes o dices respuestas de improvisación a indicaciones de escenas absurdas, y un público con IA reacciona en vivo con risas, quejas o abucheos que moldean tu puntaje. Clava un buen chiste y la sala ruge; fracasa y se van. El gancho es actuar para un público que de verdad te juzga, divertido en una creación enfocada.', 'games-fun', '6-12h', 6, 12, 'intermediate', '["ai-npc","party-games"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Constellation Puzzle Where You Connect Stars to Match a Myth', 'Puzzle de constelaciones donde unes estrellas según un mito', 'A calm puzzle game on a procedurally scattered night sky: you connect stars to recreate a creature, and as you trace it the game tells a short myth tied to the shape. Each board generates a new sky and legend. A serene, beginner-friendly build with a gentle hook and a quietly beautiful demo moment.', 'Un juego de puzzle tranquilo sobre un cielo nocturno disperso de forma procedural: conectas estrellas para recrear una criatura, y mientras la trazas el juego cuenta un mito breve ligado a la forma. Cada tablero genera un cielo y una leyenda nuevos. Una creación serena y apta para principiantes con un gancho suave y un momento de demo silenciosamente bello.', 'games-fun', '3-6h', 3, 6, 'beginner', '["procedural","ai-npc"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Hide-and-Seek Where Hiders Are Props Scattered in the Room', 'Escondidas donde quienes se ocultan son objetos de la sala', 'A prop-hunt party game over a shared link: hiders morph into everyday objects on a 3D map and freeze among the real furniture, while a seeker hunts the one mug that''s secretly a player. Tiny tells like a wiggle give hiders away. A tense, giggly multiplayer build whose whole joy is the held-breath bluff.', 'Un juego de fiesta de caza de objetos por un enlace compartido: quienes se ocultan se transforman en objetos cotidianos en un mapa 3D y se congelan entre el mobiliario real, mientras un buscador caza la única taza que en secreto es un jugador. Pequeños gestos como un meneo los delatan. Una creación multijugador tensa y risueña cuya alegría es el farol con la respiración contenida.', 'games-fun', '12-24h', 12, 24, 'intermediate', '["multiplayer","party-games"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('VR Archery Range That Spawns Targets From a Story It Tells', 'Tiro con arco VR que genera blancos según la historia que narra', 'A VR archery experience where an AI narrator weaves a tale and spawns targets to match it: dragons swoop, lanterns drift, bandits charge, all conjured by the unfolding story so no two sessions aim the same. Hand-tracked draw-and-loose makes it physical. A polished, immersive build with strong demo wow over multiple days.', 'Una experiencia de tiro con arco VR donde un narrador con IA teje un relato y genera blancos que lo acompañan: dragones que se lanzan, faroles que flotan, bandidos que cargan, todo conjurado por la historia que se despliega, así que ninguna sesión apunta igual. El tensar y soltar con seguimiento de manos lo vuelve físico. Una creación pulida e inmersiva con gran impacto en demo a lo largo de varios días.', 'games-fun', '48h+', 48, 72, 'advanced', '["ar-vr","ai-npc"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Word Ladder Race Where Each Step Must Rhyme With the Last', 'Carrera de escalera de palabras donde cada paso debe rimar', 'A fast word game for a group: a starting word appears and players race to type a chain where every new word rhymes with the previous one, scoring on speed and cleverness. Repeats and non-rhymes break your streak. A snappy, low-tech party build that gets a room shouting answers, ideal for a tiny sprint.', 'Un juego de palabras veloz para un grupo: aparece una palabra inicial y los jugadores compiten por escribir una cadena donde cada palabra nueva rima con la anterior, puntuando por velocidad e ingenio. Las repeticiones y las no-rimas cortan tu racha. Una creación de fiesta ágil y de baja tecnología que hace gritar respuestas a la sala, ideal para un sprint mínimo.', 'games-fun', '1-3h', 1, 3, 'beginner', '["party-games","multiplayer"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Bridge Builder Where Your Structure Carries Live Foot Traffic', 'Constructor de puentes que soporta tráfico peatonal en vivo', 'A physics building puzzle: you assemble a bridge from beams and cables on a budget, then a parade of tiny pedestrians and carts walks across while joints flex and groan under real load. Watching it sag, hold, or spectacularly collapse is the payoff. A satisfying, demoable engineering toy buildable in a focused day.', 'Un puzzle de construcción con física: ensamblas un puente con vigas y cables dentro de un presupuesto, y luego un desfile de peatones y carros diminutos lo cruza mientras las juntas se flexionan y crujen bajo carga real. Verlo ceder, aguantar o colapsar espectacularmente es la recompensa. Un juguete de ingeniería satisfactorio y demostrable, construible en una jornada enfocada.', 'games-fun', '12-24h', 12, 24, 'intermediate', '["physics","procedural"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Karaoke Duet Where Two Singers Must Harmonize to Score', 'Karaoke a dúo donde dos cantantes deben armonizar para puntuar', 'A two-mic karaoke game that rewards harmony, not just pitch: both singers get different vocal lines and the score only climbs when their notes lock into a real chord together. Solo wandering tanks the bar. The hook is being forced to actually listen to each other, a joyful, loud build for a short jam.', 'Un juego de karaoke a dos micrófonos que premia la armonía, no solo la afinación: ambos cantantes reciben líneas vocales distintas y el puntaje solo sube cuando sus notas encajan en un acorde real juntos. Andar solo por libre hunde la barra. El gancho es verse obligado a escucharse de verdad, una creación alegre y ruidosa para una jam corta.', 'games-fun', '6-12h', 6, 12, 'intermediate', '["music-game","multiplayer"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Minimalist Falling-Block Game Where Lines Clear to a Beat', 'Juego minimalista de bloques donde las líneas se borran al ritmo', 'A retro falling-block puzzle fused with rhythm: cleared lines only resolve on the downbeat, so timing your placements to the music multiplies your score and triggers cascading visual pulses. Drop in any track to set the tempo. A clean, single-screen build that marries an old classic with a fresh rhythmic twist in a few hours.', 'Un puzzle retro de bloques que caen fusionado con ritmo: las líneas completadas solo se resuelven en el tiempo fuerte, así que sincronizar tus piezas con la música multiplica tu puntaje y dispara pulsos visuales en cascada. Suelta cualquier pista para fijar el tempo. Una creación limpia de una pantalla que casa un clásico viejo con un giro rítmico fresco en pocas horas.', 'games-fun', '3-6h', 3, 6, 'intermediate', '["retro","music-game"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Survival Island Where an AI Castaway Argues About Your Plans', 'Isla de supervivencia donde un náufrago IA discute tus planes', 'A survival game with a companion twist: you''re stranded with an AI castaway who has opinions, fears, and a survival theory of their own, and they''ll help, sulk, or sabotage based on how you treat them. Resources and weather are procedurally seeded each run. The hook is managing a moody partner, deep enough for a long build.', 'Un juego de supervivencia con giro de compañero: estás varado con un náufrago de IA que tiene opiniones, miedos y su propia teoría de supervivencia, y te ayudará, se enfurruñará o saboteará según cómo lo trates. Los recursos y el clima se siembran de forma procedural en cada partida. El gancho es manejar a un socio temperamental, profundo para una creación larga.', 'games-fun', '48h+', 48, 72, 'advanced', '["ai-npc","procedural"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Speech-Pacing Coach for People Who Stutter', 'Entrenador de ritmo del habla para personas que tartamudean', 'A practice tool that listens while you read aloud and gently paces your speech with a visual metronome that slows down when it detects blocks or rushed syllables. It tracks fluent stretches over sessions so you can see progress, not just disfluencies. The demo has a judge read a passage and watch the pacing guide adapt in real time to their rhythm.', 'Una herramienta de práctica que escucha mientras lees en voz alta y marca el ritmo de tu habla con un metrónomo visual que se desacelera cuando detecta bloqueos o sílabas apresuradas. Registra los tramos fluidos a lo largo de las sesiones para que veas el progreso, no solo las disfluencias. La demo hace que un juez lea un pasaje y vea la guía de ritmo adaptarse en tiempo real.', 'health-medtech', '6-12h', 6, 12, 'intermediate', '["accessibility","diagnostics"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Inhaler Technique Checker from a Phone Video', 'Verificador de técnica de inhalador desde un video del teléfono', 'Asthma patients often use inhalers wrong, wasting the dose. Record a short clip of yourself using one and the tool checks the steps — shake, exhale, seal, slow breath, hold — flagging which you skipped or rushed. It returns a simple scorecard with the one fix that matters most. A focused, demoable build that turns a common error into a coachable moment.', 'Los pacientes con asma suelen usar mal los inhaladores, desperdiciando la dosis. Graba un clip corto usándolo y la herramienta revisa los pasos — agitar, exhalar, sellar, inhalar despacio, retener — señalando cuáles omitiste o apuraste. Devuelve una tarjeta de puntaje simple con el único ajuste que más importa. Un proyecto enfocado y demostrable que convierte un error común en un momento de aprendizaje.', 'health-medtech', '6-12h', 6, 12, 'intermediate', '["diagnostics","accessibility"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Color-Blind-Safe Lab Chart Recolorizer for Clinics', 'Recoloreador de gráficos de laboratorio seguro para daltónicos', 'Many clinical charts and heatmaps use red-green palettes that color-blind clinicians misread. Upload a chart image and the tool detects the risky palette and repaints it with a color-blind-safe scheme plus patterns, preserving the legend. A sharp single-screen build that makes existing medical visuals readable for everyone in one click.', 'Muchos gráficos clínicos y mapas de calor usan paletas rojo-verde que los clínicos daltónicos malinterpretan. Sube una imagen del gráfico y la herramienta detecta la paleta riesgosa y la repinta con un esquema seguro para daltónicos más patrones, conservando la leyenda. Un proyecto nítido de una sola pantalla que hace legibles los visuales médicos existentes con un clic.', 'health-medtech', '3-6h', 3, 6, 'beginner', '["accessibility","med-data"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Tinnitus Sound-Matching Tool for Audiology Intake', 'Herramienta de coincidencia de sonido para tinnitus en audiología', 'Describing the pitch and texture of your tinnitus is hard. This tool plays candidate tones and noises and lets you steer sliders until the synthesized sound matches what you hear, then exports the profile for an audiologist. The demo has someone dial in a ringing tone and watch the matched frequency chart appear, turning a vague complaint into structured data.', 'Describir el tono y la textura de tu tinnitus es difícil. Esta herramienta reproduce tonos y ruidos candidatos y te deja ajustar deslizadores hasta que el sonido sintetizado coincida con lo que oyes, y luego exporta el perfil para un audiólogo. La demo hace que alguien sintonice un zumbido y vea aparecer el gráfico de frecuencia coincidente, convirtiendo una queja vaga en datos estructurados.', 'health-medtech', '6-12h', 6, 12, 'intermediate', '["diagnostics","accessibility"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Fall-Risk Quick Test from a 30-Second Chair Stand', 'Test rápido de riesgo de caída con sentarse y pararse 30s', 'Older adults'' fall risk can be estimated from how many times they stand from a chair in 30 seconds. Point a phone at the person and the tool counts reps automatically, checks symmetry, and compares against age norms to flag elevated risk. The demo runs a live count on camera and shows a clear traffic-light result that a caregiver could act on.', 'El riesgo de caída en adultos mayores puede estimarse por cuántas veces se paran de una silla en 30 segundos. Apunta el teléfono a la persona y la herramienta cuenta las repeticiones automáticamente, revisa la simetría y compara con normas por edad para señalar riesgo elevado. La demo hace un conteo en vivo por cámara y muestra un resultado tipo semáforo sobre el cual un cuidador podría actuar.', 'health-medtech', '6-12h', 6, 12, 'intermediate', '["diagnostics","fitness","wearable-health"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Discharge Instructions Translator into a Day-by-Day Plan', 'Traductor de instrucciones de alta a un plan día por día', 'Hospital discharge papers cram meds, wound care, and follow-ups into dense text. Paste them and the tool rebuilds everything as a clear day-by-day calendar with checkboxes — when to take each pill, when to change a dressing, which warning signs mean call now. The demo takes a real discharge sheet and turns it into an at-a-glance recovery schedule.', 'Los papeles de alta hospitalaria amontonan medicamentos, cuidado de heridas y seguimientos en texto denso. Pégalos y la herramienta lo reconstruye como un calendario claro día por día con casillas — cuándo tomar cada pastilla, cuándo cambiar un vendaje, qué señales de alarma significan llamar ya. La demo toma una hoja de alta real y la convierte en un cronograma de recuperación de un vistazo.', 'health-medtech', '6-12h', 6, 12, 'intermediate', '["accessibility","telemedicine"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Allergy-Aware Menu Scanner for Restaurant Photos', 'Escáner de menú con alertas de alergia desde fotos', 'Eating out with a serious food allergy is stressful. Snap a photo of any menu, set your allergens, and the tool flags every dish that likely contains or hides them — including sneaky sources like soy in sauces — with a confidence note and a question to ask the server. A tight build whose demo makes a risky menu instantly navigable.', 'Comer afuera con una alergia alimentaria seria es estresante. Saca una foto de cualquier menú, define tus alérgenos y la herramienta marca cada plato que probablemente los contiene u oculta — incluso fuentes escondidas como soja en salsas — con una nota de confianza y una pregunta para hacerle al mesero. Un proyecto compacto cuya demo hace un menú riesgoso navegable al instante.', 'health-medtech', '3-6h', 3, 6, 'intermediate', '["nutrition","accessibility"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Pediatric Dose Calculator that Reads a Prescription', 'Calculadora de dosis pediátrica que lee una receta', 'Liquid medicine dosing for kids is a frequent source of dangerous errors. Enter the child''s weight and snap the bottle label; the tool computes the exact mL per dose, the syringe marking to hit, and the safe daily maximum, warning if the prescription looks off. A demoable safety tool that turns scary mental math into a clear, checkable number for caregivers.', 'Dosificar medicina líquida para niños es una fuente frecuente de errores peligrosos. Ingresa el peso del niño y fotografía la etiqueta del frasco; la herramienta calcula los mL exactos por dosis, la marca de la jeringa a alcanzar y el máximo diario seguro, avisando si la receta parece incorrecta. Una herramienta de seguridad demostrable que convierte un cálculo mental aterrador en un número claro y verificable.', 'health-medtech', '6-12h', 6, 12, 'intermediate', '["diagnostics","accessibility"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Voice-Tremor Parkinsons Screener from a Sustained Vowel', 'Screener de Parkinson por temblor de voz en una vocal sostenida', 'Hold an ''ahh'' for a few seconds and the tool analyzes jitter, shimmer, and pitch instability — acoustic markers linked to early Parkinsonian voice changes — returning a screening score and a clear caveat that it is not a diagnosis. It tracks the score across days. The demo records a sustained vowel live and plots the tremor signature instantly.', 'Sostén un ''ahh'' por unos segundos y la herramienta analiza jitter, shimmer e inestabilidad de tono — marcadores acústicos ligados a cambios tempranos de voz parkinsoniana — devolviendo un puntaje de screening con la advertencia clara de que no es un diagnóstico. Registra el puntaje a lo largo de los días. La demo graba una vocal sostenida en vivo y grafica la firma del temblor al instante.', 'health-medtech', '12-24h', 12, 24, 'advanced', '["diagnostics","wearable-health"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Shift-Worker Sleep Planner that Fights Jet Lag at Home', 'Planificador de sueño para turnos que combate el jet lag en casa', 'Nurses and other shift workers wreck their circadian rhythm rotating between days and nights. Enter your roster and the tool builds a personalized light, caffeine, and nap schedule to shift your body clock with the least misery before each rotation. The demo loads a brutal real shift pattern and produces an hour-by-hour adaptation plan for the week.', 'El personal de enfermería y otros trabajadores por turnos destrozan su ritmo circadiano rotando entre días y noches. Ingresa tu cuadrante y la herramienta arma un plan personalizado de luz, cafeína y siestas para ajustar tu reloj biológico con la menor incomodidad antes de cada rotación. La demo carga un patrón de turnos real y brutal y produce un plan de adaptación hora por hora para la semana.', 'health-medtech', '6-12h', 6, 12, 'intermediate', '["wearable-health","mental-health"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Range-of-Motion Tracker for Frozen Shoulder Recovery', 'Medidor de rango de movimiento para recuperación de hombro congelado', 'Recovering shoulder mobility is slow and hard to measure at home. Stand in front of the camera, raise your arm, and the tool measures the exact angle you reach, logs it daily, and shows the recovery curve climbing over weeks. It flags when you plateau so you know to escalate to your physio. A motivating, demoable progress tool grounded in a single clean measurement.', 'Recuperar la movilidad del hombro es lento y difícil de medir en casa. Párate frente a la cámara, levanta el brazo y la herramienta mide el ángulo exacto que alcanzas, lo registra a diario y muestra la curva de recuperación subiendo a lo largo de las semanas. Avisa cuando te estancas para que sepas consultar a tu fisio. Una herramienta de progreso motivadora y demostrable basada en una sola medición limpia.', 'health-medtech', '6-12h', 6, 12, 'intermediate', '["fitness","diagnostics","accessibility"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Anxiety Exposure Ladder Builder with Gradual Steps', 'Generador de escalera de exposición para la ansiedad por pasos', 'Exposure therapy works by facing fears in small steps, but building the ladder is the hard part. Describe what you avoid and the tool drafts a personalized ladder from easiest to hardest, with a check-in after each rung to record anxiety before and after. The demo takes a phobia like public speaking and lays out a ten-rung plan you could actually start tonight.', 'La terapia de exposición funciona enfrentando miedos en pasos pequeños, pero armar la escalera es lo difícil. Describe lo que evitas y la herramienta redacta una escalera personalizada de lo más fácil a lo más difícil, con un registro tras cada escalón para anotar la ansiedad antes y después. La demo toma una fobia como hablar en público y despliega un plan de diez escalones que podrías empezar esta noche.', 'health-medtech', '3-6h', 3, 6, 'beginner', '["mental-health"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Caregiver Burnout Radar from Daily Voice Check-Ins', 'Radar de agotamiento del cuidador con check-ins de voz diarios', 'Family caregivers burn out silently. Each day they leave a short voice note about how things went; the tool tracks tone, sleep mentions, and stress language over time and surfaces a gentle alert when the trend points toward burnout, suggesting concrete respite options. The demo plays a week of notes and shows the burnout curve and the nudge it triggers.', 'Los cuidadores familiares se agotan en silencio. Cada día dejan una nota de voz corta sobre cómo fue todo; la herramienta sigue el tono, las menciones de sueño y el lenguaje de estrés con el tiempo y muestra una alerta suave cuando la tendencia apunta al agotamiento, sugiriendo opciones concretas de respiro. La demo reproduce una semana de notas y muestra la curva de agotamiento y el aviso que dispara.', 'health-medtech', '12-24h', 12, 24, 'intermediate', '["mental-health","wearable-health"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Blood-Pressure Log Builder from Monitor Photos', 'Generador de registro de presión arterial desde fotos del monitor', 'Home blood-pressure tracking falls apart because logging readings by hand is tedious. Snap a photo of your monitor''s screen and the tool reads the systolic, diastolic, and pulse numbers, timestamps them, and builds a clean trend chart your doctor can scan in seconds. It flags readings in the danger zone. A tight build that removes all friction from a tedious routine.', 'El control de la presión en casa fracasa porque anotar las lecturas a mano es tedioso. Saca una foto de la pantalla de tu monitor y la herramienta lee los valores sistólico, diastólico y de pulso, les pone fecha y arma un gráfico de tendencia limpio que tu médico revisa en segundos. Marca las lecturas en zona de peligro. Un proyecto compacto que elimina toda la fricción de una rutina tediosa.', 'health-medtech', '3-6h', 3, 6, 'intermediate', '["wearable-health","med-data","diagnostics"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Hearing Screening Game for Kids with Tone Detection', 'Juego de screening auditivo para niños con detección de tonos', 'Catching hearing loss early in kids matters, but clinical tests intimidate them. This turns a calibrated pure-tone screen into a game where the child taps a character whenever they hear a faint beep across frequencies, quietly mapping their threshold curve. It exports a clean audiogram for a clinician. The demo plays the game and reveals the hidden hearing map behind the fun.', 'Detectar la pérdida auditiva temprano en niños importa, pero las pruebas clínicas los intimidan. Esto convierte un screening calibrado de tonos puros en un juego donde el niño toca un personaje cada vez que oye un pitido tenue en distintas frecuencias, mapeando en silencio su curva de umbral. Exporta un audiograma limpio para un clínico. La demo juega y revela el mapa auditivo oculto tras la diversión.', 'health-medtech', '12-24h', 12, 24, 'intermediate', '["diagnostics","accessibility"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Migraine Trigger Finder that Correlates Diary and Weather', 'Detector de desencadenantes de migraña que cruza diario y clima', 'Migraine sufferers rarely spot their own patterns. Log each attack with a tap and the tool quietly pulls weather, sleep, and the foods you noted, then surfaces the correlations that actually predict your headaches — like pressure drops plus poor sleep. The demo loads a month of attacks and reveals the top two personalized triggers with a confidence note.', 'Quienes sufren migraña rara vez detectan sus propios patrones. Registra cada ataque con un toque y la herramienta cruza en silencio el clima, el sueño y los alimentos que anotaste, y luego muestra las correlaciones que de verdad predicen tus dolores — como caídas de presión más mal sueño. La demo carga un mes de ataques y revela los dos principales desencadenantes personalizados con una nota de confianza.', 'health-medtech', '12-24h', 12, 24, 'intermediate', '["diagnostics","wearable-health","med-data"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Pill Organizer Verifier that Catches a Wrong Fill', 'Verificador de pastillero que detecta un llenado incorrecto', 'After filling a weekly pill organizer, mistakes are easy and dangerous. Photograph the open box and the tool checks each compartment against your medication list — counting pills, recognizing shapes and colors — and flags a slot that has too many, too few, or the wrong pill. A focused safety check whose demo catches a deliberately wrong compartment on camera.', 'Tras llenar un pastillero semanal, los errores son fáciles y peligrosos. Fotografía la caja abierta y la herramienta revisa cada compartimento contra tu lista de medicamentos — contando pastillas, reconociendo formas y colores — y marca un casillero con demasiadas, muy pocas o la pastilla equivocada. Un control de seguridad enfocado cuya demo atrapa un compartimento mal llenado a propósito frente a la cámara.', 'health-medtech', '12-24h', 12, 24, 'advanced', '["diagnostics","accessibility"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Swallowing-Safety Coach for Texture-Modified Diets', 'Coach de deglución segura para dietas de textura modificada', 'People with dysphagia need food thickened to a precise consistency, and getting it wrong risks choking. Describe or photograph a drink or meal and the tool maps it to the standardized texture levels, shows the simple thickening fix, and explains the safe-swallow posture. The demo takes a normal glass of juice and produces the exact steps to make it safe.', 'Las personas con disfagia necesitan alimentos espesados a una consistencia precisa, y equivocarse implica riesgo de atragantamiento. Describe o fotografía una bebida o comida y la herramienta la asigna a los niveles de textura estandarizados, muestra el ajuste de espesado y explica la postura de deglución segura. La demo toma un vaso normal de jugo y produce los pasos exactos para hacerlo seguro.', 'health-medtech', '6-12h', 6, 12, 'intermediate', '["nutrition","accessibility"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Newborn Jaundice Estimator from a Calibrated Skin Photo', 'Estimador de ictericia neonatal por foto de piel calibrada', 'New parents struggle to judge if a baby''s yellow tint means dangerous jaundice. Place a printed color card beside the baby''s skin, take a photo, and the tool calibrates against the card to estimate a bilirubin risk band, telling you clearly when to seek care. The demo shows the card-based correction and the resulting risk readout, with a firm not-a-diagnosis caveat.', 'Los padres primerizos batallan para juzgar si el tinte amarillo de un bebé indica ictericia peligrosa. Coloca una tarjeta de color impresa junto a la piel del bebé, toma una foto y la herramienta se calibra con la tarjeta para estimar una banda de riesgo de bilirrubina, indicando con claridad cuándo buscar atención. La demo muestra la corrección con la tarjeta y la lectura de riesgo, con una firme advertencia de que no es un diagnóstico.', 'health-medtech', '12-24h', 12, 24, 'advanced', '["diagnostics","accessibility"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Two-Way Sign-Language Bridge for Emergency Rooms', 'Puente bidireccional de lengua de señas para urgencias', 'When a Deaf patient arrives at the ER without an interpreter, communication stalls. This tablet bridge captures the patient''s signed answers to common triage questions and shows them as text to staff, while turning staff prompts into clear signed-avatar or captioned questions back. The demo runs a triage exchange both directions so a judge feels the gap it closes.', 'Cuando un paciente sordo llega a urgencias sin intérprete, la comunicación se traba. Este puente en tablet capta las respuestas en señas del paciente a las preguntas comunes de triaje y las muestra como texto al personal, y convierte los mensajes del personal en preguntas claras con avatar de señas o subtítulos de vuelta. La demo corre un intercambio de triaje en ambos sentidos para que un juez sienta la brecha que cierra.', 'health-medtech', '24-48h', 24, 48, 'advanced', '["accessibility","telemedicine"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Wheelchair-Accessible Route Mapper from Crowd Reports', 'Mapeador de rutas accesibles en silla desde reportes de la gente', 'Map apps ignore curbs, steps, and broken elevators that block wheelchair users. This routes you door to door using accessibility data — ramp slopes, step-free paths, working lifts — and lets users drop quick reports that instantly reroute others. The demo plans a route across a city, then drops a broken-elevator report and shows the path adapt around it live.', 'Las apps de mapas ignoran cordones, escalones y ascensores rotos que bloquean a los usuarios de silla de ruedas. Esto te lleva de puerta a puerta usando datos de accesibilidad — pendientes de rampas, rutas sin escalones, ascensores en servicio — y permite dejar reportes rápidos que reenrutan a otros al instante. La demo planifica una ruta por una ciudad, luego registra un ascensor roto y muestra el camino adaptarse en vivo.', 'health-medtech', '24-48h', 24, 48, 'intermediate', '["accessibility"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Offline Triage Assistant for Disaster Field Medics', 'Asistente de triaje offline para médicos de campo en desastres', 'In a disaster zone with no signal, medics must triage many casualties fast and consistently. This fully offline tool walks a medic through a standard triage protocol per patient, assigns a color priority, and keeps a running board of everyone tagged so handoff to incoming teams is instant. The demo triages a wave of simulated casualties and shows the live priority board it builds.', 'En una zona de desastre sin señal, los médicos deben triar a muchas víctimas rápido y de forma consistente. Esta herramienta totalmente offline guía al médico por un protocolo de triaje estándar por paciente, asigna un color de prioridad y mantiene un tablero vivo de todos los etiquetados para que el relevo con los equipos entrantes sea instantáneo. La demo tría una ola de víctimas simuladas y muestra el tablero de prioridades que construye.', 'health-medtech', '24-48h', 24, 48, 'advanced', '["telemedicine","diagnostics","med-data"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Clinical Trial Matcher from a Plain Patient Story', 'Buscador de ensayos clínicos desde la historia simple del paciente', 'Patients rarely find trials they qualify for because eligibility criteria are dense and technical. Describe your condition and history in plain words and the tool matches you to open trials, explaining in plain language why you likely qualify or what would exclude you. The demo takes a patient narrative and returns a ranked, readable shortlist with the key eligibility gaps highlighted.', 'Los pacientes rara vez encuentran ensayos para los que califican porque los criterios de elegibilidad son densos y técnicos. Describe tu condición e historia en palabras simples y la herramienta te empareja con ensayos abiertos, explicando en lenguaje claro por qué probablemente calificas o qué te excluiría. La demo toma una narrativa de paciente y devuelve una lista corta jerarquizada y legible con las brechas clave de elegibilidad resaltadas.', 'health-medtech', '12-24h', 12, 24, 'intermediate', '["med-data","accessibility"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Dental X-Ray Cavity Highlighter for Patient Explanations', 'Resaltador de caries en radiografías para explicar al paciente', 'Patients can''t read their own dental X-rays, so they just trust the dentist. Upload a bitewing image and the tool highlights suspected cavities and bone-loss areas with a plain-language note for each, turning a gray blur into something a patient can actually understand. The demo overlays the findings on a real X-ray, framed clearly as an explanation aid, not a diagnosis.', 'Los pacientes no saben leer sus propias radiografías dentales, así que solo confían en el dentista. Sube una imagen de aleta de mordida y la herramienta resalta las caries sospechosas y las zonas de pérdida ósea con una nota en lenguaje claro para cada una, convirtiendo un borrón gris en algo que un paciente pueda entender. La demo superpone los hallazgos sobre una radiografía real, presentada claramente como apoyo explicativo, no un diagnóstico.', 'health-medtech', '12-24h', 12, 24, 'advanced', '["diagnostics","accessibility"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Grief Companion that Paces Support Across the First Year', 'Acompañante de duelo que dosifica el apoyo durante el primer año', 'Grief support tends to flood in early and vanish later, exactly backwards from when people need it. This companion paces gentle check-ins across the whole first year, anticipating hard dates like birthdays and anniversaries and offering grounding rituals tuned to each phase. The demo fast-forwards a timeline to show how it quietly shows up months later when most support has faded.', 'El apoyo en el duelo suele desbordarse al inicio y desvanecerse después, justo al revés de cuando la gente lo necesita. Este acompañante dosifica check-ins suaves a lo largo de todo el primer año, anticipando fechas difíciles como cumpleaños y aniversarios y ofreciendo rituales de contención ajustados a cada fase. La demo adelanta una línea de tiempo para mostrar cómo aparece en silencio meses después, cuando casi todo el apoyo ya se apagó.', 'health-medtech', '12-24h', 12, 24, 'intermediate', '["mental-health"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Insulin-on-Board Visualizer to Prevent Stacking', 'Visualizador de insulina activa para evitar apilar dosis', 'People on insulin risk dangerous lows by stacking doses before the last one has finished working. Log a dose and the tool models the remaining active insulin over time on a clear decay curve, warning when a new dose would overlap unsafely. The demo logs two doses close together and shows the overlap zone light up red, making an invisible risk visible.', 'Quienes usan insulina arriesgan bajadas peligrosas al apilar dosis antes de que la anterior termine de actuar. Registra una dosis y la herramienta modela la insulina activa restante en el tiempo sobre una curva de decaimiento clara, avisando cuando una nueva dosis se superpondría de forma insegura. La demo registra dos dosis muy seguidas y muestra la zona de superposición encenderse en rojo, haciendo visible un riesgo invisible.', 'health-medtech', '6-12h', 6, 12, 'intermediate', '["diagnostics","wearable-health","med-data"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Reading-Strain Detector that Adjusts Screen Text Live', 'Detector de fatiga lectora que ajusta el texto en pantalla en vivo', 'Eye strain and fatigue creep up silently during long reading. Using the webcam, the tool watches blink rate and squinting and, when strain rises, gently bumps up font size, contrast, and line spacing and suggests a micro-break. The demo simulates rising fatigue and shows the page reflow itself to stay comfortable, a quiet accessibility win for anyone reading for hours.', 'La fatiga y el cansancio visual se acumulan en silencio durante lecturas largas. Usando la webcam, la herramienta observa la tasa de parpadeo y el entrecerrar de ojos y, cuando sube la fatiga, aumenta suavemente el tamaño de fuente, el contraste y el interlineado y sugiere una micropausa. La demo simula fatiga creciente y muestra la página reorganizarse para mantenerse cómoda, una victoria silenciosa de accesibilidad para quien lee horas.', 'health-medtech', '6-12h', 6, 12, 'intermediate', '["accessibility","wearable-health"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Antibiotic Course Tracker that Prevents Early Stopping', 'Seguidor de antibióticos que evita abandonar el tratamiento antes', 'People feel better and stop antibiotics early, fueling resistance. Scan the prescription and the tool builds an exact dosing schedule with smart reminders, shows a progress bar of the full course, and explains plainly why finishing matters even when symptoms vanish. The demo sets up a real course and shows the streak and the gentle nudge that fires when a dose is missed.', 'La gente se siente mejor y deja los antibióticos antes de tiempo, alimentando la resistencia. Escanea la receta y la herramienta arma un cronograma exacto de dosis con recordatorios inteligentes, muestra una barra de progreso del tratamiento completo y explica con claridad por qué terminar importa aunque los síntomas desaparezcan. La demo configura un tratamiento real y muestra la racha y el aviso suave que salta cuando se olvida una dosis.', 'health-medtech', '3-6h', 3, 6, 'beginner', '["med-data","accessibility"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Pregnancy Kick-Counter that Learns Baby''s Normal Pattern', 'Contador de pataditas que aprende el patrón normal del bebé', 'Counting fetal movements helps catch problems, but a raw count means little without context. Tap each kick and the tool learns the baby''s own daily rhythm, then alerts gently when today''s activity drifts well below that personal baseline. The demo builds a few days of pattern, then simulates a quiet day and shows the personalized alert that suggests calling a midwife.', 'Contar los movimientos fetales ayuda a detectar problemas, pero un conteo crudo dice poco sin contexto. Toca en cada patadita y la herramienta aprende el ritmo diario propio del bebé, y luego avisa con suavidad cuando la actividad de hoy baja muy por debajo de esa línea base personal. La demo construye unos días de patrón, simula un día tranquilo y muestra la alerta personalizada que sugiere llamar a la partera.', 'health-medtech', '6-12h', 6, 12, 'intermediate', '["diagnostics","wearable-health"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Color-and-Texture Plate Coach for Balanced Meals', 'Coach de color y textura del plato para comidas equilibradas', 'Instead of counting calories, this nudges variety: photograph your plate and the tool scores how many color groups and food textures it covers, since diversity tracks with nutrient breadth. It suggests the one swap that would round it out. The demo snaps a beige, monochrome plate, scores it low, and shows it climb when a colorful side is added.', 'En lugar de contar calorías, esto fomenta la variedad: fotografía tu plato y la herramienta puntúa cuántos grupos de color y texturas de alimento cubre, ya que la diversidad acompaña la amplitud de nutrientes. Sugiere el único cambio que lo completaría. La demo fotografía un plato beige y monocromático, lo puntúa bajo y muestra cómo sube al agregar un acompañamiento colorido.', 'health-medtech', '3-6h', 3, 6, 'beginner', '["nutrition","fitness"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Telehealth Pre-Visit Summary Built from Patient Answers', 'Resumen previo a teleconsulta armado con respuestas del paciente', 'Telehealth visits waste minutes on basic history-taking. Before the call, the patient answers an adaptive questionnaire that drills into their main complaint, and the tool hands the clinician a tight structured summary — onset, severity, red flags, current meds. The demo walks a patient through intake and produces the one-screen brief the doctor opens, so the call starts at minute zero.', 'Las teleconsultas pierden minutos en tomar la historia básica. Antes de la llamada, el paciente responde un cuestionario adaptativo que profundiza en su motivo principal, y la herramienta entrega al clínico un resumen estructurado y conciso — inicio, severidad, señales de alarma, medicación actual. La demo guía a un paciente por la admisión y produce el resumen de una pantalla que el médico abre, para que la llamada arranque en el minuto cero.', 'health-medtech', '6-12h', 6, 12, 'intermediate', '["telemedicine","med-data"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Aphasia Communication Board that Predicts Next Words', 'Tablero de comunicación para afasia que predice palabras', 'People with aphasia struggle to retrieve words, and static picture boards are slow. This board predicts likely next words and phrases from context and the conversation so far, surfacing the right tiles before the user hunts for them, and speaks the chosen phrase aloud. The demo has someone build a sentence in a few taps as the predictions adapt, dramatically cutting the effort.', 'Las personas con afasia tienen dificultad para recuperar palabras, y los tableros de imágenes fijos son lentos. Este tablero predice las palabras y frases siguientes probables según el contexto y la conversación hasta el momento, mostrando las fichas adecuadas antes de que el usuario las busque, y dice en voz alta la frase elegida. La demo hace que alguien arme una oración en pocos toques mientras las predicciones se adaptan, reduciendo drásticamente el esfuerzo.', 'health-medtech', '12-24h', 12, 24, 'advanced', '["accessibility","mental-health"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Dehydration Spotter from Voice and a Few Quick Questions', 'Detector de deshidratación por voz y unas preguntas rápidas', 'Older adults and athletes miss early dehydration. The tool combines a short spoken sample — dry-mouth acoustic cues — with quick questions about urine color and dizziness to estimate a hydration risk band and a concrete drink-now recommendation. The demo runs the quick check and shows the risk readout, a fast field tool that needs no special hardware.', 'Los adultos mayores y los atletas pasan por alto la deshidratación temprana. La herramienta combina una muestra hablada corta — señales acústicas de boca seca — con preguntas rápidas sobre el color de la orina y los mareos para estimar una banda de riesgo de hidratación y una recomendación concreta de beber ya. La demo corre el chequeo rápido y muestra la lectura de riesgo, una herramienta de campo veloz que no necesita hardware especial.', 'health-medtech', '3-6h', 3, 6, 'intermediate', '["diagnostics","fitness","wearable-health"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Chronic-Condition Self-Management Coach Over Many Weeks', 'Coach de autocuidado de enfermedad crónica a lo largo de semanas', 'Living with a chronic condition like heart failure means juggling daily weight, symptoms, meds, and activity, with deterioration that creeps in slowly. This builds a full self-management program over weeks: daily check-ins, trend dashboards, escalating alerts when several signals drift together, and a shareable report for the care team. The demo simulates a slow decline and shows the system catch it days before a crisis.', 'Vivir con una enfermedad crónica como insuficiencia cardíaca implica gestionar a diario peso, síntomas, medicación y actividad, con un deterioro que se cuela lentamente. Esto construye un programa completo de autocuidado durante semanas: check-ins diarios, paneles de tendencias, alertas escaladas cuando varias señales se desvían juntas y un informe compartible para el equipo de salud. La demo simula un declive lento y muestra al sistema detectarlo días antes de una crisis.', 'health-medtech', '48h+', 48, 72, 'advanced', '["telemedicine","wearable-health","med-data","diagnostics"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Rural Eye-Camp Platform from Screening to Surgery Queue', 'Plataforma de campañas oculares de screening a cola de cirugía', 'Rural eye camps screen hundreds for cataracts and refractive errors but lose people between screening and surgery. This builds the full flow: offline visual-acuity and basic eye screening on a phone, automatic prioritization of who needs surgery soonest, and a synced queue that books and reminds patients when connectivity returns. The demo runs a camp end to end, from a vision check to a scheduled surgery slot.', 'Las campañas oculares rurales examinan a cientos por cataratas y errores refractivos pero pierden gente entre el screening y la cirugía. Esto construye el flujo completo: screening offline de agudeza visual y básico en un teléfono, priorización automática de quién necesita cirugía antes y una cola sincronizada que agenda y recuerda a los pacientes cuando vuelve la conectividad. La demo corre una campaña de punta a punta, de un chequeo de visión a un turno de cirugía agendado.', 'health-medtech', '48h+', 48, 72, 'advanced', '["telemedicine","diagnostics","accessibility","med-data"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Quit-Smoking Coach that Maps and Defuses Your Triggers', 'Coach para dejar de fumar que mapea y desactiva tus disparadores', 'Generic quit plans ignore that everyone''s cravings fire from different cues. Log each craving with a tap noting place, mood, and trigger; the tool learns your personal danger map and pre-empts high-risk moments with a tailored coping action right before they hit. The demo builds a few days of cravings and shows it predict the next risky window and intervene before the urge peaks.', 'Los planes genéricos para dejar de fumar ignoran que las ganas de cada persona se disparan por señales distintas. Registra cada antojo con un toque anotando lugar, ánimo y disparador; la herramienta aprende tu mapa personal de riesgo y se adelanta a los momentos peligrosos con una acción de afrontamiento a medida justo antes de que lleguen. La demo construye unos días de antojos y muestra cómo predice la próxima ventana riesgosa e interviene antes del pico.', 'health-medtech', '12-24h', 12, 24, 'intermediate', '["mental-health","wearable-health"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Single-Sensor Water-Safe Buoy that Scores a Sip', 'Boya de un sensor que califica si el agua es potable', 'A pocket probe you dip into a stream or tank that reads turbidity and TDS, then runs a tiny on-device model to flag the water as drink, boil, or avoid with a single LED color. The whole build is one sensor plus a microcontroller, so it fits a quick sprint and demos by dunking it in clean versus murky cups.', 'Una sonda de bolsillo que sumergís en un arroyo o tanque, mide turbidez y TDS y corre un modelo diminuto en el dispositivo para marcar el agua como tomar, hervir o evitar con un solo color de LED. Todo el armado es un sensor más un microcontrolador, así que entra en un sprint corto y se demuestra sumergiéndola en vasos limpios y turbios.', 'iot-hardware', '1-3h', 1, 3, 'beginner', '["sensors","arduino-rpi"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Desk Cube that Flips to Start and Stop a Time Log', 'Cubo de escritorio que registra tiempo al voltearlo', 'A small cube with an accelerometer where each face means a task; flip it and it logs the time you spend on that activity, beeping when you cross an hour. It needs only one motion sensor and a microcontroller, making it a sharp single-feature build whose demo is just turning the cube and watching the running tally change.', 'Un cubo pequeño con acelerómetro donde cada cara representa una tarea; lo volteás y registra el tiempo que pasás en esa actividad, sonando al cruzar una hora. Solo necesita un sensor de movimiento y un microcontrolador, lo que lo hace un build de una sola función cuya demo es voltear el cubo y ver cambiar el conteo.', 'iot-hardware', '1-3h', 1, 3, 'beginner', '["sensors","wearables"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('UV-Dose Badge that Buzzes When You Should Reapply', 'Insignia de dosis UV que vibra para reaplicar protector', 'A clip-on badge with a UV sensor that tracks accumulated sun exposure and gently buzzes once you hit a burn-risk threshold for your skin type, set with one dial. A single sensor and a vibration motor make it a tight short-sprint wearable; the demo shines a UV lamp and watches the alert trip in seconds.', 'Una insignia con clip y sensor UV que rastrea la exposición solar acumulada y vibra suavemente al alcanzar el umbral de riesgo de quemadura para tu tipo de piel, fijado con un dial. Un solo sensor y un motor de vibración la hacen un wearable ajustado para sprint corto; la demo apunta una lámpara UV y ve saltar la alerta en segundos.', 'iot-hardware', '1-3h', 1, 3, 'beginner', '["wearables","sensors"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Fridge-Door Tally that Counts How Often You Snack', 'Contador de puerta de heladera que cuenta tus picoteos', 'A magnetic reed switch on the fridge door logs every open, charts a daily snacking timeline, and flashes a light if you raid it past a bedtime you set. One cheap switch and a microcontroller make it a fast single-feature hack; the demo opens and closes the door and watches the count and timeline update live.', 'Un interruptor de lengüeta magnético en la puerta de la heladera registra cada apertura, grafica una línea de tiempo diaria de picoteo y enciende una luz si la asaltás pasada una hora límite que fijás. Un interruptor barato y un microcontrolador lo hacen un hack veloz de una función; la demo abre y cierra la puerta y ve actualizarse el conteo en vivo.', 'iot-hardware', '1-3h', 1, 3, 'beginner', '["sensors","home-automation"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Doorway Counter that Knows If a Room Is Empty', 'Contador de puerta que sabe si una sala está vacía', 'A pair of beam sensors at a doorway figures out direction of travel so it always knows the live headcount inside a room, then turns the lights off the moment it empties. Two sensors and a relay keep it a crisp short build; the demo walks people through the frame and shows the occupancy number rise and fall.', 'Un par de sensores de haz en una puerta deduce la dirección del paso para saber siempre cuánta gente hay dentro de una sala, y apaga las luces apenas queda vacía. Dos sensores y un relé lo mantienen un build corto y nítido; la demo hace pasar personas por el marco y muestra subir y bajar el número de ocupación.', 'iot-hardware', '3-6h', 3, 6, 'intermediate', '["sensors","lights","home-automation"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Cough-Counting Bedside Node for Tracking a Cold', 'Nodo de mesa de luz que cuenta tos para seguir un resfrío', 'A bedside box runs a tiny audio model that distinguishes coughs from other night sounds and charts how your cough frequency falls as you recover, all without sending audio off the device. A single mic and an edge model make it a focused half-day build; the demo fakes a few coughs and watches the nightly count climb.', 'Una caja de mesa de luz corre un modelo de audio diminuto que distingue toses de otros sonidos nocturnos y grafica cómo baja tu frecuencia de tos al recuperarte, sin enviar audio fuera del dispositivo. Un micrófono y un modelo en el borde la hacen un build enfocado de medio día; la demo simula unas toses y ve subir el conteo nocturno.', 'iot-hardware', '3-6h', 3, 6, 'intermediate', '["sensors","arduino-rpi"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Snore-Sensing Pillow Tag that Nudges You to Roll', 'Etiqueta de almohada que detecta ronquidos y te hace girar', 'A flat tag clipped to a pillow listens for snoring with an on-device sound model and gives a soft vibration to prompt a position change, logging how often it had to act. One mic, one motor, and a tiny classifier make it a sharp half-day wearable-adjacent build; the demo plays snore audio and feels the nudge fire.', 'Una etiqueta plana sujeta a la almohada escucha ronquidos con un modelo de sonido en el dispositivo y da una vibración suave para inducir un cambio de posición, registrando cuántas veces tuvo que actuar. Un micrófono, un motor y un clasificador diminuto la hacen un build ajustado de medio día; la demo reproduce audio de ronquido y siente saltar el empujón.', 'iot-hardware', '3-6h', 3, 6, 'intermediate', '["wearables","sensors"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Parking-Spot Sensor that Lights Free Bays Green', 'Sensor de estacionamiento que ilumina lugares libres en verde', 'Ultrasonic sensors over each bay in a small lot show a ceiling light per spot, green when free and red when taken, plus a single count of open spaces at the entrance. The per-bay node is cheap and repeatable, so a half-day yields a working aisle; the demo slides a box under a sensor and watches its light flip to red.', 'Sensores ultrasónicos sobre cada lugar de un estacionamiento chico muestran una luz de techo por plaza, verde si está libre y roja si ocupada, más un conteo único de espacios libres en la entrada. El nodo por plaza es barato y replicable, así que medio día rinde un pasillo funcional; la demo desliza una caja bajo un sensor y ve su luz pasar a rojo.', 'iot-hardware', '3-6h', 3, 6, 'intermediate', '["sensors","lights"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Soldering-Fume Watchdog that Vents Your Bench', 'Vigía de humos de soldadura que ventila tu banco', 'A bench node sniffs for solder fume particulates and VOCs, ramps a small fan when levels climb, and flashes amber if your face is too close to the plume. A gas sensor, a fan, and a distance sensor make it a contained half-day build; the demo waves a hot iron near it and watches the fan spin up automatically.', 'Un nodo de banco olfatea partículas de humo de soldadura y COV, acelera un ventilador chico cuando suben los niveles y parpadea ámbar si tu cara está muy cerca de la columna de humo. Un sensor de gas, un ventilador y un sensor de distancia lo hacen un build contenido de medio día; la demo acerca un soldador caliente y ve arrancar el ventilador solo.', 'iot-hardware', '3-6h', 3, 6, 'intermediate', '["sensors","home-automation","arduino-rpi"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Tap-to-Pair Light Switch that Skips the Wiring', 'Interruptor de luz por toque que evita el cableado', 'A battery-free wall button harvests the press energy itself to send a wireless toggle to a nearby lamp, so you can stick a new switch anywhere with no wiring. The hook is the energy-harvesting press; a half-day yields a working button-to-lamp pair, and the demo peels the switch off one wall and re-sticks it across the room.', 'Un botón de pared sin batería cosecha la energía de la propia pulsación para enviar un toggle inalámbrico a una lámpara cercana, así pegás un interruptor nuevo en cualquier lado sin cables. El gancho es la pulsación que cosecha energía; medio día rinde un par botón-lámpara funcional, y la demo despega el interruptor de una pared y lo repega al otro lado.', 'iot-hardware', '6-12h', 6, 12, 'advanced', '["lights","home-automation","energy-monitor"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Beehive Scale that Weighs the Colony and Warns of Loss', 'Balanza de colmena que pesa la colonia y avisa pérdidas', 'A load-cell platform under a beehive logs its weight through the day, learns the normal nectar-and-foraging rhythm, and pings the keeper when a sudden drop hints at a swarm or theft. One scale plus temperature gives a rich signal; a day of work yields a logging hive, and the demo lifts a jar off the plate to trigger a loss alert.', 'Una plataforma con celda de carga bajo una colmena registra su peso durante el día, aprende el ritmo normal de néctar y forrajeo, y avisa al apicultor cuando una caída brusca sugiere enjambrazón o robo. Una balanza más temperatura da una señal rica; un día de trabajo rinde una colmena con registro, y la demo levanta un frasco del plato para disparar la alerta de pérdida.', 'iot-hardware', '6-12h', 6, 12, 'intermediate', '["sensors","arduino-rpi","energy-monitor"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Tremor-Logging Spoon that Steadies a Shaky Hand', 'Cuchara que registra temblores y estabiliza la mano', 'A handle holds a small gimbal that counter-rotates to keep the spoon level despite hand tremor, while logging tremor intensity over meals to share with a clinician. The hook is active stabilization plus quiet tracking; a day yields a working motorized handle, and the demo shakes the grip while the bowl stays remarkably still.', 'Un mango sostiene un pequeño gimbal que contrarrota para mantener la cuchara nivelada pese al temblor de la mano, registrando la intensidad del temblor en las comidas para compartir con un clínico. El gancho es estabilización activa más seguimiento silencioso; un día rinde un mango motorizado funcional, y la demo agita la empuñadura mientras el cuenco queda notablemente quieto.', 'iot-hardware', '6-12h', 6, 12, 'advanced', '["wearables","robotics","sensors"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Geophone Stake that Hears Footsteps Before a Camera', 'Estaca con geófono que oye pasos antes que una cámara', 'A ground stake with a vibration geophone learns the seismic signature of human footsteps versus wind or animals and raises a silent alert without any camera, ideal for a privacy-respecting perimeter. The hook is camera-free detection through the soil; a day yields a trained node, and the demo has someone walk up while the alert lights only for people.', 'Una estaca con geófono de vibración aprende la firma sísmica de pasos humanos frente a viento o animales y levanta una alerta silenciosa sin cámara, ideal para un perímetro que respeta la privacidad. El gancho es la detección sin cámara a través del suelo; un día rinde un nodo entrenado, y la demo hace que alguien se acerque mientras la alerta se enciende solo para personas.', 'iot-hardware', '6-12h', 6, 12, 'advanced', '["sensors","home-automation","arduino-rpi"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Grip-Strength Cuff that Coaches Rehab Reps by Light', 'Brazalete de fuerza de agarre que guía la rehabilitación', 'A wrap-around cuff measures grip and pinch force, walks a patient through a prescribed rehab set with a light bar that fills as they squeeze, and logs progress across days. A force sensor and an LED bar make it a focused build; the demo squeezes the cuff and watches the bar fill and a rep counter tick up toward the target.', 'Un brazalete envolvente mide la fuerza de agarre y pinza, guía al paciente por una serie de rehabilitación prescrita con una barra de luz que se llena al apretar, y registra el progreso día a día. Un sensor de fuerza y una barra LED lo hacen un build enfocado; la demo aprieta el brazalete y ve llenarse la barra y subir un contador de repeticiones hacia la meta.', 'iot-hardware', '6-12h', 6, 12, 'intermediate', '["wearables","sensors"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Compost Bin Brain that Tells You When to Turn It', 'Cerebro de compostera que te dice cuándo voltearla', 'A probe in a compost pile tracks temperature, moisture, and gas to gauge how the decomposition is going, then advises exactly when to turn or water it for the fastest finish. Three sensors and a simple rule engine make it a tidy day build; the demo pours water in and watches the moisture reading and the next-action advice change.', 'Una sonda en una pila de compost rastrea temperatura, humedad y gas para evaluar cómo va la descomposición y luego aconseja exactamente cuándo voltearla o regarla para terminar más rápido. Tres sensores y un motor de reglas simple la hacen un build prolijo de un día; la demo echa agua y ve cambiar la lectura de humedad y el consejo de próxima acción.', 'iot-hardware', '6-12h', 6, 12, 'intermediate', '["sensors","arduino-rpi","home-automation"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Power-Strip Phantom-Load Killer that Cuts Vampire Watts', 'Zapatilla que corta el consumo fantasma en reposo', 'A smart strip senses when a device drops into standby draw and fully cuts its socket, surfacing how many vampire watts it reclaimed each day on a tiny display. Current sensing plus relays per socket make it a satisfying day build; the demo flips a TV to standby and watches the strip detect the idle draw and snap the outlet off.', 'Una zapatilla inteligente detecta cuándo un aparato cae a consumo en espera y corta del todo su toma, mostrando cuántos vatios vampiro recuperó cada día en una pantalla diminuta. La medición de corriente más relés por toma la hacen un build satisfactorio de un día; la demo pone un TV en espera y ve a la zapatilla detectar el consumo ocioso y apagar la toma.', 'iot-hardware', '6-12h', 6, 12, 'intermediate', '["energy-monitor","home-automation","sensors"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Whiteboard Plotter Bot that Redraws Your Sketch', 'Robot plotter de pizarra que redibuja tu boceto', 'A two-cable hanging plotter clings to any whiteboard and redraws an uploaded line sketch with a dry-erase marker, turning a meeting board into a print surface. The hook is the wall-climbing cable kinematics; a day yields a drawing bot, and the demo sends a doodle from a phone and watches the marker trace it on the board.', 'Un plotter colgante de dos cables se aferra a cualquier pizarra y redibuja un boceto de líneas cargado con un marcador borrable, convirtiendo un pizarrón de reunión en superficie de impresión. El gancho es la cinemática de cables que trepan la pared; un día rinde un bot dibujante, y la demo manda un garabato desde el teléfono y ve al marcador trazarlo en la pizarra.', 'iot-hardware', '6-12h', 6, 12, 'advanced', '["robotics","arduino-rpi"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Rain-Aware Awning that Rolls Out When Drops Hit', 'Toldo que se despliega cuando empiezan las gotas', 'A motorized patio awning watches a rain sensor and wind gauge to roll itself out at the first drops but retract before a gust can tear it, logging each weather event it reacted to. Two sensors and a motor make it a clean day build; the demo flicks water on the sensor and watches the awning extend, then fan-blasts it to make it retract.', 'Un toldo de patio motorizado vigila un sensor de lluvia y un anemómetro para desplegarse a las primeras gotas pero retraerse antes de que una ráfaga lo rompa, registrando cada evento al que reaccionó. Dos sensores y un motor lo hacen un build limpio de un día; la demo salpica agua en el sensor y ve extenderse el toldo, luego lo sopla con un ventilador para retraerlo.', 'iot-hardware', '6-12h', 6, 12, 'intermediate', '["home-automation","sensors","robotics"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Crowd-Density Beacon that Warns When a Room Packs In', 'Baliza de densidad que avisa cuando una sala se llena', 'A ceiling node estimates how many phones and bodies are in a space using Wi-Fi probe counts and a thermal grid, then shifts a public light from green to red as crowding nears a safe limit. Sensor fusion makes it a meaty day build; the demo fills the area with people and watches the density readout and the warning light climb.', 'Un nodo de techo estima cuántos teléfonos y cuerpos hay en un espacio usando conteos de sondas Wi-Fi y una grilla térmica, y luego cambia una luz pública de verde a rojo a medida que la aglomeración se acerca a un límite seguro. La fusión de sensores la hace un build sustancioso de un día; la demo llena el área de gente y ve subir la densidad y la luz de aviso.', 'iot-hardware', '6-12h', 6, 12, 'advanced', '["sensors","lights","energy-monitor"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Gait-Watching Insole that Flags an Uneven Limp', 'Plantilla que observa la marcha y marca una cojera', 'A pressure-sensing insole maps how your weight rolls across each foot, compares left versus right, and flags a developing limp or favoring before it becomes an injury. Pressure arrays plus an on-device model make it a full-day wearable; the demo walks normally then fakes a limp and watches the asymmetry score spike on screen.', 'Una plantilla con sensores de presión mapea cómo rueda tu peso por cada pie, compara izquierda contra derecha y marca una cojera o un favorecimiento incipiente antes de que sea lesión. Las matrices de presión más un modelo en el dispositivo la hacen un wearable de un día completo; la demo camina normal y luego finge cojear y ve dispararse el puntaje de asimetría.', 'iot-hardware', '12-24h', 12, 24, 'advanced', '["wearables","sensors","arduino-rpi"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Sorting Conveyor that Routes Parts by Size and Color', 'Cinta clasificadora que enruta piezas por tamaño y color', 'A short conveyor with a camera and a few air jets sorts small parts into bins by size and color in real time, showing a live count per category. Vision plus timed actuation make it a rich overnight build; the demo dumps a mixed handful on the belt and watches each piece get blown into the right bin as the tallies update.', 'Una cinta corta con cámara y unos chorros de aire clasifica piezas chicas en cajones por tamaño y color en tiempo real, mostrando un conteo en vivo por categoría. La visión más la actuación temporizada la hacen un build nocturno rico; la demo vuelca un puñado mezclado en la cinta y ve cada pieza soplada al cajón correcto mientras se actualizan los conteos.', 'iot-hardware', '12-24h', 12, 24, 'advanced', '["robotics","sensors","arduino-rpi"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Cold-Chain Tag that Proves a Package Stayed Chilled', 'Etiqueta de cadena de frío que prueba que se mantuvo fría', 'A stick-on logger rides inside a shipment, records the full temperature history, and at delivery shows a green or red verdict plus the exact minutes it spent out of the safe range. Logging plus a tamper-evident readout make it a solid day build; the demo warms the tag briefly and watches the verdict flip to red with the breach time shown.', 'Un registrador adhesivo viaja dentro de un envío, graba todo el historial de temperatura y al entregar muestra un veredicto verde o rojo más los minutos exactos fuera del rango seguro. El registro más una lectura a prueba de manipulación lo hacen un build sólido de un día; la demo calienta la etiqueta un momento y ve el veredicto pasar a rojo con el tiempo de violación mostrado.', 'iot-hardware', '12-24h', 12, 24, 'intermediate', '["sensors","wearables","energy-monitor"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Braille Cell Strip that Refreshes Text Line by Line', 'Tira de celdas braille que refresca texto línea a línea', 'A row of motorized pins forms a refreshable braille line that steps through any pasted text one segment at a time at a pace the reader sets with a thumb wheel. The hook is low-cost refreshable braille from servos or solenoids; an overnight build yields a readable cell, and the demo pastes a sentence and feels the pins reshape as it advances.', 'Una fila de pines motorizados forma una línea braille refrescable que recorre cualquier texto pegado un segmento a la vez al ritmo que el lector fija con una rueda de pulgar. El gancho es braille refrescable de bajo costo con servos o solenoides; un build nocturno rinde una celda legible, y la demo pega una frase y se siente a los pines reformarse al avanzar.', 'iot-hardware', '12-24h', 12, 24, 'advanced', '["robotics","arduino-rpi","wearables"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Soil Network that Tells Each Bed What to Plant Next', 'Red de suelo que dice qué plantar en cada cantero', 'A handful of wireless soil stakes across garden beds track moisture, light hours, and nutrient proxies, then recommend which crop suits each bed this season based on its real conditions. Multi-node sensing plus a matching rule set make it a full-day build; the demo shades one stake and waters another and watches their crop suggestions diverge.', 'Un puñado de estacas de suelo inalámbricas por los canteros del jardín rastrean humedad, horas de luz y proxies de nutrientes, y luego recomiendan qué cultivo conviene a cada cantero esta temporada según sus condiciones reales. El sensado multinodo más un conjunto de reglas de emparejamiento lo hacen un build de un día; la demo sombrea una estaca y riega otra y ve divergir sus sugerencias de cultivo.', 'iot-hardware', '12-24h', 12, 24, 'intermediate', '["sensors","home-automation","arduino-rpi"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('EMG Armband that Maps a Clench to Any Key Combo', 'Banda EMG que asigna un apriete a cualquier atajo', 'An armband reads forearm muscle signals so a clench, a flick, or a finger pinch can fire any keyboard shortcut hands-free, with a quick on-device training step per gesture. Cheap EMG plus gesture classification make it a rich overnight build; the demo trains three clenches live and uses them to switch slides without touching anything.', 'Una banda de brazo lee señales musculares del antebrazo para que un apriete, un golpe o un pellizco disparen cualquier atajo de teclado sin manos, con un paso rápido de entrenamiento por gesto en el dispositivo. EMG barato más clasificación de gestos la hacen un build nocturno rico; la demo entrena tres aprietes en vivo y los usa para pasar diapositivas sin tocar nada.', 'iot-hardware', '12-24h', 12, 24, 'advanced', '["wearables","sensors"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Window-Crawling Cleaner Bot for Glass You Can''t Reach', 'Robot que trepa ventanas para limpiar vidrios altos', 'A suction-driven bot adheres to a window, plans a coverage path across the pane, and squeegees it clean while a tether catches it if suction ever fails. The hook is safe vertical adhesion with fall protection; a long sprint yields a crawling cleaner, and the demo sticks it to a glass door and watches it map and wipe the whole pane.', 'Un robot por succión se adhiere a una ventana, planifica un recorrido de cobertura por el vidrio y lo limpia con un secador mientras un cordel lo atrapa si la succión falla. El gancho es la adhesión vertical segura con protección anticaída; un sprint largo rinde un limpiador trepador, y la demo lo pega a una puerta de vidrio y lo ve mapear y limpiar todo el panel.', 'iot-hardware', '24-48h', 24, 48, 'advanced', '["robotics","sensors","home-automation"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Beach Litter Rover that Sifts Sand for Microplastics', 'Rover de playa que tamiza arena buscando microplásticos', 'A tracked rover drives a beach line, scoops and sifts sand through a screen, and uses a camera to tally suspected plastic fragments onto a cleanup heat map. Mobility plus on-device vision make it a meaty two-day build; the demo runs it over a sandbox seeded with bits and watches the map fill in where it found the most.', 'Un rover con orugas recorre una línea de playa, recoge y tamiza arena por una malla y usa una cámara para contar fragmentos sospechosos de plástico en un mapa de calor de limpieza. La movilidad más la visión en el dispositivo la hacen un build sustancioso de dos días; la demo lo pasa por un cajón de arena sembrado con trozos y ve llenarse el mapa donde más encontró.', 'iot-hardware', '24-48h', 24, 48, 'advanced', '["robotics","sensors","drones"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Crop-Scout Drone that Flags Sick Plants from the Air', 'Dron explorador que marca plantas enfermas desde el aire', 'A small drone flies a saved grid over a field, captures multispectral-style imagery, and lands with a map pinning the rows where plant stress or disease is creeping in. Autonomous routing plus crop-stress vision make it a full two-day build; the demo flies it over a planter and shows the heat map lighting up over the wilted plants.', 'Un dron pequeño vuela una grilla guardada sobre un campo, captura imágenes de estilo multiespectral y aterriza con un mapa que marca las hileras donde el estrés o la enfermedad de las plantas avanza. El ruteo autónomo más la visión de estrés vegetal lo hacen un build de dos días; la demo lo vuela sobre una jardinera y muestra el mapa de calor encendiéndose sobre las plantas marchitas.', 'iot-hardware', '24-48h', 24, 48, 'advanced', '["drones","sensors","robotics"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Exo-Glove that Adds Grip for a Weak Hand', 'Exoguante que suma agarre a una mano debilitada', 'A soft tendon-driven glove senses your intent to close and adds gentle motorized force so a weak or recovering hand can grip a mug or a doorknob. The hook is assistive force that follows your own effort; a two-day build yields a working glove, and the demo has someone grasp an object they couldn''t hold before as the assist kicks in.', 'Un guante blando accionado por tendones detecta tu intención de cerrar y suma una fuerza motorizada suave para que una mano débil o en recuperación pueda agarrar una taza o un picaporte. El gancho es la fuerza asistiva que sigue tu propio esfuerzo; un build de dos días rinde un guante funcional, y la demo hace que alguien agarre un objeto que antes no podía mientras entra la asistencia.', 'iot-hardware', '24-48h', 24, 48, 'advanced', '["wearables","robotics","sensors"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Tabletop Foosball Bot that Defends with a Camera', 'Robot de metegol de mesa que defiende con una cámara', 'A motorized rod on a foosball table watches the ball with an overhead camera and slides and kicks to defend its goal against a human attacker in real time. Fast vision plus snappy actuation make it a thrilling two-day build; the demo lets a player shoot on goal and watches the robot rod intercept the ball again and again.', 'Una varilla motorizada en una mesa de metegol observa la pelota con una cámara cenital y se desliza y patea para defender su arco contra un atacante humano en tiempo real. La visión rápida más la actuación ágil la hacen un build emocionante de dos días; la demo deja que un jugador remate al arco y ve a la varilla robot interceptar la pelota una y otra vez.', 'iot-hardware', '24-48h', 24, 48, 'advanced', '["robotics","sensors","arduino-rpi"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Off-Grid Weather Mast that Lives on Sun and LoRa', 'Mástil meteorológico autónomo con sol y LoRa', 'A solar-powered mast logs wind, rain, temperature, and humidity and relays it kilometers over LoRa with no mains power or cell signal, surviving on a battery sized to its own harvest. The hook is true off-grid endurance; a two-day build yields a self-powered station, and the demo cuts its USB power and watches it keep transmitting on solar alone.', 'Un mástil alimentado por sol registra viento, lluvia, temperatura y humedad y los retransmite kilómetros por LoRa sin red eléctrica ni señal celular, sobreviviendo con una batería dimensionada a su propia cosecha. El gancho es la autonomía real fuera de la red; un build de dos días rinde una estación autoalimentada, y la demo le corta el USB y la ve seguir transmitiendo solo con solar.', 'iot-hardware', '24-48h', 24, 48, 'advanced', '["sensors","energy-monitor","arduino-rpi"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Autonomous Shelf Scanner that Spots Empty Slots', 'Escáner de góndola autónomo que detecta huecos vacíos', 'A small floor robot rolls a store aisle, scans the shelves with a camera, and produces a restock list of empty or misplaced facings without anyone walking the aisle. Navigation plus shelf-gap vision make it a deep multi-day build; the demo sends it down a mock aisle and watches it return a map flagging exactly which slots ran out.', 'Un pequeño robot de piso recorre un pasillo de tienda, escanea las góndolas con una cámara y produce una lista de reposición de huecos vacíos o mal ubicados sin que nadie camine el pasillo. La navegación más la visión de huecos en estantería lo hacen un build profundo de varios días; la demo lo manda por un pasillo simulado y lo ve devolver un mapa marcando qué espacios se agotaron.', 'iot-hardware', '48h+', 48, 72, 'advanced', '["robotics","sensors","arduino-rpi"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Two-Drone Tag Team that Hands Off a Tracked Runner', 'Dúo de drones que se relevan siguiendo a un corredor', 'A pair of drones cover a route together, keeping a moving subject in frame and handing the follow off from one to the other when battery runs low so coverage never drops. The hook is the airborne handoff between aircraft; a long build yields a working relay, and the demo has someone jog a loop while the lead drone passes tracking to its partner.', 'Un par de drones cubren juntos un recorrido, manteniendo a un sujeto en movimiento en cuadro y pasándose el seguimiento de uno a otro cuando baja la batería para que la cobertura nunca se corte. El gancho es el relevo aéreo entre aeronaves; un build largo rinde un relevo funcional, y la demo hace que alguien trote una vuelta mientras el dron líder pasa el seguimiento a su compañero.', 'iot-hardware', '48h+', 48, 72, 'advanced', '["drones","robotics","sensors"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Stair-Climbing Cargo Bot for Last-Meter Deliveries', 'Robot que sube escaleras para la entrega del último metro', 'A tracked or legged cargo bot carries a parcel up a flight of stairs to a door, balancing the load and finding each step without help. The hook is conquering stairs, the one obstacle wheeled delivery bots fail at; a multi-day build yields a climbing carrier, and the demo loads a box and watches it ascend a real staircase to deliver it.', 'Un robot de carga con orugas o patas lleva un paquete por un tramo de escaleras hasta una puerta, equilibrando la carga y encontrando cada escalón sin ayuda. El gancho es vencer las escaleras, el obstáculo que los robots de entrega con ruedas no superan; un build de varios días rinde un cargador trepador, y la demo carga una caja y lo ve subir una escalera real para entregarla.', 'iot-hardware', '48h+', 48, 72, 'advanced', '["robotics","sensors","arduino-rpi"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Always-On Terminal Debugger that Records Every Command', 'Depurador de terminal siempre activo que graba cada comando', 'A background daemon that quietly records every command you run, its exit code, and its output, then lets you scrub back through the session like a timeline when something breaks. Instead of re-running things blindly, you replay the exact failing command and inspect the environment as it was. The demo breaks a build, then rewinds to the moment it went wrong.', 'Un demonio en segundo plano que graba en silencio cada comando que ejecutas, su código de salida y su salida, y luego te deja recorrer la sesión como una línea de tiempo cuando algo falla. En vez de repetir todo a ciegas, reproduces el comando exacto que falló e inspeccionas el entorno tal como estaba. La demo rompe un build y rebobina al momento justo en que se quebró.', 'productivity-devtools', '12-24h', 12, 24, 'advanced', '["cli-tools","automation"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Local-First Agent that Runs Plain-English Shell Tasks', 'Agente local que ejecuta tareas de shell en lenguaje natural', 'Type a task in plain English and a local agent proposes the shell commands to do it, shows you exactly what it will run, and only executes after you approve each step. Nothing leaves your machine, and every run is logged so you can audit what happened. The demo asks it to find and compress old logs, then watches it draft, confirm, and execute safely.', 'Escribe una tarea en lenguaje natural y un agente local propone los comandos de shell para hacerla, te muestra exactamente qué ejecutará y solo actúa tras tu aprobación paso a paso. Nada sale de tu máquina y cada ejecución queda registrada para que audites lo ocurrido. La demo le pide encontrar y comprimir logs viejos y lo ve redactar, confirmar y ejecutar con seguridad.', 'productivity-devtools', '12-24h', 12, 24, 'advanced', '["automation","cli-tools"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Stack Trace Untangler that Folds Library Frames Away', 'Desenredador de stack traces que pliega los marcos de librerías', 'Paste a noisy stack trace and the tool collapses framework and dependency frames into one line, leaving only the frames from your own code highlighted and clickable. It guesses the likely culprit line and explains the call chain in order. A tight single-screen build that turns a wall of red text into the three lines that actually matter.', 'Pega un stack trace ruidoso y la herramienta colapsa los marcos del framework y las dependencias en una sola línea, dejando solo los marcos de tu propio código resaltados y clicables. Adivina la línea culpable más probable y explica la cadena de llamadas en orden. Un build de una sola pantalla que convierte un muro de texto rojo en las tres líneas que de verdad importan.', 'productivity-devtools', '3-6h', 3, 6, 'intermediate', '["cli-tools","testing"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Dependency Bloat Visualizer that Ranks What to Drop', 'Visualizador de exceso de dependencias que ordena qué quitar', 'Point it at a lockfile and it draws your dependency tree sized by install weight, then ranks packages by how much you''d save versus how little you actually import. It flags duplicates pulled in at different versions and one-function libraries you could inline. The demo loads a real project and surfaces the three packages worth removing first.', 'Apúntalo a un lockfile y dibuja tu árbol de dependencias dimensionado por peso de instalación, luego ordena los paquetes según cuánto ahorrarías frente a lo poco que realmente importas. Marca duplicados traídos en versiones distintas y librerías de una sola función que podrías incorporar. La demo carga un proyecto real y destaca los tres paquetes que conviene quitar primero.', 'productivity-devtools', '6-12h', 6, 12, 'intermediate', '["cli-tools","automation"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Flaky Network Simulator that Tortures Your App Live', 'Simulador de red inestable que tortura tu app en vivo', 'A local proxy that injects latency, packet loss, and random 500s into your app''s outgoing calls so you can see how the UI behaves under a bad connection. You toggle scenarios from a panel and watch retries, timeouts, and spinners react in real time. The demo runs a checkout flow on a fake subway-tunnel connection and exposes every place it hangs.', 'Un proxy local que inyecta latencia, pérdida de paquetes y errores 500 aleatorios en las llamadas salientes de tu app para ver cómo se comporta la UI con mala conexión. Activas escenarios desde un panel y observas reintentos, timeouts y spinners reaccionar en tiempo real. La demo corre un flujo de pago sobre una conexión falsa de túnel de subte y expone cada punto donde se cuelga.', 'productivity-devtools', '6-12h', 6, 12, 'intermediate', '["testing","api-tools"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Changelog Drafter that Groups Commits by User Impact', 'Redactor de changelog que agrupa commits por impacto al usuario', 'Feed it a range of commits and it drafts a release changelog split into what users will notice, what developers should know, and internal-only noise. It rewrites terse commit subjects into readable bullet points and flags breaking changes at the top. The demo turns a messy week of commits into a polished release note ready to paste.', 'Dale un rango de commits y redacta un changelog de versión dividido en lo que los usuarios notarán, lo que los desarrolladores deben saber y el ruido solo interno. Reescribe asuntos de commit escuetos en viñetas legibles y marca los cambios incompatibles arriba. La demo convierte una semana caótica de commits en una nota de versión pulida lista para pegar.', 'productivity-devtools', '3-6h', 3, 6, 'intermediate', '["automation","collaboration"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Onboarding Map that Traces a Repo''s Real Entry Points', 'Mapa de onboarding que rastrea los puntos de entrada reales', 'Drop a new dev into an unfamiliar repo and this tool draws the actual paths a request takes from entry point to database, ranking which files matter most by how often they sit on those paths. It generates a guided reading order instead of a flat file list. The demo opens a strange codebase and produces a one-page tour of where to start.', 'Mete a un dev nuevo en un repo desconocido y esta herramienta dibuja los caminos reales que toma una petición desde el punto de entrada hasta la base de datos, ordenando qué archivos importan más según cuán seguido están en esos caminos. Genera un orden de lectura guiado en vez de una lista plana de archivos. La demo abre un código extraño y produce un recorrido de una página de por dónde empezar.', 'productivity-devtools', '12-24h', 12, 24, 'advanced', '["knowledge-mgmt","collaboration"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Schema Migration Previewer that Shows Locked Rows', 'Previsualizador de migraciones que muestra filas bloqueadas', 'Paste a migration and it explains in plain language what each statement does, estimates how long it will lock the table, and warns when a change will block writes on a large table. It suggests a safer online-migration ordering when one exists. The demo takes a scary ALTER on a million-row table and reveals the hidden production stall before it ships.', 'Pega una migración y explica en lenguaje claro qué hace cada sentencia, estima cuánto bloqueará la tabla y avisa cuando un cambio bloqueará escrituras en una tabla grande. Sugiere un orden de migración online más seguro cuando existe. La demo toma un ALTER aterrador sobre una tabla de un millón de filas y revela el bloqueo oculto en producción antes de desplegar.', 'productivity-devtools', '6-12h', 6, 12, 'advanced', '["cli-tools","testing"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Paste-Anywhere Formatter that Detects the Language First', 'Formateador universal que detecta el lenguaje primero', 'Paste any blob — JSON, XML, SQL, a stack trace, a JWT — and the tool guesses what it is, then formats, pretty-prints, or decodes it without you choosing a mode. It chains transforms, so a base64 string that contains JSON unfolds in one click. A fast single-screen utility that kills the daily hunt for the right online formatter.', 'Pega cualquier bloque — JSON, XML, SQL, un stack trace, un JWT — y la herramienta adivina qué es, luego lo formatea, lo imprime ordenado o lo decodifica sin que elijas un modo. Encadena transformaciones, así un base64 que contiene JSON se despliega en un clic. Una utilidad rápida de una sola pantalla que mata la búsqueda diaria del formateador online correcto.', 'productivity-devtools', '1-3h', 1, 3, 'beginner', '["cli-tools","api-tools"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Build Time Profiler that Blames the Slowest Steps', 'Perfilador de tiempos de build que culpa a los pasos lentos', 'Wrap your build or CI script and the tool times each step, then draws a waterfall that highlights the few stages eating most of the wall clock. It tracks runs over time so you can see when a step suddenly got slower and what commit did it. The demo profiles a sluggish pipeline and points straight at the install step nobody suspected.', 'Envuelve tu script de build o CI y la herramienta cronometra cada paso, luego dibuja una cascada que resalta las pocas etapas que se comen casi todo el tiempo real. Registra ejecuciones en el tiempo para ver cuándo un paso se volvió lento y qué commit lo causó. La demo perfila un pipeline lento y apunta directo al paso de instalación que nadie sospechaba.', 'productivity-devtools', '6-12h', 6, 12, 'intermediate', '["automation","cli-tools"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Feature Flag Janitor that Finds Flags Safe to Delete', 'Conserje de feature flags que halla flags seguros de borrar', 'Scan a codebase and the tool lists every feature flag, how long it''s been fully on or off, and where it''s still referenced, then ranks which stale flags are safe to rip out. It generates the cleanup diff that removes the dead branch behind each flag. The demo finds a flag that''s been 100% live for a year and offers the one-click removal.', 'Escanea un código y la herramienta lista cada feature flag, cuánto lleva totalmente encendido o apagado y dónde se referencia aún, luego ordena qué flags obsoletos son seguros de eliminar. Genera el diff de limpieza que quita la rama muerta detrás de cada flag. La demo encuentra un flag activo al 100% desde hace un año y ofrece la eliminación en un clic.', 'productivity-devtools', '6-12h', 6, 12, 'intermediate', '["automation","cli-tools"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Test Data Factory that Builds Realistic Rows from a Schema', 'Fábrica de datos de prueba que genera filas reales de un esquema', 'Point it at a table schema and it generates believable seed data that respects foreign keys, value ranges, and formats like emails and phone numbers, instead of dumping random gibberish. You tune the shape — mostly active users, a few edge cases — and export ready-to-load rows. The demo fills an empty database with a coherent set of customers and orders in one pass.', 'Apúntalo a un esquema de tabla y genera datos de semilla creíbles que respetan claves foráneas, rangos de valores y formatos como emails y teléfonos, en vez de volcar basura aleatoria. Ajustas la forma — usuarios mayormente activos, unos pocos casos límite — y exportas filas listas para cargar. La demo llena una base vacía con un conjunto coherente de clientes y pedidos de una sola vez.', 'productivity-devtools', '6-12h', 6, 12, 'intermediate', '["testing","automation"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('OpenAPI Diff that Speaks in Breaking and Safe Changes', 'Diff de OpenAPI que habla de cambios rotos y seguros', 'Drop two versions of an API spec and the tool classifies every difference as breaking, additive, or cosmetic, then writes the migration notes a consumer needs. It catches the subtle ones — a field that became required, an enum value removed — that plain text diffs hide. The demo compares two specs and produces a clear go or no-go for shipping the change.', 'Suelta dos versiones de una spec de API y la herramienta clasifica cada diferencia como ruptura, agregado o cosmética, luego escribe las notas de migración que un consumidor necesita. Atrapa las sutiles — un campo que se volvió obligatorio, un valor de enum eliminado — que los diffs de texto plano ocultan. La demo compara dos specs y produce un claro sí o no para publicar el cambio.', 'productivity-devtools', '3-6h', 3, 6, 'intermediate', '["api-tools","testing"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Code Review Pre-Flight that Comments Before Humans Do', 'Pre-revisión de código que comenta antes que los humanos', 'Run it on your own diff before opening a pull request and it leaves the comments a reviewer probably would — missing null checks, untested branches, a name that lies about what it does — so you fix them privately first. It groups nitpicks separately from real concerns. The demo runs on a fresh diff and hands back a tidy list of self-fixes before anyone else looks.', 'Córrelo sobre tu propio diff antes de abrir un pull request y deja los comentarios que probablemente haría un revisor — chequeos de null faltantes, ramas sin probar, un nombre que miente sobre lo que hace — para que los arregles en privado primero. Separa las nimiedades de las preocupaciones reales. La demo corre sobre un diff nuevo y devuelve una lista ordenada de autocorrecciones antes de que otro lo mire.', 'productivity-devtools', '6-12h', 6, 12, 'intermediate', '["collaboration","testing"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Secret Rotation Reminder that Reads Your Expiry Dates', 'Recordatorio de rotación que lee tus fechas de vencimiento', 'Point it at your certs, tokens, and API keys and it parses their real expiry dates, then builds a calendar of what dies when and nags you before each one lapses. It groups secrets by service so you rotate related ones together. The demo scans a config folder and surfaces the TLS cert quietly expiring next Tuesday before it takes prod down.', 'Apúntalo a tus certificados, tokens y claves de API y parsea sus fechas reales de vencimiento, luego arma un calendario de qué muere cuándo y te avisa antes de que cada uno caduque. Agrupa secretos por servicio para que rotes los relacionados juntos. La demo escanea una carpeta de configuración y destaca el certificado TLS que vence el martes antes de que tumbe producción.', 'productivity-devtools', '3-6h', 3, 6, 'intermediate', '["automation","time-mgmt"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Visual Diff for Rendered Output, Not Just Source Lines', 'Diff visual de la salida renderizada, no solo del código', 'Instead of diffing source, this tool renders the before and after of generated output — a chart, an email template, a PDF — and overlays exactly which pixels moved. It flags unintended visual regressions a line diff would never show. The demo edits a template, then highlights that one logo shifted four pixels while the code looked harmless.', 'En vez de comparar código, esta herramienta renderiza el antes y el después de una salida generada — un gráfico, una plantilla de email, un PDF — y superpone exactamente qué píxeles se movieron. Marca regresiones visuales no intencionadas que un diff de líneas jamás mostraría. La demo edita una plantilla y resalta que un logo se corrió cuatro píxeles aunque el código parecía inofensivo.', 'productivity-devtools', '6-12h', 6, 12, 'intermediate', '["testing","automation"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Meeting-Free Block Negotiator for a Whole Team Calendar', 'Negociador de bloques sin reuniones para todo el equipo', 'Connect a team''s calendars and the tool proposes shared maker-time blocks where it can carve focus hours for everyone with the fewest meetings moved. It shows the trade-offs and lets the team vote before applying. The demo takes a fractured week of overlapping meetings and finds two protected mornings the whole team can keep.', 'Conecta los calendarios de un equipo y la herramienta propone bloques compartidos de tiempo de creación donde puede tallar horas de foco para todos moviendo la menor cantidad de reuniones. Muestra los compromisos y deja que el equipo vote antes de aplicar. La demo toma una semana fragmentada de reuniones superpuestas y encuentra dos mañanas protegidas que todo el equipo puede conservar.', 'productivity-devtools', '6-12h', 6, 12, 'intermediate', '["time-mgmt","collaboration"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Local Webhook Tunnel that Names and Filters Events', 'Túnel de webhooks local que nombra y filtra eventos', 'Expose your local server to receive real webhooks, but instead of a raw firehose the tool labels each event by type, lets you filter to the ones you care about, and pins the exact payload you''re debugging. You can edit and re-fire any captured event. A focused build for the painful loop of testing third-party callbacks against localhost.', 'Expone tu servidor local para recibir webhooks reales, pero en vez de una manguera cruda la herramienta etiqueta cada evento por tipo, te deja filtrar los que te importan y fija el payload exacto que estás depurando. Puedes editar y reenviar cualquier evento capturado. Un build enfocado para el doloroso ciclo de probar callbacks de terceros contra localhost.', 'productivity-devtools', '6-12h', 6, 12, 'intermediate', '["api-tools","cli-tools"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Config Drift Detector Across Your Dev and Prod Envs', 'Detector de deriva de configuración entre dev y prod', 'Feed it the config from two environments and it lines them up key by key, highlighting where dev and prod silently disagree and which differences are expected versus dangerous. It learns which keys should differ so it stops crying wolf. The demo compares staging and prod and surfaces the one feature flag set differently that explains the bug.', 'Dale la configuración de dos entornos y los alinea clave por clave, resaltando dónde dev y prod difieren en silencio y qué diferencias son esperadas frente a peligrosas. Aprende qué claves deberían diferir para dejar de dar falsas alarmas. La demo compara staging y prod y destaca el único feature flag configurado distinto que explica el bug.', 'productivity-devtools', '3-6h', 3, 6, 'intermediate', '["automation","cli-tools"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Personal Command Palette that Learns Your Shell Aliases', 'Paleta de comandos personal que aprende tus alias de shell', 'A fuzzy launcher that watches your real command history, surfaces the long incantations you keep retyping, and offers to save them as named, parameterized shortcuts. It fills in the variable parts with a quick prompt at run time. A small but addictive build that turns your own habits into a personal command menu.', 'Un lanzador difuso que observa tu historial real de comandos, destaca los conjuros largos que vuelves a teclear y ofrece guardarlos como atajos nombrados y parametrizados. Completa las partes variables con una pregunta rápida al ejecutar. Un build pequeño pero adictivo que convierte tus propios hábitos en un menú de comandos personal.', 'productivity-devtools', '3-6h', 3, 6, 'intermediate', '["cli-tools","time-mgmt"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('No-Code Form to Database App in One Shareable Link', 'App de formulario a base de datos en un enlace compartible', 'Drag fields onto a canvas and the tool instantly stands up a working form backed by a real table, complete with validation and a sortable view of submissions, shared as a single link. No deploy step, no schema writing. The demo builds a small intake form live and shows responses landing in a queryable table seconds later.', 'Arrastra campos a un lienzo y la herramienta levanta al instante un formulario funcional respaldado por una tabla real, con validación y una vista ordenable de respuestas, compartida como un solo enlace. Sin paso de despliegue, sin escribir esquemas. La demo construye un pequeño formulario de ingreso en vivo y muestra las respuestas llegando a una tabla consultable segundos después.', 'productivity-devtools', '6-12h', 6, 12, 'intermediate', '["no-code","collaboration"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('CI Failure Clusterer that Groups Red Builds by Cause', 'Agrupador de fallos de CI que junta builds rojos por causa', 'Pull a stream of failed CI runs and the tool clusters them by the underlying error signature, so one flaky cause stops looking like fifty separate failures. It ranks clusters by how much developer time each is wasting. The demo ingests a week of red builds and reveals that three error patterns explain most of the noise.', 'Trae un flujo de ejecuciones de CI fallidas y la herramienta las agrupa por la firma de error subyacente, para que una causa inestable deje de parecer cincuenta fallos distintos. Ordena los grupos según cuánto tiempo de desarrollo desperdicia cada uno. La demo ingiere una semana de builds rojos y revela que tres patrones de error explican casi todo el ruido.', 'productivity-devtools', '12-24h', 12, 24, 'advanced', '["testing","automation"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Throwaway Sandbox per Pull Request with a Live URL', 'Sandbox descartable por pull request con URL en vivo', 'Open a pull request and the tool spins up an isolated preview environment with seeded data and hands back a shareable URL, then tears it down when the PR closes. Reviewers click instead of pulling the branch and running it locally. A meatier build whose payoff is letting a non-technical stakeholder try the change before merge.', 'Abre un pull request y la herramienta levanta un entorno de vista previa aislado con datos de semilla y devuelve una URL compartible, luego lo destruye cuando el PR se cierra. Los revisores hacen clic en vez de bajar la rama y correrla local. Un build más sustancioso cuyo premio es dejar que un interesado no técnico pruebe el cambio antes del merge.', 'productivity-devtools', '24-48h', 24, 48, 'advanced', '["automation","collaboration"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Self-Hosted Status Page that Watches Your Own Endpoints', 'Página de estado autoalojada que vigila tus endpoints', 'Define your services in a simple file and the tool probes each endpoint on a schedule, computes uptime, and serves a clean public status page that updates itself. It groups related checks and shows incident history without a paid SaaS. The demo lists three services, knocks one offline, and watches the page flip to a clear degraded state.', 'Define tus servicios en un archivo simple y la herramienta sondea cada endpoint según un calendario, calcula el uptime y sirve una página de estado pública y limpia que se actualiza sola. Agrupa chequeos relacionados y muestra el historial de incidentes sin un SaaS pago. La demo lista tres servicios, deja uno offline y ve la página pasar a un estado degradado claro.', 'productivity-devtools', '12-24h', 12, 24, 'intermediate', '["automation","api-tools"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Glossary Builder that Mines Your Codebase for Jargon', 'Generador de glosario que extrae la jerga de tu código', 'Scan a repo and the tool surfaces the domain terms that appear in names and comments but are never defined anywhere, then drafts a starter glossary entry for each and lets the team confirm definitions. It links each term back to where it''s used. The demo runs on a project and exposes the ten invented words new hires keep asking about.', 'Escanea un repo y la herramienta destaca los términos de dominio que aparecen en nombres y comentarios pero nunca se definen, luego redacta una entrada inicial de glosario para cada uno y deja que el equipo confirme las definiciones. Enlaza cada término a donde se usa. La demo corre sobre un proyecto y expone las diez palabras inventadas que los nuevos siempre preguntan.', 'productivity-devtools', '6-12h', 6, 12, 'intermediate', '["knowledge-mgmt","collaboration"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Load Test Recorder that Replays Your Click Path at Scale', 'Grabador de pruebas de carga que repite tu clic a escala', 'Click through a real user flow once in the browser and the tool records it as a script, then replays it from many simulated users at once while charting where latency cracks. No hand-writing load scripts. The demo records a login-and-checkout path, ramps to a thousand virtual users, and shows the exact step that buckles first.', 'Recorre un flujo de usuario real una vez en el navegador y la herramienta lo graba como script, luego lo reproduce desde muchos usuarios simulados a la vez mientras grafica dónde se quiebra la latencia. Sin escribir scripts de carga a mano. La demo graba un camino de login y pago, escala a mil usuarios virtuales y muestra el paso exacto que cede primero.', 'productivity-devtools', '12-24h', 12, 24, 'advanced', '["testing","automation"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Pomodoro Timer that Auto-Logs Work to the Right Ticket', 'Temporizador Pomodoro que registra el trabajo al ticket justo', 'A focus timer that watches which branch and ticket you''re on, so when a session ends it logs the time against the correct task without you filling a timesheet. It batches the day into a clean summary you can confirm in one click. A small build that quietly solves the time-tracking everyone forgets to do.', 'Un temporizador de foco que observa en qué rama y ticket estás, así cuando termina una sesión registra el tiempo contra la tarea correcta sin que llenes una planilla. Agrupa el día en un resumen limpio que confirmas en un clic. Un build pequeño que resuelve en silencio el registro de tiempo que todos olvidan hacer.', 'productivity-devtools', '3-6h', 3, 6, 'beginner', '["time-mgmt","automation"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Error Budget Tracker that Turns SLOs into a Live Gauge', 'Rastreador de presupuesto de error que vuelve SLOs un medidor', 'Define an availability target and the tool watches your error rate, then shows how much error budget is left this month as a simple gauge that ticks down with every incident. It warns when the burn rate means you''ll blow the budget early. The demo sets a target, replays a spike of errors, and shows the gauge dropping into the danger zone.', 'Define un objetivo de disponibilidad y la herramienta vigila tu tasa de error, luego muestra cuánto presupuesto de error queda este mes como un medidor simple que baja con cada incidente. Avisa cuando el ritmo de consumo implica que agotarás el presupuesto antes de tiempo. La demo fija un objetivo, repite un pico de errores y muestra el medidor cayendo a la zona de peligro.', 'productivity-devtools', '6-12h', 6, 12, 'intermediate', '["automation","api-tools"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Reproducible Bug Capsule from a Single Failing Session', 'Cápsula de bug reproducible desde una sesión que falla', 'When something breaks, hit record and the tool bundles the exact inputs, environment variables, and steps into a portable capsule a teammate can replay verbatim, ending the it-works-on-my-machine standoff. It strips secrets before sharing. The demo captures a crash, sends the capsule to another machine, and reproduces the failure on the first try.', 'Cuando algo se rompe, presionas grabar y la herramienta empaqueta los inputs exactos, las variables de entorno y los pasos en una cápsula portátil que un compañero puede reproducir al pie de la letra, acabando con el clásico funciona-en-mi-máquina. Quita secretos antes de compartir. La demo captura un crash, envía la cápsula a otra máquina y reproduce el fallo al primer intento.', 'productivity-devtools', '24-48h', 24, 48, 'advanced', '["testing","collaboration"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Inline Doc Checker that Flags Comments the Code Outgrew', 'Verificador de docs que marca comentarios que el código superó', 'Scan a repo and the tool finds comments and docstrings that no longer match the code beside them — a parameter that was renamed, a return type that changed, an example that would now throw. It ranks the most misleading ones first. A sharp build that hunts the documentation lies quietly rotting next to working code.', 'Escanea un repo y la herramienta encuentra comentarios y docstrings que ya no concuerdan con el código a su lado — un parámetro renombrado, un tipo de retorno cambiado, un ejemplo que ahora fallaría. Ordena primero los más engañosos. Un build agudo que caza las mentiras de documentación que se pudren en silencio junto al código que funciona.', 'productivity-devtools', '6-12h', 6, 12, 'intermediate', '["knowledge-mgmt","testing"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Drag-and-Drop Scraper that Outputs a Scheduled Feed', 'Scraper de arrastrar y soltar que genera un feed programado', 'Point at a web page, click the elements you want, and the tool builds a scraper visually that runs on a schedule and emits a clean structured feed you can subscribe to. No selectors written by hand, and it warns when a page layout breaks the recipe. The demo turns a listings page into a daily JSON feed in a couple of clicks.', 'Apunta a una página web, haz clic en los elementos que quieres y la herramienta construye un scraper visualmente que corre programado y emite un feed estructurado y limpio al que puedes suscribirte. Sin selectores escritos a mano, y avisa cuando un cambio de diseño rompe la receta. La demo convierte una página de listados en un feed JSON diario en un par de clics.', 'productivity-devtools', '6-12h', 6, 12, 'intermediate', '["no-code","automation"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Keyboard-Only Database Browser for Fast Ad-Hoc Queries', 'Navegador de base de datos por teclado para consultas rápidas', 'A terminal database client built for speed: fuzzy-jump to any table, page through rows, and build filters without touching the mouse or writing full SQL for simple lookups. It remembers your recent queries per database. A focused build for the developer who lives in the keyboard and just wants to peek at a row right now.', 'Un cliente de base de datos en terminal hecho para la velocidad: salta con búsqueda difusa a cualquier tabla, recorre filas y arma filtros sin tocar el mouse ni escribir SQL completo para búsquedas simples. Recuerda tus consultas recientes por base de datos. Un build enfocado para el desarrollador que vive en el teclado y solo quiere espiar una fila ya mismo.', 'productivity-devtools', '12-24h', 12, 24, 'intermediate', '["cli-tools","api-tools"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Incident Timeline Stitcher from Logs, Chats, and Deploys', 'Costurero de cronologías de incidentes desde logs y chats', 'After an outage, point the tool at your logs, deploy records, and chat thread and it merges them into one ordered timeline of what happened when, so the postmortem writes its own first draft. It marks the deploy that lines up with the first error spike. A bigger build that turns scattered incident evidence into a coherent story.', 'Tras una caída, apunta la herramienta a tus logs, registros de despliegue e hilo de chat y los fusiona en una sola cronología ordenada de qué pasó y cuándo, así el postmortem escribe su propio primer borrador. Marca el despliegue que coincide con el primer pico de errores. Un build más grande que convierte evidencia dispersa de incidentes en una historia coherente.', 'productivity-devtools', '24-48h', 24, 48, 'advanced', '["knowledge-mgmt","collaboration"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('API Mock that Mutates State Like a Real Backend', 'Mock de API que muta el estado como un backend real', 'Most mocks return canned responses; this one keeps in-memory state, so a POST actually creates a record a later GET returns, letting you build a whole frontend before the backend exists. You seed initial data and define simple rules per route. The demo wires a UI to the mock and runs a real create-read-update cycle with no server written.', 'La mayoría de los mocks devuelven respuestas enlatadas; este mantiene estado en memoria, así un POST realmente crea un registro que un GET posterior devuelve, dejándote construir todo un frontend antes de que exista el backend. Siembras datos iniciales y defines reglas simples por ruta. La demo conecta una UI al mock y corre un ciclo real de crear-leer-actualizar sin servidor escrito.', 'productivity-devtools', '6-12h', 6, 12, 'intermediate', '["api-tools","testing"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Spaced-Repetition Trainer for Your Team''s Runbooks', 'Entrenador de repetición espaciada para los runbooks del equipo', 'Turn the critical steps of your operational runbooks into short drills the on-call rotation practices on a spaced schedule, so the deploy or rollback steps are muscle memory before a real 3 a.m. page. It tracks who''s rusty on which procedure. A focused build that keeps emergency know-how fresh instead of letting it decay in a wiki.', 'Convierte los pasos críticos de tus runbooks operativos en ejercicios cortos que la rotación de guardia practica en un calendario espaciado, así los pasos de despliegue o rollback son memoria muscular antes de una alerta real a las 3 a.m. Registra quién está oxidado en qué procedimiento. Un build enfocado que mantiene fresco el saber de emergencia en vez de dejarlo decaer en una wiki.', 'productivity-devtools', '6-12h', 6, 12, 'intermediate', '["knowledge-mgmt","collaboration"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Polling-Place Wait-Time Reporter Crowdsourced by Voters', 'Reportero de tiempos de espera en mesas de votacion', 'Voters tap one button on arrival and another when they finish, and the app crowdsources live wait times per polling location onto a map. Late voters can see which nearby site has the shortest line before heading out. The demo shows wait times turning red as fake check-ins pile up, a sharp single-screen civic tool.', 'Los votantes tocan un boton al llegar y otro al terminar, y la app calcula tiempos de espera en vivo por mesa sobre un mapa. Quienes votan tarde pueden ver que lugar cercano tiene la fila mas corta antes de salir. La demo muestra los tiempos volviendose rojos a medida que se acumulan registros, una herramienta civica de una sola pantalla.', 'social-impact', '1-3h', 1, 3, 'beginner', '["civic-tech"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Contrast Checker that Audits a Live Page for Low Vision', 'Verificador de contraste que audita una pagina para baja vision', 'Paste any URL and the tool walks the rendered page, flags every text block that fails contrast ratios for low-vision readers, and proposes the nearest passing color. It overlays a heatmap so a designer sees the worst offenders at a glance. A tight single-feature build that turns an accessibility audit into one click.', 'Pega cualquier URL y la herramienta recorre la pagina renderizada, marca cada bloque de texto que falla los ratios de contraste para personas con baja vision y propone el color valido mas cercano. Superpone un mapa de calor para que el disenador vea los peores casos de un vistazo. Una construccion ajustada que convierte una auditoria de accesibilidad en un clic.', 'social-impact', '1-3h', 1, 3, 'beginner', '["accessibility","civic-tech"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Flashcard Maker that Turns a Textbook Photo into a Quiz Set', 'Generador de tarjetas que convierte la foto de un libro en un examen', 'A student snaps a photo of a textbook page and instantly gets a spaced-repetition deck of question-and-answer cards pulled from the key terms and definitions. It works on any subject and exports to study apps. A focused single-feature build that removes the tedious part of studying for kids without paid tools.', 'Un estudiante saca una foto de la pagina de un libro y obtiene al instante un mazo de repeticion espaciada con tarjetas de pregunta y respuesta extraidas de los terminos y definiciones clave. Funciona con cualquier materia y exporta a apps de estudio. Una construccion enfocada que elimina la parte tediosa de estudiar para chicos sin herramientas pagas.', 'social-impact', '1-3h', 1, 3, 'beginner', '["education"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Reading-Level Meter that Grades Any Public Notice as You Type', 'Medidor de nivel de lectura que califica un aviso publico al escribir', 'A clerk pastes a draft public notice and a live gauge shows the reading grade level, highlighting the exact sentences that push it above what most residents can follow. It suggests simpler swaps for jargon words inline. A sharp single-screen tool that helps agencies write notices everyone can actually read.', 'Un funcionario pega el borrador de un aviso publico y un medidor en vivo muestra el nivel de lectura, resaltando las frases exactas que lo elevan por encima de lo que la mayoria de los vecinos puede seguir. Sugiere reemplazos mas simples para la jerga sobre la marcha. Una herramienta de una pantalla que ayuda a las agencias a escribir avisos que todos puedan leer.', 'social-impact', '1-3h', 1, 3, 'beginner', '["civic-tech","accessibility","language"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Split-the-Bill Tool for Informal Savings Groups Offline', 'Herramienta de division de aportes para grupos de ahorro informales sin conexion', 'Members of a rotating savings club log weekly contributions on a shared phone that works offline, and the tool tracks whose turn it is to receive the pot and who still owes. It prints a clear ledger card so trust stays intact without a bank. A tight build for communities running money circles by hand.', 'Los miembros de un club de ahorro rotativo registran los aportes semanales en un telefono compartido que funciona sin conexion, y la herramienta lleva el control de a quien le toca recibir el fondo y quien todavia debe. Imprime una tarjeta de cuentas clara para que la confianza se mantenga sin banco. Una construccion ajustada para comunidades que manejan circulos de dinero a mano.', 'social-impact', '3-6h', 3, 6, 'beginner', '["finance-inclusion","nonprofit"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Curb-Cut Gap Finder that Spots Missing Ramps from Map Imagery', 'Buscador de rampas faltantes a partir de imagenes de mapas', 'Feed a neighborhood bounding box and the tool scans street-level imagery for intersections that lack curb cuts, then ranks the gaps that strand the most wheelchair routes. City staff get a prioritized punch list with photos attached. The demo lets a judge draw a box on a map and watch missing ramps pin themselves.', 'Ingresa el area de un barrio y la herramienta escanea imagenes a nivel de calle en busca de esquinas sin rampas, y luego ordena las brechas que dejan aisladas a mas rutas en silla de ruedas. El personal municipal recibe una lista priorizada con fotos adjuntas. La demo permite a un juez dibujar un area en un mapa y ver como se marcan las rampas faltantes.', 'social-impact', '6-12h', 6, 12, 'intermediate', '["accessibility","civic-tech"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Tactile Diagram Generator that Prints Charts for Blind Students', 'Generador de diagramas tactiles que imprime graficos para estudiantes ciegos', 'A teacher uploads a chart or simple diagram and the tool converts it into a swell-paper or 3D-printable tactile version with braille labels placed correctly. It keeps proportions so a blind student feels the same trends a sighted peer sees. A meaty build that makes visual science material physically explorable.', 'Un docente sube un grafico o diagrama simple y la herramienta lo convierte en una version tactil para papel termico o impresion 3D con etiquetas en braille bien ubicadas. Mantiene las proporciones para que un estudiante ciego sienta las mismas tendencias que ve un companero vidente. Una construccion sustancial que hace explorable fisicamente el material cientifico visual.', 'social-impact', '6-12h', 6, 12, 'intermediate', '["accessibility","education"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Rumor-Tracker Dashboard for Crisis Misinformation in Real Time', 'Panel de rumores para desinformacion en crisis en tiempo real', 'During a disaster the tool clusters incoming social posts into distinct rumors, ranks each by spread and potential harm, and lets responders mark which ones to debunk first. A timeline shows a false evacuation claim ballooning before it is corrected. The demo replays a real crisis feed and watches dangerous rumors rise to the top.', 'Durante un desastre la herramienta agrupa las publicaciones entrantes en rumores distintos, los ordena por difusion y dano potencial, y permite a los equipos marcar cuales desmentir primero. Una linea de tiempo muestra una falsa alerta de evacuacion creciendo antes de ser corregida. La demo reproduce un feed real de crisis y ve subir los rumores peligrosos.', 'social-impact', '6-12h', 6, 12, 'intermediate', '["disaster-response","civic-tech"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Grant-Deadline Radar that Surfaces Funding a Nonprofit Qualifies For', 'Radar de fechas de subvenciones que muestra fondos para los que una ONG califica', 'A small nonprofit enters its mission, size, and region, and the tool scans open grant calls to surface only the ones it actually qualifies for, sorted by deadline. It flags eligibility deal-breakers up front so no time is wasted. The demo profiles a fake food bank and watches matching grants populate a countdown board.', 'Una ONG pequena ingresa su mision, tamano y region, y la herramienta escanea convocatorias abiertas para mostrar solo aquellas para las que realmente califica, ordenadas por fecha limite. Marca de entrada los requisitos excluyentes para no perder tiempo. La demo perfila un banco de alimentos ficticio y ve poblarse un tablero de cuenta regresiva con subvenciones compatibles.', 'social-impact', '6-12h', 6, 12, 'intermediate', '["nonprofit","finance-inclusion"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Pronunciation Coach that Scores a Heritage Learner Word by Word', 'Entrenador de pronunciacion que califica a un hablante de herencia palabra por palabra', 'A heritage-language learner reads a phrase aloud and the tool scores each word against a native model, highlighting the exact sounds that drifted and looping just those. It builds short drills from the words a learner keeps missing. The demo has someone speak a sentence and watch the weak syllables light up instantly.', 'Un aprendiz de lengua de herencia lee una frase en voz alta y la herramienta califica cada palabra contra un modelo nativo, resaltando los sonidos exactos que se desviaron y repitiendo solo esos. Arma ejercicios cortos con las palabras que el aprendiz sigue fallando. La demo hace que alguien diga una oracion y vea encenderse las silabas debiles al instante.', 'social-impact', '6-12h', 6, 12, 'intermediate', '["language","education","accessibility"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Medication-Conflict Checker for Caregivers of Multiple Elders', 'Verificador de interacciones para cuidadores de varios adultos mayores', 'A caregiver photographs the pill bottles for each elder they help, and the tool builds a per-person schedule while flagging dangerous drug interactions across the whole list. It generates a large-print daily card that anyone can follow. The demo scans a messy pile of bottles and surfaces a hidden conflict the family missed.', 'Un cuidador fotografia los frascos de pastillas de cada adulto mayor que atiende, y la herramienta arma un cronograma por persona mientras marca interacciones peligrosas en toda la lista. Genera una tarjeta diaria en letra grande que cualquiera puede seguir. La demo escanea una pila desordenada de frascos y revela un conflicto oculto que la familia no habia visto.', 'social-impact', '6-12h', 6, 12, 'intermediate', '["elderly","accessibility"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Lost-Pet and Person Flyer Maker that Geo-Targets a Neighborhood', 'Creador de carteles de personas o mascotas perdidas con geolocalizacion barrial', 'In a crisis or everyday emergency, someone fills a short form and the tool generates a clean printable flyer plus a shareable card that auto-targets the surrounding blocks. Sightings flow back onto a private map for the searcher. A focused build that turns a panicked moment into an organized, local search effort.', 'En una crisis o emergencia cotidiana, alguien completa un formulario corto y la herramienta genera un cartel imprimible prolijo mas una tarjeta para compartir que apunta automaticamente a las cuadras cercanas. Los avistamientos vuelven a un mapa privado para quien busca. Una construccion enfocada que convierte un momento de panico en una busqueda local organizada.', 'social-impact', '3-6h', 3, 6, 'intermediate', '["disaster-response","civic-tech"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Sliding-Scale Calculator that Sets Fair Clinic Fees by Income', 'Calculadora de escala movil para tarifas justas de clinica segun ingresos', 'A community clinic enters its cost floor and a patient answers a few private questions about household income and size, and the tool returns a fair sliding-scale fee plus which subsidies might cover the rest. It keeps the math transparent so patients trust the number. A tight build that removes guesswork from charitable pricing.', 'Una clinica comunitaria ingresa su costo minimo y un paciente responde unas pocas preguntas privadas sobre ingresos y tamano del hogar, y la herramienta devuelve una tarifa justa de escala movil mas que subsidios podrian cubrir el resto. Mantiene las cuentas transparentes para que el paciente confie en el numero. Una construccion ajustada que quita la incertidumbre del precio solidario.', 'social-impact', '3-6h', 3, 6, 'beginner', '["finance-inclusion","nonprofit"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Read-Aloud Reformatter that Tames Cluttered Pages for Dyslexia', 'Reformateador de lectura que ordena paginas recargadas para dislexia', 'Paste a URL or article and the tool strips clutter, reflows text into a dyslexia-friendly font and spacing, and reads it aloud while highlighting each word in sync. Readers tune line length and color overlays to what suits them. A sharp single-screen build that makes dense web text approachable for struggling readers.', 'Pega una URL o articulo y la herramienta elimina el desorden, reacomoda el texto en una fuente y espaciado amigables para la dislexia, y lo lee en voz alta resaltando cada palabra en sincronia. El lector ajusta el largo de linea y los filtros de color a su gusto. Una construccion de una pantalla que hace accesible el texto web denso para lectores con dificultades.', 'social-impact', '3-6h', 3, 6, 'intermediate', '["accessibility","education"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Damage-Photo Sorter that Triages Crowd Reports After a Storm', 'Clasificador de fotos de danos que prioriza reportes tras una tormenta', 'Residents upload photos of storm damage and the tool tags severity, pins each to a map, and clusters the hardest-hit blocks so crews go where need is greatest first. Duplicate reports of the same site get merged automatically. The demo feeds a batch of mixed photos and watches a priority map self-assemble.', 'Los vecinos suben fotos de los danos de una tormenta y la herramienta etiqueta la gravedad, las ubica en un mapa y agrupa las cuadras mas afectadas para que las cuadrillas vayan primero donde mas se necesita. Los reportes duplicados del mismo lugar se fusionan automaticamente. La demo carga un lote de fotos mezcladas y ve armarse solo un mapa de prioridades.', 'social-impact', '6-12h', 6, 12, 'intermediate', '["disaster-response","civic-tech"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Translation Relay that Links a Patient to a Volunteer Interpreter', 'Relevo de traduccion que conecta a un paciente con un interprete voluntario', 'When a patient and clinician do not share a language, the tool instantly pages an available volunteer interpreter for that exact language pair and bridges them by voice in seconds. It falls back to machine translation while a human connects. A demoable build that turns a frantic search for an interpreter into one tap.', 'Cuando un paciente y un medico no comparten idioma, la herramienta convoca al instante a un interprete voluntario disponible para ese par exacto de lenguas y los une por voz en segundos. Recurre a la traduccion automatica mientras se conecta una persona. Una construccion demostrable que convierte la busqueda desesperada de un interprete en un solo toque.', 'social-impact', '12-24h', 12, 24, 'intermediate', '["language","accessibility","nonprofit"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Tutor-Match Scheduler that Pairs Volunteers to Students by Gap', 'Agenda de tutorias que empareja voluntarios con estudiantes por brecha', 'Students list the topics they are stuck on and volunteers list what they can teach plus their free hours, and the tool proposes weekly pairings that maximize coverage of the worst gaps. It auto-fills calendar invites and tracks attendance. A solid build that turns scattered goodwill into a reliable tutoring schedule.', 'Los estudiantes listan los temas en los que estan trabados y los voluntarios listan que pueden ensenar y sus horas libres, y la herramienta propone emparejamientos semanales que maximizan la cobertura de las peores brechas. Completa invitaciones de calendario y registra la asistencia. Una construccion solida que convierte la buena voluntad dispersa en un cronograma de tutorias confiable.', 'social-impact', '12-24h', 12, 24, 'intermediate', '["education","nonprofit"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Eviction-Notice Decoder that Maps Out a Tenant''s Next Steps', 'Decodificador de avisos de desalojo que traza los pasos del inquilino', 'A tenant photographs an eviction or rent notice and the tool extracts the key dates, explains what each one means in plain language, and lays out a personalized timeline of deadlines and options. It surfaces local legal-aid contacts for each step. A focused build that turns a terrifying letter into a clear plan of action.', 'Un inquilino fotografia un aviso de desalojo o de alquiler y la herramienta extrae las fechas clave, explica que significa cada una en lenguaje simple y traza una linea de tiempo personalizada de plazos y opciones. Muestra contactos locales de asistencia legal para cada paso. Una construccion enfocada que convierte una carta aterradora en un plan de accion claro.', 'social-impact', '6-12h', 6, 12, 'intermediate', '["civic-tech","accessibility","language"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Budget-Coaching Game that Teaches Saving on a Tight Income', 'Juego de coaching de presupuesto que ensena a ahorrar con ingresos ajustados', 'A short interactive game drops the player into realistic month scenarios on a low income, where every choice about rent, food, and surprise bills shows the ripple effect on savings. It coaches gentle strategies after each round. A demoable build that teaches budgeting through felt consequences instead of dry advice.', 'Un juego interactivo corto pone al jugador en escenarios realistas de un mes con bajos ingresos, donde cada decision sobre alquiler, comida y gastos imprevistos muestra el efecto domino en los ahorros. Aconseja estrategias suaves despues de cada ronda. Una construccion demostrable que ensena a presupuestar mediante consecuencias sentidas en lugar de consejos aridos.', 'social-impact', '6-12h', 6, 12, 'beginner', '["finance-inclusion","education"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Public-Comment Summarizer that Clusters Thousands of Citizen Notes', 'Resumidor de comentarios publicos que agrupa miles de notas ciudadanas', 'Drop in a pile of public comments on a proposed rule and the tool clusters them into the main themes, counts how many people share each concern, and pulls a representative quote per cluster. Officials see the public''s real priorities without reading every note. The demo ingests a comment dump and renders an instant theme map.', 'Carga una pila de comentarios publicos sobre una norma propuesta y la herramienta los agrupa en los temas principales, cuenta cuanta gente comparte cada preocupacion y extrae una cita representativa por grupo. Los funcionarios ven las prioridades reales del publico sin leer cada nota. La demo ingiere un volcado de comentarios y muestra al instante un mapa de temas.', 'social-impact', '12-24h', 12, 24, 'advanced', '["civic-tech","nonprofit"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Sign-Language Story Player that Animates Books for Deaf Kids', 'Reproductor de cuentos en lengua de senas que anima libros para ninos sordos', 'A parent picks a children''s book and the tool plays it as an animated avatar signing each page in sync with highlighted text, so a deaf child can follow the story in their first language. Pacing slows on request for early readers. A meaty build that brings bedtime stories to kids print alone leaves behind.', 'Un padre elige un libro infantil y la herramienta lo reproduce con un avatar animado que senala cada pagina en sincronia con el texto resaltado, para que un nino sordo siga la historia en su primera lengua. El ritmo se ralentiza a pedido para lectores iniciales. Una construccion sustancial que acerca los cuentos para dormir a los ninos que el texto solo deja atras.', 'social-impact', '12-24h', 12, 24, 'advanced', '["accessibility","education","language"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Heat-Risk Caller that Checks On Isolated Elders During a Wave', 'Llamador de riesgo por calor que controla a adultos mayores aislados en una ola', 'When a heat wave hits, the tool auto-calls enrolled isolated elders with a simple wellness check, escalates to family or a volunteer if someone does not answer, and logs who still needs help. Operators see a live board of who is safe and who is unreachable. A build that turns a deadly heat event into an organized care sweep.', 'Cuando llega una ola de calor, la herramienta llama automaticamente a adultos mayores aislados inscritos con un chequeo simple de bienestar, escala a la familia o a un voluntario si alguien no responde, y registra quien aun necesita ayuda. Los operadores ven un tablero en vivo de quien esta a salvo y quien es inubicable. Una construccion que convierte un evento mortal de calor en un barrido de cuidado organizado.', 'social-impact', '12-24h', 12, 24, 'intermediate', '["elderly","disaster-response"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Skill-Swap Board that Trades Help Without Any Money Changing Hands', 'Tablero de intercambio de habilidades sin que circule dinero', 'Neighbors post a skill they can give and one they need, and the tool finds time-banking chains so a haircut pays for a tutoring hour that pays for a repair. Everyone earns and spends time credits instead of cash. A solid build that lets a community without spare money still trade real value.', 'Los vecinos publican una habilidad que pueden dar y otra que necesitan, y la herramienta encuentra cadenas de banco de tiempo para que un corte de pelo pague una hora de tutoria que paga una reparacion. Todos ganan y gastan creditos de tiempo en lugar de efectivo. Una construccion solida que permite a una comunidad sin dinero extra intercambiar valor real.', 'social-impact', '12-24h', 12, 24, 'intermediate', '["finance-inclusion","nonprofit","civic-tech"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Allergen and Ingredient Reader that Speaks Labels for Low Literacy', 'Lector de ingredientes que dice las etiquetas para baja alfabetizacion', 'A shopper points a phone at any packaged-food label and the tool reads it aloud in their language, calling out the allergens they flagged and rating how processed the item is. It works on tiny print that low-vision and low-literacy shoppers struggle with. A sharp build that makes the grocery aisle safe to navigate by voice.', 'Un comprador apunta el telefono a la etiqueta de cualquier alimento envasado y la herramienta la lee en voz alta en su idioma, avisando de los alergenos que marco y calificando cuan procesado es el producto. Funciona sobre la letra diminuta que cuesta a personas con baja vision y baja alfabetizacion. Una construccion ajustada que vuelve seguro recorrer el supermercado por voz.', 'social-impact', '3-6h', 3, 6, 'intermediate', '["accessibility","language"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Open-Records Request Builder that Drafts the Right FOIA Letter', 'Generador de pedidos de acceso que redacta la carta de informacion publica correcta', 'A resident describes the records they want and the tool drafts a properly worded public-records request aimed at the correct agency, with the legal citations and fee-waiver language that get results. It tracks deadlines and nudges follow-ups. A focused build that puts a journalist-grade transparency tool in anyone''s hands.', 'Un vecino describe los registros que quiere y la herramienta redacta un pedido de informacion publica bien formulado dirigido a la agencia correcta, con las citas legales y el lenguaje de exencion de tarifas que dan resultado. Lleva el control de los plazos y recuerda los seguimientos. Una construccion enfocada que pone una herramienta de transparencia de nivel periodistico en manos de cualquiera.', 'social-impact', '3-6h', 3, 6, 'intermediate', '["civic-tech","language"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Quiet-Hours Map that Shows Sensory-Friendly Times at Public Places', 'Mapa de horarios tranquilos en lugares publicos sensorialmente amigables', 'Families of autistic or sensory-sensitive members search a map for shops, clinics, and museums by how loud and bright they are at each hour, crowdsourced from quick visitor ratings. It flags official sensory-friendly hours too. A build that lets people plan outings around the calm windows instead of dreading the chaos.', 'Las familias de personas autistas o sensorialmente sensibles buscan en un mapa comercios, clinicas y museos segun cuan ruidosos y luminosos son a cada hora, con datos aportados por calificaciones rapidas de visitantes. Tambien marca los horarios oficiales sensorialmente amigables. Una construccion que permite planear salidas en las ventanas de calma en lugar de temer al caos.', 'social-impact', '6-12h', 6, 12, 'intermediate', '["accessibility","civic-tech"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Refugee Credential Mapper that Matches Foreign Degrees to Local Jobs', 'Mapeador de credenciales que vincula titulos extranjeros con empleos locales', 'A newcomer enters their foreign degree, license, and work history, and the tool maps it to the closest locally recognized equivalents plus the exact steps to validate each one. It surfaces jobs they can already do while credentials process. A meaty build that keeps skilled refugees from being stuck below their training.', 'Un recien llegado ingresa su titulo extranjero, matricula e historial laboral, y la herramienta lo vincula con los equivalentes reconocidos localmente mas cercanos y los pasos exactos para validar cada uno. Muestra empleos que ya puede ejercer mientras se procesan las credenciales. Una construccion sustancial que evita que refugiados calificados queden atrapados por debajo de su formacion.', 'social-impact', '12-24h', 12, 24, 'intermediate', '["finance-inclusion","language","nonprofit"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Shelter-Capacity Beacon that Broadcasts Open Beds to Outreach Teams', 'Baliza de capacidad de refugios que difunde camas libres a equipos de calle', 'Shelters update open beds with one tap and street-outreach workers see a live map of where someone can sleep tonight, filtered by needs like family, pets, or accessibility. A bed is held the moment a worker claims it. A demoable build that ends the cold-night phone-tag of finding a free bed.', 'Los refugios actualizan las camas libres con un toque y los trabajadores de calle ven un mapa en vivo de donde alguien puede dormir esta noche, filtrado por necesidades como familia, mascotas o accesibilidad. Una cama queda reservada en el momento en que un trabajador la toma. Una construccion demostrable que termina con las llamadas interminables para encontrar una cama libre en una noche fria.', 'social-impact', '12-24h', 12, 24, 'intermediate', '["nonprofit","disaster-response","civic-tech"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Math-Anxiety Tutor that Slows Down and Praises Each Small Win', 'Tutor de ansiedad matematica que va despacio y celebra cada pequeno logro', 'A learner who freezes at math works one tiny step at a time, with the tutor detecting frustration from pace and errors, then easing difficulty and naming each small win to rebuild confidence. It never moves on until a step feels solid. A build aimed at the emotional barrier, not just the content.', 'Un estudiante que se bloquea con la matematica trabaja un pequeno paso por vez, mientras el tutor detecta la frustracion por el ritmo y los errores, baja la dificultad y nombra cada pequeno logro para reconstruir la confianza. Nunca avanza hasta que un paso se siente firme. Una construccion dirigida a la barrera emocional, no solo al contenido.', 'social-impact', '6-12h', 6, 12, 'intermediate', '["education","accessibility"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Disaster-Day Phrasebook that Pre-Loads Survival Lines Offline', 'Frasario de desastres que precarga frases de supervivencia sin conexion', 'Before connectivity drops, the tool pre-downloads a two-way phrasebook of survival sentences between local and responder languages, with audio so anyone can play the right line to be understood. It covers injuries, water, and shelter needs. A sharp build that keeps language from being a wall when networks and time are gone.', 'Antes de que se caiga la conectividad, la herramienta predescarga un frasario bidireccional de frases de supervivencia entre el idioma local y el de los rescatistas, con audio para que cualquiera reproduzca la frase correcta y se haga entender. Cubre lesiones, agua y necesidades de refugio. Una construccion ajustada que evita que el idioma sea un muro cuando ya no hay redes ni tiempo.', 'social-impact', '3-6h', 3, 6, 'beginner', '["disaster-response","language","accessibility"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Participatory-Budget Simulator that Lets Residents Spend the City Pot', 'Simulador de presupuesto participativo para que los vecinos repartan el fondo', 'Residents drag a fixed city budget across competing projects and instantly see trade-offs, like funding a park means cutting bus frequency. Aggregated choices show officials what the community actually prioritizes. The demo hands a judge a slider board and watches the collective spending plan take shape in real time.', 'Los vecinos reparten un presupuesto municipal fijo entre proyectos en competencia y ven al instante las disyuntivas, como que financiar un parque implica recortar la frecuencia del colectivo. Las elecciones agregadas muestran a los funcionarios que prioriza realmente la comunidad. La demo entrega a un juez un tablero de controles y ve formarse en vivo el plan de gasto colectivo.', 'social-impact', '6-12h', 6, 12, 'intermediate', '["civic-tech","education"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Caption Quality Grader that Catches Broken Auto-Captions in Class', 'Calificador de subtitulos que detecta subtitulos automaticos rotos en clase', 'A deaf or hard-of-hearing student runs a recorded lecture through the tool, which scores the auto-captions for accuracy, flags the garbled segments, and lets a volunteer fix only those lines. It builds a corrected transcript fast. A build that closes the gap between cheap auto-captions and ones a student can actually learn from.', 'Un estudiante sordo o con dificultades auditivas pasa una clase grabada por la herramienta, que califica la precision de los subtitulos automaticos, marca los segmentos confusos y permite a un voluntario corregir solo esas lineas. Arma una transcripcion corregida rapido. Una construccion que cierra la brecha entre los subtitulos automaticos baratos y unos de los que un estudiante realmente pueda aprender.', 'social-impact', '6-12h', 6, 12, 'intermediate', '["accessibility","education"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Bus-Stop Voice Guide that Announces Arrivals for Blind Riders', 'Guia de voz en paradas que anuncia llegadas para pasajeros ciegos', 'A blind rider at a stop holds up their phone and the tool tells them which routes serve this stop, how many minutes until each, and which door to board, all by voice from open transit feeds. It vibrates a pattern as the bus nears. A focused build that makes catching the right bus possible without sight.', 'Un pasajero ciego en una parada levanta su telefono y la herramienta le dice por voz que rutas pasan por esa parada, cuantos minutos faltan para cada una y por que puerta subir, todo a partir de feeds abiertos de transporte. Vibra con un patron cuando el colectivo se acerca. Una construccion enfocada que hace posible tomar el colectivo correcto sin vision.', 'social-impact', '6-12h', 6, 12, 'intermediate', '["accessibility","civic-tech"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Donation-in-Kind Router that Sends Each Item Where It Is Needed', 'Enrutador de donaciones en especie que envia cada objeto donde se necesita', 'Donors photograph items they want to give and the tool matches each one to the nearest charity that currently needs exactly that, preventing useless piles of unwanted goods. It schedules pickup or drop-off and tracks what was actually used. A solid build that fixes the chronic mismatch between in-kind donations and real need.', 'Los donantes fotografian los objetos que quieren entregar y la herramienta empareja cada uno con la organizacion mas cercana que ahora mismo necesita exactamente eso, evitando pilas inutiles de cosas no deseadas. Programa el retiro o la entrega y registra que se uso realmente. Una construccion solida que corrige el desajuste cronico entre las donaciones en especie y la necesidad real.', 'social-impact', '12-24h', 12, 24, 'intermediate', '["nonprofit","disaster-response"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Citywide Accessibility Audit Platform Built in a Weekend', 'Plataforma de auditoria de accesibilidad de toda la ciudad armada en un fin de semana', 'Volunteers walk routes logging barriers like broken ramps, blocked sidewalks, and missing tactile paving, and the platform fuses their reports into a citywide accessibility score with a heatmap and a prioritized fix list for officials. It assigns walking routes to avoid overlap. A fuller two-day build spanning data capture, scoring, and a public dashboard.', 'Los voluntarios recorren rutas registrando barreras como rampas rotas, veredas bloqueadas y falta de pavimento tactil, y la plataforma fusiona sus reportes en un puntaje de accesibilidad de toda la ciudad con un mapa de calor y una lista priorizada de arreglos para los funcionarios. Asigna rutas para evitar superposiciones. Una construccion mas completa de dos dias que abarca captura de datos, puntaje y un panel publico.', 'social-impact', '24-48h', 24, 48, 'advanced', '["accessibility","civic-tech","nonprofit"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('End-to-End Disaster Coordination Hub for a Whole Community', 'Centro integral de coordinacion de desastres para toda una comunidad', 'A full weekend build that ties together resident SOS reports, volunteer dispatch, resource inventory, and a public status map into one disaster hub that keeps working as connectivity flickers. Coordinators assign tasks, track who is helping where, and broadcast verified updates. The depth and many moving parts justify a 48-hour-plus effort.', 'Una construccion de fin de semana completo que une los reportes de SOS de vecinos, el despacho de voluntarios, el inventario de recursos y un mapa publico de estado en un solo centro de desastres que sigue funcionando mientras la conectividad falla. Los coordinadores asignan tareas, controlan quien ayuda donde y difunden actualizaciones verificadas. La profundidad y las muchas partes moviles justifican un esfuerzo de mas de 48 horas.', 'social-impact', '48h+', 48, 72, 'advanced', '["disaster-response","civic-tech","nonprofit"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Prompt Linter Extension that Rates Your AI Prompts Live', 'Extensión que califica tus prompts de IA en vivo', 'A browser extension that sits beside any chat box and scores your prompt as you type, flagging vague verbs, missing context, and conflicting instructions, then suggests one concrete rewrite. The whole charm is the live meter that nudges you before you hit send. A focused single-panel build for a short sprint.', 'Una extensión de navegador que se ubica junto a cualquier cuadro de chat y puntúa tu prompt mientras escribís, marcando verbos vagos, contexto faltante e instrucciones contradictorias, y sugiere una reescritura concreta. Su gracia es el medidor en vivo que te avisa antes de enviar. Un proyecto enfocado de un solo panel para un sprint corto.', 'web-frontend', '3-6h', 3, 6, 'intermediate', '["browser-extension","ui-tooling"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Focus Mode Overlay that Greys Out Everything But One Block', 'Modo enfoque que atenúa todo menos un bloque', 'A browser extension that lets you click any paragraph, form, or card on a page and dims the rest of the screen around it, following your reading down the page like a spotlight. It kills visual noise on cluttered sites without breaking the layout. A tight, demoable single-feature build for a half-day.', 'Una extensión que te deja hacer clic en cualquier párrafo, formulario o tarjeta de una página y atenúa el resto de la pantalla a su alrededor, siguiendo tu lectura como un foco de luz. Elimina el ruido visual en sitios recargados sin romper el diseño. Un proyecto compacto y demostrable de una sola función para medio día.', 'web-frontend', '1-3h', 1, 3, 'beginner', '["browser-extension","accessibility"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Sankey Builder that Traces Money Flow from a Pasted Ledger', 'Generador Sankey que traza el flujo de dinero de un libro', 'Paste rows of from-to-amount transactions and the tool renders an animated Sankey diagram of where the money moves, with hovers that isolate any single path and totals that update as you filter. The demo turns a boring spreadsheet into a story of flows in seconds. A sharp dataviz build for an evening.', 'Pegá filas de transacciones de origen-destino-monto y la herramienta genera un diagrama Sankey animado de hacia dónde se mueve el dinero, con resaltados que aíslan cualquier ruta y totales que se actualizan al filtrar. La demo convierte una planilla aburrida en una historia de flujos en segundos. Un proyecto de visualización filoso para una tarde.', 'web-frontend', '3-6h', 3, 6, 'intermediate', '["dataviz","animation"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Tab Group Auto-Sorter that Clusters Open Tabs by Topic', 'Organizador de pestañas que las agrupa por tema', 'A browser extension that reads the titles of your open tabs and silently clusters them into labelled groups by topic, so a chaotic window of forty tabs becomes a tidy set of stacks you can collapse. The hook is one keystroke that tidies the mess instantly. A satisfying, demoable build for a short sprint.', 'Una extensión que lee los títulos de tus pestañas abiertas y las agrupa silenciosamente por tema en grupos etiquetados, de modo que una ventana caótica de cuarenta pestañas se vuelve un conjunto ordenado y plegable. El gancho es una tecla que ordena el desastre al instante. Un proyecto satisfactorio y demostrable para un sprint corto.', 'web-frontend', '3-6h', 3, 6, 'intermediate', '["browser-extension","ui-tooling"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Live Form Validation Playground with Shareable Rule Sets', 'Laboratorio de validación de formularios con reglas compartibles', 'A sandbox where you sketch a form, attach validation rules from a visual list, and watch every field react in real time as you type test values, with the failing path highlighted. Export the rules as a snippet or a shareable link. A clean UI-tooling build that makes invisible logic visible for a half-day sprint.', 'Un laboratorio donde dibujás un formulario, le agregás reglas de validación desde una lista visual y ves cada campo reaccionar en tiempo real mientras escribís valores de prueba, con la ruta que falla resaltada. Exportá las reglas como fragmento o enlace compartible. Un proyecto de herramientas de UI que hace visible la lógica invisible para medio día.', 'web-frontend', '3-6h', 3, 6, 'intermediate', '["ui-tooling","real-time"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Spectator Esports HUD that Renders a Match Replay Log', 'HUD de espectador que renderiza el log de una partida', 'Drop in a JSON event log from a game match and the tool plays it back as a living HUD: a timeline scrubber, kill feed, and a heat trail of player positions on the map that you can rewind and pause. The demo lets a judge scrub to any moment and watch the action redraw. A juicy game-UI build for a day.', 'Cargá un log de eventos JSON de una partida y la herramienta lo reproduce como un HUD vivo: una línea de tiempo navegable, un feed de bajas y un rastro de calor de las posiciones de los jugadores que podés rebobinar y pausar. La demo deja a un juez saltar a cualquier momento y ver la acción redibujarse. Un atractivo proyecto de UI de juegos para un día.', 'web-frontend', '6-12h', 6, 12, 'intermediate', '["game-ui","dataviz","animation"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Screen Reader Preview Pane that Speaks Your Page as Built', 'Panel que lee tu página como un lector de pantalla', 'A dev tool that renders a live preview of how a screen reader would announce your page, listing the heading tree, landmarks, and the exact spoken order, with a play button that reads it aloud. It surfaces skipped headings and unlabelled buttons inline. A genuinely useful accessibility build for an evening sprint.', 'Una herramienta para desarrolladores que muestra una vista previa en vivo de cómo un lector de pantalla anunciaría tu página, listando el árbol de encabezados, las regiones y el orden hablado exacto, con un botón que lo lee en voz alta. Detecta encabezados salteados y botones sin etiqueta en línea. Un proyecto de accesibilidad genuinamente útil para una tarde.', 'web-frontend', '6-12h', 6, 12, 'intermediate', '["accessibility","ui-tooling"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Shared Cursor Pictionary that Two Browsers Play Side by Side', 'Pictionary de cursores que dos navegadores juegan juntos', 'A real-time party game where one player draws with their cursor on a shared canvas while the other guesses the word in a live chat, with a round timer and a reveal animation. Join by sharing a link, no install. The hook is the instant two-tab demo that feels alive. A fun real-time build for an evening.', 'Un juego de fiesta en tiempo real donde un jugador dibuja con su cursor en un lienzo compartido mientras el otro adivina la palabra en un chat en vivo, con temporizador de ronda y una animación de revelación. Se une compartiendo un enlace, sin instalar. El gancho es la demo instantánea de dos pestañas que se siente viva. Un proyecto divertido en tiempo real para una tarde.', 'web-frontend', '6-12h', 6, 12, 'intermediate', '["real-time","game-ui"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Animated Tournament Bracket that Fills In as Scores Arrive', 'Llave de torneo animada que se llena con los resultados', 'A live bracket view where typing a match result animates the winner sliding up to the next round, with confetti on the final and a replay button that walks the whole tournament forward. Built for screens at a game night or a real event. A snappy game-UI build with a satisfying demo for a half-day.', 'Una vista de llave en vivo donde escribir un resultado anima al ganador deslizándose a la siguiente ronda, con confeti en la final y un botón de repetición que recorre todo el torneo hacia adelante. Pensado para pantallas en una noche de juegos o un evento real. Un ágil proyecto de UI de juegos con una demo satisfactoria para medio día.', 'web-frontend', '3-6h', 3, 6, 'beginner', '["game-ui","animation","real-time"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Reaction-Time Trainer that Charts Your Reflexes Over Days', 'Entrenador de reflejos que grafica tu reacción por días', 'A PWA mini-game that drills your reaction time with quick visual prompts, then stores every run offline and charts how your reflexes trend across days and times of day. The hook is the personal curve that proves you are faster after coffee. A clean offline build that works on a flaky connection for an evening.', 'Un mini-juego PWA que entrena tu tiempo de reacción con estímulos visuales rápidos, guarda cada intento sin conexión y grafica cómo evolucionan tus reflejos según el día y la hora. El gancho es la curva personal que demuestra que sos más rápido después del café. Un proyecto offline limpio que funciona con conexión inestable para una tarde.', 'web-frontend', '6-12h', 6, 12, 'intermediate', '["pwa","dataviz","game-ui"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Focus Trap Visualizer that Maps Tab Order as a Flow Arrow', 'Visualizador de orden de tabulación como flecha de flujo', 'A dev overlay that draws a numbered arrow path through every focusable element on a page in tab order, so you can see at a glance where keyboard focus jumps, loops, or escapes a modal. Click any node to jump there. A precise accessibility tool whose demo instantly reveals a broken modal in a half-day.', 'Una capa para desarrolladores que dibuja una flecha numerada a través de cada elemento enfocable de una página en orden de tabulación, para ver de un vistazo dónde salta, gira o escapa el foco de un modal. Hacé clic en cualquier nodo para ir ahí. Una herramienta de accesibilidad precisa cuya demo revela un modal roto al instante en medio día.', 'web-frontend', '3-6h', 3, 6, 'intermediate', '["accessibility","dataviz","ui-tooling"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Pixel-Art Editor in the Browser that Exports Sprite Sheets', 'Editor de pixel art en el navegador que exporta sprites', 'A grid-based pixel editor with frames, an onion-skin preview, and a play button that animates your sprite, then exports a packed sprite sheet plus the CSS to run it. The hook is watching your character walk the moment you draw the second frame. A delightful game-UI build for an evening sprint.', 'Un editor de píxeles basado en grilla con fotogramas, vista de papel cebolla y un botón de reproducción que anima tu sprite, y luego exporta una hoja de sprites compacta junto con el CSS para usarla. El gancho es ver a tu personaje caminar en cuanto dibujás el segundo fotograma. Un encantador proyecto de UI de juegos para una tarde.', 'web-frontend', '6-12h', 6, 12, 'intermediate', '["game-ui","animation","ui-tooling"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Live Captions Overlay that Subtitles Any Browser Tab Audio', 'Capa de subtítulos en vivo para el audio de cualquier pestaña', 'A browser extension that captures the audio of the current tab and renders live captions in a movable, resizable bar over the page, so a video without subtitles becomes readable. Captions stay legible with adjustable size and contrast. A high-impact accessibility build that demos instantly on any clip in a day.', 'Una extensión que captura el audio de la pestaña actual y muestra subtítulos en vivo en una barra móvil y redimensionable sobre la página, de modo que un video sin subtítulos se vuelve legible. Los subtítulos se mantienen claros con tamaño y contraste ajustables. Un proyecto de accesibilidad de alto impacto que se demuestra al instante en cualquier clip en un día.', 'web-frontend', '6-12h', 6, 12, 'advanced', '["browser-extension","accessibility","real-time"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Calendar Heatmap Generator from a Pasted Date Column', 'Generador de mapa de calor de calendario desde fechas', 'Paste a column of dates and counts and the tool renders a GitHub-style year heatmap you can recolor, tooltip, and export as an image or embed snippet. Hover any cell to see the day''s total and streaks light up. A tight, genuinely reusable dataviz build that fits a short evening sprint.', 'Pegá una columna de fechas y conteos y la herramienta genera un mapa de calor anual estilo GitHub que podés recolorear, con tooltips, y exportar como imagen o fragmento para incrustar. Pasá el cursor por cualquier celda para ver el total del día y se iluminan las rachas. Un proyecto de visualización compacto y reutilizable que entra en una tarde corta.', 'web-frontend', '1-3h', 1, 3, 'beginner', '["dataviz","ui-tooling"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Multiplayer Quiz Buzzer where Phones Race to Press First', 'Pulsador de quiz donde los teléfonos compiten por presionar', 'A real-time buzzer system for trivia nights: the host shows a question on the big screen and players race to tap their phone, with the first buzz locking the board and a sound cue. No app, just a shared link. The hook is the live race and the instant lockout. A lively real-time build for a half-day sprint.', 'Un sistema de pulsadores en tiempo real para noches de trivia: el anfitrión muestra una pregunta en la pantalla grande y los jugadores compiten por tocar su teléfono, y el primer pulso bloquea el tablero con un aviso sonoro. Sin app, solo un enlace compartido. El gancho es la carrera en vivo y el bloqueo instantáneo. Un proyecto en tiempo real animado para medio día.', 'web-frontend', '3-6h', 3, 6, 'intermediate', '["real-time","game-ui"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Motion Reducer that Tames Aggressive Animations on Any Site', 'Reductor de movimiento que calma animaciones agresivas', 'A browser extension that detects parallax, auto-playing carousels, and jittery scroll effects on a page and lets you slow or freeze them with one toggle, respecting reduced-motion needs. A before-and-after slider shows the calm version. A focused accessibility build with a vivid demo for an evening.', 'Una extensión que detecta parallax, carruseles automáticos y efectos de scroll temblorosos en una página y te deja ralentizarlos o congelarlos con un interruptor, respetando las necesidades de movimiento reducido. Un control deslizante de antes y después muestra la versión calma. Un proyecto de accesibilidad enfocado con una demo vívida para una tarde.', 'web-frontend', '3-6h', 3, 6, 'intermediate', '["browser-extension","accessibility","animation"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Network Graph Explorer from a Pasted List of Connections', 'Explorador de grafo de red desde una lista de conexiones', 'Paste pairs of connected names and the tool lays them out as a force-directed graph you can drag, search, and prune, with node size scaling by connection count and a focus mode that fades everything but one neighborhood. The demo turns a flat list into an explorable map. A rich dataviz build for a day.', 'Pegá pares de nombres conectados y la herramienta los dispone como un grafo dirigido por fuerzas que podés arrastrar, buscar y podar, con nodos cuyo tamaño escala según las conexiones y un modo de foco que atenúa todo menos un vecindario. La demo convierte una lista plana en un mapa explorable. Un proyecto de visualización rico para un día.', 'web-frontend', '6-12h', 6, 12, 'intermediate', '["dataviz","animation"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Offline Field Survey PWA that Syncs When Signal Returns', 'PWA de encuestas de campo que sincroniza al volver la señal', 'A PWA for collecting survey responses in the field with no connection, queuing entries with photos and GPS locally, then syncing and showing a clear status when the signal returns. The hook is a reliable offline form that never loses a record. A practical 24-48h build with a real sync flow to demo.', 'Una PWA para recolectar respuestas de encuestas en el campo sin conexión, encolando entradas con fotos y GPS localmente, y luego sincronizando con un estado claro al volver la señal. El gancho es un formulario offline confiable que nunca pierde un registro. Un proyecto práctico de 24-48h con un flujo de sincronización real para demostrar.', 'web-frontend', '24-48h', 24, 48, 'advanced', '["pwa","real-time","ui-tooling"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Collaborative Mood Board that Reacts to Everyone in Real Time', 'Tablero de inspiración colaborativo en tiempo real', 'A shared canvas where a team drops images, swatches, and notes that snap into a clean grid, with live cursors, reactions, and a vote dot anyone can place. The hook is watching the board fill and reshuffle as the group works together. A polished real-time build with a strong group demo for a day.', 'Un lienzo compartido donde un equipo arroja imágenes, muestras de color y notas que se acomodan en una grilla limpia, con cursores en vivo, reacciones y un punto de voto que cualquiera puede colocar. El gancho es ver el tablero llenarse y reordenarse mientras el grupo trabaja junto. Un proyecto en tiempo real pulido con una buena demo grupal para un día.', 'web-frontend', '6-12h', 6, 12, 'intermediate', '["real-time","ui-tooling"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Idle Tycoon Game that Runs Entirely Offline as a PWA', 'Juego idle de tycoon que corre offline como PWA', 'An incremental clicker game packaged as an installable PWA that keeps simulating your factory while the tab is closed, then shows an animated catch-up reel of what you earned offline on return. The hook is the offline progress that makes the game feel alive. A juicy game-UI build for a full day.', 'Un juego clicker incremental empaquetado como PWA instalable que sigue simulando tu fábrica con la pestaña cerrada y, al volver, muestra una secuencia animada de lo que ganaste sin conexión. El gancho es el progreso offline que hace que el juego se sienta vivo. Un atractivo proyecto de UI de juegos para un día completo.', 'web-frontend', '6-12h', 6, 12, 'intermediate', '["pwa","game-ui","animation"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Contrast Fixer Extension that Auto-Repairs Unreadable Text', 'Extensión que repara automáticamente texto ilegible', 'A browser extension that scans a page for low-contrast text and one-by-one nudges colors to a readable ratio without breaking the design, showing each fix with a before-and-after swatch and the new score. The hook is making a washed-out site instantly legible. A high-value accessibility build for a half-day.', 'Una extensión que escanea una página en busca de texto de bajo contraste y ajusta los colores uno por uno a una proporción legible sin romper el diseño, mostrando cada arreglo con una muestra de antes y después y el nuevo puntaje. El gancho es volver legible al instante un sitio descolorido. Un proyecto de accesibilidad de alto valor para medio día.', 'web-frontend', '3-6h', 3, 6, 'intermediate', '["browser-extension","accessibility"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Race-Replay Visualizer that Animates Lap Times into a Chase', 'Visualizador que anima tiempos de vuelta como una carrera', 'Paste lap-time data for several racers and the tool animates them as dots chasing along a track, with a live leaderboard that reorders on every lap and a slider to scrub the race. The hook is feeling the overtakes happen instead of reading a table. A vivid animation build for an evening sprint.', 'Pegá datos de tiempos de vuelta de varios corredores y la herramienta los anima como puntos persiguiéndose en una pista, con una tabla de posiciones que se reordena en cada vuelta y un deslizador para navegar la carrera. El gancho es sentir los adelantamientos en vez de leer una tabla. Un proyecto de animación vívido para una tarde.', 'web-frontend', '6-12h', 6, 12, 'intermediate', '["dataviz","animation","game-ui"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Design Token Inspector that Reads Live Styles Off Any Page', 'Inspector de tokens que lee estilos de cualquier página', 'A browser extension that scans a live page and extracts its de-facto design tokens, the colors, spacing steps, font sizes, and radii actually in use, then shows them as a tidy palette you can copy as CSS variables. The hook is reverse-engineering a site''s system in one click. A handy dev build for a half-day.', 'Una extensión que escanea una página en vivo y extrae sus tokens de diseño de facto, los colores, pasos de espaciado, tamaños de fuente y radios realmente en uso, y los muestra como una paleta ordenada que podés copiar como variables CSS. El gancho es hacer ingeniería inversa del sistema de un sitio en un clic. Una práctica herramienta para medio día.', 'web-frontend', '3-6h', 3, 6, 'intermediate', '["browser-extension","ui-tooling"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Storyboard Animator that Tweens Between Hand-Drawn Frames', 'Animador de storyboard que interpola entre fotogramas', 'An in-browser tool where you sketch a few key frames on a canvas and it tweens smooth motion between them with adjustable easing, then plays the loop and exports a GIF or video. The hook is turning three rough drawings into a fluid animation in minutes. A creative animation build for an evening sprint.', 'Una herramienta en el navegador donde dibujás unos fotogramas clave en un lienzo y ella interpola un movimiento suave entre ellos con easing ajustable, luego reproduce el bucle y exporta un GIF o video. El gancho es convertir tres dibujos toscos en una animación fluida en minutos. Un proyecto de animación creativo para una tarde.', 'web-frontend', '6-12h', 6, 12, 'intermediate', '["animation","ui-tooling"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Touch Target Auditor that Highlights Tap Zones Too Small', 'Auditor de zonas táctiles que marca botones muy pequeños', 'A dev overlay that measures every button and link on a page against minimum touch-target sizes and paints the too-small ones red with their exact pixel size, plus an overlap warning where tap zones collide. The hook is seeing thumb-unfriendly UI light up at a glance. A precise accessibility build for a short sprint.', 'Una capa para desarrolladores que mide cada botón y enlace de una página contra los tamaños mínimos de zona táctil y pinta de rojo los demasiado chicos con su tamaño exacto en píxeles, más un aviso de solapamiento donde las zonas chocan. El gancho es ver de un vistazo la UI poco amigable para el dedo. Un proyecto de accesibilidad preciso para un sprint corto.', 'web-frontend', '1-3h', 1, 3, 'beginner', '["accessibility","ui-tooling"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Watch-Party Sync Room that Keeps Everyone on the Same Frame', 'Sala de watch-party que mantiene a todos en el mismo cuadro', 'A real-time room where friends paste a video link and play, pause, and seek in lockstep, with a side chat, synced reactions that float over the player, and a host control to round everyone back up. The hook is a buffer-proof shared timeline. A solid real-time build for a full day with a great group demo.', 'Una sala en tiempo real donde amigos pegan un enlace de video y reproducen, pausan y saltan al unísono, con un chat lateral, reacciones sincronizadas que flotan sobre el reproductor y un control del anfitrión para reagrupar a todos. El gancho es una línea de tiempo compartida a prueba de buffering. Un sólido proyecto en tiempo real para un día con gran demo grupal.', 'web-frontend', '6-12h', 6, 12, 'advanced', '["real-time","animation"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Full Game Jam Entry: A Co-op Browser Roguelite over a Link', 'Entrada de game jam: roguelite cooperativo por un enlace', 'A weekend-scale build of a small co-op roguelite that runs in the browser and is joined by a shared link: two players explore procedurally generated rooms, share loot, and revive each other, with a polished HUD, sound, and a run-summary screen. The hook is a complete, replayable loop you can show end to end.', 'Un proyecto de fin de semana de un pequeño roguelite cooperativo que corre en el navegador y se une por un enlace compartido: dos jugadores exploran salas generadas proceduralmente, comparten botín y se reviven, con un HUD pulido, sonido y una pantalla de resumen de partida. El gancho es un bucle completo y rejugable que podés mostrar de principio a fin.', 'web-frontend', '24-48h', 24, 48, 'advanced', '["game-ui","real-time","animation"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Polished Dashboard Kit: Real-Time Ops Wall for a Live Event', 'Kit de panel: muro de operaciones en vivo para un evento', 'A 48-hour build of a big-screen operations wall for a live event: real-time ticket flow, a venue heatmap, an alert ribbon, and animated counters, all fed by a mock live stream and arranged on a configurable grid the organizer can rearrange on the fly. The hook is a TV-ready command center you can demo running live.', 'Un proyecto de 48 horas de un muro de operaciones para pantalla grande en un evento en vivo: flujo de tickets en tiempo real, un mapa de calor del recinto, una cinta de alertas y contadores animados, alimentados por un stream simulado y dispuestos en una grilla configurable que el organizador reordena al vuelo. El gancho es un centro de comando listo para TV que podés demostrar en vivo.', 'web-frontend', '24-48h', 24, 48, 'advanced', '["dataviz","real-time","animation","ui-tooling"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Link Preview Card Generator that Mirrors Social Unfurls', 'Generador de tarjetas de previsualización de enlaces', 'Paste a URL and the tool fetches its metadata and renders pixel-accurate preview cards as they would appear on major social platforms, side by side, flagging missing images or truncated titles. The hook is seeing exactly how your link will unfurl everywhere before you post. A tidy UI-tooling build for a short sprint.', 'Pegá una URL y la herramienta obtiene sus metadatos y renderiza tarjetas de previsualización con precisión de píxel tal como aparecerían en las principales plataformas sociales, lado a lado, marcando imágenes faltantes o títulos cortados. El gancho es ver exactamente cómo se desplegará tu enlace antes de publicar. Un prolijo proyecto de herramientas de UI para un sprint corto.', 'web-frontend', '1-3h', 1, 3, 'beginner', '["ui-tooling"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Crowd Reaction Wall that Pulses with Live Audience Emojis', 'Muro de reacciones que late con emojis del público en vivo', 'A big-screen wall where an audience taps emojis on their phones and the reactions float up, cluster, and pulse in real time, with a running sentiment bar and bursts when a reaction spikes. Built for talks and streams. The hook is a room''s energy made visible instantly. A lively real-time build for a half-day.', 'Un muro para pantalla grande donde el público toca emojis en sus teléfonos y las reacciones flotan, se agrupan y laten en tiempo real, con una barra de sentimiento y estallidos cuando una reacción se dispara. Pensado para charlas y streams. El gancho es la energía de una sala hecha visible al instante. Un proyecto en tiempo real animado para medio día.', 'web-frontend', '3-6h', 3, 6, 'intermediate', '["real-time","animation","dataviz"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Alt-Text Coach that Drafts and Grades Image Descriptions', 'Asistente de texto alternativo que redacta y califica', 'A browser extension that finds images missing alt text on a page, drafts a concrete description for each, and grades existing alt text against good-practice rules, decorative versus meaningful, length, redundancy. The hook is fixing a page''s image accessibility in one guided pass. A focused build for an evening sprint.', 'Una extensión que encuentra imágenes sin texto alternativo en una página, redacta una descripción concreta para cada una y califica el texto existente contra reglas de buenas prácticas, decorativo versus significativo, longitud, redundancia. El gancho es arreglar la accesibilidad de imágenes de una página en un recorrido guiado. Un proyecto enfocado para una tarde.', 'web-frontend', '6-12h', 6, 12, 'intermediate', '["browser-extension","accessibility","ui-tooling"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Bezier Easing Lab that Compares Curves on Racing Squares', 'Laboratorio de curvas easing que compara con cuadrados', 'An interactive easing editor where you drag bezier handles and instantly race several squares across the screen to feel each curve side by side, with named presets and a copy-out snippet. The hook is choosing motion by watching it, not guessing numbers. A tight, playful animation-tooling build for a short sprint.', 'Un editor interactivo de easing donde arrastrás los manejadores bezier y al instante hacés correr varios cuadrados por la pantalla para sentir cada curva en paralelo, con presets nombrados y un fragmento para copiar. El gancho es elegir el movimiento mirándolo, no adivinando números. Un proyecto de herramientas de animación compacto y divertido para un sprint corto.', 'web-frontend', '1-3h', 1, 3, 'beginner', '["animation","ui-tooling"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Form Abandonment Replay that Shows Where Users Give Up', 'Repetición de abandono que muestra dónde se rinden', 'A dev tool that records anonymized interaction events on a form and replays an aggregated heatmap of where users hesitate, backtrack, or quit, field by field, with a drop-off funnel beside it. The hook is watching exactly which field kills your conversions. A useful dataviz build for a full day.', 'Una herramienta para desarrolladores que registra eventos de interacción anonimizados en un formulario y reproduce un mapa de calor agregado de dónde los usuarios dudan, retroceden o abandonan, campo por campo, con un embudo de caída al lado. El gancho es ver exactamente qué campo mata tus conversiones. Un proyecto de visualización útil para un día completo.', 'web-frontend', '6-12h', 6, 12, 'advanced', '["dataviz","ui-tooling"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Typing Race Arena where Players Sprint Through Live Text', 'Arena de tipeo donde los jugadores corren por un texto', 'A real-time multiplayer typing race where players join a link and sprint through the same passage, each shown as a car advancing with their words-per-minute, mistakes shaking the car, and a live podium. The hook is the head-to-head race that turns typing into a spectator sport. A fun real-time build for a half-day.', 'Una carrera de tipeo multijugador en tiempo real donde los jugadores entran por un enlace y corren por el mismo texto, cada uno mostrado como un auto que avanza con sus palabras por minuto, los errores sacuden el auto y hay un podio en vivo. El gancho es la carrera mano a mano que convierte el tipeo en deporte. Un proyecto en tiempo real divertido para medio día.', 'web-frontend', '3-6h', 3, 6, 'intermediate', '["real-time","game-ui"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Globe Visualizer that Arcs Connections Between Pasted Cities', 'Visualizador de globo que arquea conexiones entre ciudades', 'Paste pairs of city names and the tool plots them on a rotating 3D globe with glowing arcs animating between each pair, sized by a weight column, and a click to spin to any city. The hook is turning a flat connection list into a striking, presentation-ready globe. A polished dataviz build for an evening sprint.', 'Pegá pares de nombres de ciudades y la herramienta las ubica en un globo 3D rotatorio con arcos brillantes animándose entre cada par, dimensionados por una columna de peso, y un clic para girar hacia cualquier ciudad. El gancho es convertir una lista de conexiones plana en un globo llamativo y listo para presentar. Un pulido proyecto de visualización para una tarde.', 'web-frontend', '6-12h', 6, 12, 'intermediate', '["dataviz","animation"]');
INSERT INTO ideas (name, name_es, long_description, long_description_es, topic, time_bucket, min_hours, max_hours, difficulty, tags) VALUES ('Live Code Battle Arena where Spectators Vote on Solutions', 'Arena de batalla de código con votación del público', 'A real-time arena where two coders solve the same prompt in split editors while spectators watch both screens, see a live test pass-count race, and vote for the cleaner solution at the end. The hook is competitive coding turned into a watchable show. A meaty real-time build for a full day with a strong demo.', 'Una arena en tiempo real donde dos programadores resuelven el mismo desafío en editores divididos mientras los espectadores ven ambas pantallas, una carrera en vivo de tests aprobados y votan por la solución más limpia al final. El gancho es la programación competitiva vuelta espectáculo. Un sustancioso proyecto en tiempo real para un día con una buena demo.', 'web-frontend', '6-12h', 6, 12, 'advanced', '["real-time","game-ui"]');
